function mesh(geometry, material, position = [0, 0, 0], rotation = [0, 0, 0]) {
  const m = new THREE.Mesh(geometry, material);
  m.position.set(...position);
  m.rotation.set(...rotation);
  m.castShadow = true;
  m.receiveShadow = true;
  return m;
}

export class Character {
  constructor(scene, team = 'CT', { name = 'BOT', scale = 1 } = {}) {
    this.scene = scene;
    this.team = team;
    this.name = name;
    this.group = new THREE.Group();
    this.body = new THREE.Group();
    this.group.add(this.body);
    this.group.scale.setScalar(scale);

    const mats = teamMaterials[team] || teamMaterials.CT;

    // Legs
    this.legs = [];
    for (const side of [-1, 1]) {
      const hip = new THREE.Group();
      hip.position.set(side * 0.125, 0.9, 0);
      const thigh = mesh(geo.thigh, mats.uniform, [0, -0.2, 0]);
      hip.add(thigh);
      const knee = new THREE.Group();
      knee.position.y = -0.41;
      const shin = mesh(geo.shin, mats.uniform, [0, -0.19, 0]);
      const boot = mesh(geo.boot, shared.boot, [0, -0.43, 0.05]);
      knee.add(shin, boot);
      hip.add(knee);
      this.body.add(hip);
      this.legs.push({ hip, knee, side });
    }

    // Hips, torso, vest
    this.body.add(mesh(geo.hip, mats.uniform, [0, 0.95, 0]));
    const torso = mesh(geo.torso, mats.uniform, [0, 1.26, 0]);
    torso.scale.set(1.08, 1.06, 0.84);
    this.body.add(torso);
    this.body.add(mesh(geo.vest, mats.vest, [0, 1.28, 0.01]));
    for (let i = -1; i <= 1; i++) {
      this.body.add(mesh(geo.pouch, mats.vest, [i * 0.15, 1.22, 0.17]));
    }
    this.body.add(mesh(new THREE.BoxGeometry(0.42, 0.06, 0.32), shared.strap, [0, 1.49, 0]));

    // Head and headwear
    this.body.add(mesh(geo.neck, shared.skin, [0, 1.57, 0]));
    this.headGroup = new THREE.Group();
    this.headGroup.position.set(0, 1.69, 0);
    const head = mesh(geo.head, team === 'T' ? shared.skinDark : shared.skin);
    head.scale.set(0.92, 1.06, 0.95);
    this.headGroup.add(head);
    if (team === 'CT') {
      this.headGroup.add(mesh(geo.helmet, mats.helmet, [0, 0.035, 0]));
      this.headGroup.add(mesh(new THREE.BoxGeometry(0.22, 0.05, 0.06), mats.accent, [0, 0.06, 0.14]));
    } else {
      this.headGroup.add(mesh(geo.cap, mats.helmet, [0, 0.1, 0]));
      this.headGroup.add(mesh(geo.brim, mats.helmet, [0, 0.07, 0.14]));
      const mask = mesh(new THREE.SphereGeometry(0.15, 8, 6), mats.balaclava, [0, -0.01, 0]);
      mask.scale.set(0.94, 1.0, 0.95);
      this.headGroup.add(mask);
      // Eyes visible through the balaclava
      for (const side of [-1, 1]) {
        this.headGroup.add(mesh(new THREE.BoxGeometry(0.045, 0.022, 0.02), shared.eyes, [side * 0.055, 0.01, 0.137]));
      }
    }
    this.body.add(this.headGroup);

    // Arms
    this.arms = [];
    for (const side of [-1, 1]) {
      const shoulder = new THREE.Group();
      shoulder.position.set(side * 0.3, 1.44, 0);
      shoulder.rotation.z = side * -0.08;
      const upper = mesh(geo.upperArm, mats.uniform, [0, -0.16, 0]);
      const elbow = new THREE.Group();
      elbow.position.y = -0.33;
      const fore = mesh(geo.forearm, mats.uniform, [0, -0.14, 0]);
      const hand = mesh(geo.hand, shared.glove, [0, -0.29, 0]);
      elbow.add(fore, hand);
      shoulder.add(upper, elbow);
      this.body.add(shoulder);
      this.arms.push({ shoulder, elbow, side, hand });
    }
    // Shoulder patch
    this.body.add(mesh(new THREE.BoxGeometry(0.07, 0.1, 0.2), mats.accent, [-0.33, 1.48, 0]));

    // Backpack or radio
    if (team === 'T') {
      this.body.add(mesh(geo.pack, mats.vest, [0, 1.3, -0.21]));
    } else {
      this.body.add(mesh(new THREE.BoxGeometry(0.24, 0.3, 0.12), mats.vest, [0, 1.31, -0.21]));
      this.body.add(mesh(new THREE.CylinderGeometry(0.012, 0.012, 0.3, 4), shared.gunMetal, [0.08, 1.5, -0.22]));
    }

    // Rifle. The mount pivots between a lowered patrol pose and an aimed pose.
    this.weaponMount = new THREE.Group();
    this.weaponMount.position.set(0.14, 1.3, 0.18);
    this.rifle = new THREE.Group();
    const receiver = mesh(geo.receiver, shared.gunMetal, [0, 0, 0.16]);
    const barrel = mesh(geo.barrel, shared.gunSteel, [0, 0.015, 0.57], [Math.PI / 2, 0, 0]);
    const stock = mesh(geo.stock, shared.gunWood, [0, -0.01, -0.18]);
    const magazine = mesh(geo.magazine, shared.gunMetal, [0, -0.14, 0.12]);
    magazine.rotation.x = -0.28;
    const grip = mesh(geo.grip, shared.gunMetal, [0, -0.14, -0.02]);
    grip.rotation.x = 0.2;
    const sight = mesh(geo.sight, shared.gunSteel, [0, 0.085, 0.1]);
    const sightFront = mesh(new THREE.BoxGeometry(0.02, 0.055, 0.03), shared.gunSteel, [0, 0.08, 0.5]);
    this.rifle.add(receiver, barrel, stock, magazine, grip, sight, sightFront);
    this.muzzleFlash = new THREE.Mesh(geo.muzzle, new THREE.MeshBasicMaterial({
      color: 0xffd48a, transparent: true, opacity: 0.9, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide,
    }));
    this.muzzleFlash.position.set(0, 0.015, 0.84);
    this.muzzleFlash.rotation.x = Math.PI / 2;
    this.muzzleFlash.visible = false;
    this.rifle.add(this.muzzleFlash);
    this.weaponMount.add(this.rifle);
    this.body.add(this.weaponMount);

    this.group.traverse((obj) => {
      if (obj.isMesh) { obj.castShadow = true; obj.receiveShadow = true; }
    });

    this.phase = Math.random() * Math.PI * 2;
    this.flashTimer = 0;
    this.deadTime = 0;
    this.dead = false;
    this.aimBlend = 0;
    this.crouchBlend = 0;
    this.scene.add(this.group);
  }

  setPosition(x, y, z) {
    this.group.position.set(x, y, z);
  }

  setYaw(yaw) {
    this.group.rotation.y = yaw;
  }

  muzzle() {
    if (this.flashTimer <= 0) {
      this.flashTimer = 0.055;
      this.muzzleFlash.visible = true;
      this.muzzleFlash.rotation.z = Math.random() * Math.PI;
      this.muzzleFlash.scale.setScalar(0.8 + Math.random() * 0.7);
    }
  }

  reset() {
    this.dead = false;
    this.deadTime = 0;
    this.body.rotation.set(0, 0, 0);
    this.body.position.set(0, 0, 0);
    this.group.visible = true;
    this.flashTimer = 0;
    this.muzzleFlash.visible = false;
    this.aimBlend = 0;
    this.crouchBlend = 0;
    for (const leg of this.legs) { leg.hip.rotation.set(0, 0, 0); leg.knee.rotation.set(0, 0, 0); }
    for (const arm of this.arms) { arm.shoulder.rotation.set(0, 0, arm.side * -0.08); arm.elbow.rotation.set(0, 0, 0); }
  }

  setDead() {
    this.dead = true;
    this.deadTime = 0;
  }

  update(dt, state = {}) {
    const { speed = 0, crouched = false, aiming = false, grounded = true } = state;
    const moving = speed > 0.15;

    if (this.dead) {
      this.deadTime += dt;
      this.body.rotation.x = damp(this.body.rotation.x, -Math.PI / 2, 8, dt);
      this.body.position.y = damp(this.body.position.y, 0.18, 8, dt);
      this.group.visible = this.deadTime < 12;
      return;
    }

    this.aimBlend = damp(this.aimBlend, aiming ? 1 : 0, 10, dt);
    this.crouchBlend = damp(this.crouchBlend, crouched ? 1 : 0, 12, dt);

    if (moving && grounded) this.phase += dt * (2.5 + speed * 1.35);
    else this.phase += dt * 1.5;

    const walkAmp = moving ? clamp(speed / 6.5, 0.18, 1) : 0;
    const swing = Math.sin(this.phase) * 0.72 * walkAmp;
    for (const leg of this.legs) {
      const s = leg.side === 1 ? 1 : -1;
      const bend = this.crouchBlend * 0.5;
      leg.hip.rotation.x = swing * s - bend * 0.7;
      leg.knee.rotation.x = Math.max(0, -Math.sin(this.phase * 1 + (leg.side > 0 ? 0 : Math.PI))) * 0.65 * walkAmp + bend * 1.25;
    }

    const bob = moving ? Math.abs(Math.sin(this.phase * 2)) * 0.025 : Math.sin(this.phase * 0.8) * 0.006;
    this.body.position.y = bob - this.crouchBlend * 0.23;
    this.body.rotation.z = moving ? Math.sin(this.phase) * 0.012 : 0;

    // Arms: aiming raises the rifle; otherwise they swing with the legs.
    for (const arm of this.arms) {
      const s = arm.side === 1 ? 1 : -1;
      const aimPose = arm.side === 1 ? -1.42 : -1.28;
      const restPose = -swing * s * 0.55;
      arm.shoulder.rotation.x = restPose * (1 - this.aimBlend) + aimPose * this.aimBlend;
      arm.shoulder.rotation.z = arm.side * (-0.08 - this.aimBlend * 0.22);
      arm.elbow.rotation.x = (moving ? 0.28 : 0.08) * (1 - this.aimBlend) + (arm.side === 1 ? 0.55 : 1.0) * this.aimBlend;
    }
    this.weaponMount.rotation.x = (1 - this.aimBlend) * 0.72 - 0.02;
    this.weaponMount.rotation.y = (1 - this.aimBlend) * 0.18;
    this.weaponMount.position.y = 1.3 - this.crouchBlend * 0.05;

    this.headGroup.rotation.y = Math.sin(this.phase * 0.35) * (moving ? 0.05 : 0.16);
    this.headGroup.rotation.x = this.aimBlend * -0.04;

    if (this.flashTimer > 0) {
      this.flashTimer -= dt;
      if (this.flashTimer <= 0) this.muzzleFlash.visible = false;
    }
  }

  dispose() {
    this.scene.remove(this.group);
    this.group.traverse((obj) => {
      if (obj.isMesh && obj.geometry && !Object.values(geo).includes(obj.geometry)) obj.geometry.dispose();
      if (obj.isMesh && obj.material && obj.material !== shared.eyes) {
        if (obj.material.transparent && obj.material.map) obj.material.map.dispose();
      }
    });
  }
}

export function createHitSpheres(character, position) {
  return [
    { x: position.x, y: position.y + 1.7, z: position.z, radius: 0.21, part: 'head' },
    { x: position.x, y: position.y + 1.24, z: position.z, radius: 0.36, part: 'body' },
    { x: position.x, y: position.y + 0.72, z: position.z, radius: 0.35, part: 'legs' },
  ];
}

import * as THREE from 'three';
import { CONFIG } from '../core/config.js';
import { clamp, damp, rand } from '../core/utils.js';

const weaponMaterials = {
  metal: new THREE.MeshStandardMaterial({ color: 0x343831, roughness: 0.5, metalness: 0.4 }),
  steel: new THREE.MeshStandardMaterial({ color: 0x74786d, roughness: 0.36, metalness: 0.55 }),
  wood: new THREE.MeshStandardMaterial({ color: 0x674b2e, roughness: 0.82 }),
  glove: new THREE.MeshStandardMaterial({ color: 0x30322b, roughness: 0.95 }),
  sleeve: new THREE.MeshStandardMaterial({ color: 0x45534d, roughness: 0.95 }),
  brass: new THREE.MeshStandardMaterial({ color: 0xa78a4b, roughness: 0.4, metalness: 0.6 }),
};

function box(w, h, d, material, x = 0, y = 0, z = 0) {
  const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), material);
  m.position.set(x, y, z);
  return m;
}

function cylinder(radius, length, material, x, y, z) {
  const m = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius, length, 8), material);
  m.rotation.x = Math.PI / 2;
  m.position.set(x, y, z);
  return m;
}

class ViewWeapon {
  constructor(camera) {
    this.camera = camera;
    this.root = new THREE.Group();
    camera.add(this.root);
    this.rifle = new THREE.Group();
    this.pistol = new THREE.Group();
    this.buildRifle();
    this.buildPistol();
    this.root.add(this.rifle, this.pistol);
    this.root.position.set(0.34, -0.3, -0.58);
    this.recoil = 0;
    this.recoilVelocity = 0;
    this.bobPhase = 0;
    this.switchOffset = 0;
    this.flashTimer = 0;
    this.muzzleFlashes = [];
    this.rifle.visible = true;
    this.pistol.visible = false;
    this.current = 'rifle';
  }

  buildRifle() {
    const g = this.rifle;
    g.add(box(0.13, 0.15, 0.5, weaponMaterials.metal, 0, 0, -0.14));
    g.add(box(0.145, 0.1, 0.22, weaponMaterials.steel, 0, 0.01, -0.44));
    g.add(box(0.11, 0.11, 0.3, weaponMaterials.wood, 0, -0.01, 0.24));
    g.add(box(0.09, 0.24, 0.12, weaponMaterials.metal, 0, -0.16, -0.16));
    g.add(box(0.08, 0.21, 0.1, weaponMaterials.wood, 0, -0.15, 0.02));
    g.add(cylinder(0.025, 0.54, weaponMaterials.steel, 0, 0.025, -0.61));
    g.add(box(0.04, 0.08, 0.05, weaponMaterials.steel, 0, 0.09, -0.36));
    g.add(box(0.02, 0.07, 0.03, weaponMaterials.steel, 0, 0.095, -0.84));
    // Wood handguard detail
    g.add(box(0.16, 0.07, 0.38, weaponMaterials.wood, 0, -0.04, -0.42));
    // Charging handle and selector
    g.add(box(0.04, 0.04, 0.14, weaponMaterials.steel, 0.09, 0.05, -0.13));
    // Gloved hands and sleeves
    const rightHand = new THREE.Mesh(new THREE.SphereGeometry(0.085, 7, 6), weaponMaterials.glove);
    rightHand.position.set(0.02, -0.16, 0.07);
    rightHand.scale.set(0.9, 1.15, 1.1);
    g.add(rightHand);
    const leftHand = new THREE.Mesh(new THREE.SphereGeometry(0.08, 7, 6), weaponMaterials.glove);
    leftHand.position.set(-0.01, -0.1, -0.46);
    leftHand.scale.set(1.15, 0.9, 1.2);
    g.add(leftHand);
    const rightSleeve = new THREE.Mesh(new THREE.CapsuleGeometry(0.085, 0.36, 3, 7), weaponMaterials.sleeve);
    rightSleeve.position.set(0.1, -0.34, 0.3);
    rightSleeve.rotation.set(-0.85, 0.12, -0.3);
    g.add(rightSleeve);
    const leftSleeve = new THREE.Mesh(new THREE.CapsuleGeometry(0.08, 0.42, 3, 7), weaponMaterials.sleeve);
    leftSleeve.position.set(-0.16, -0.32, -0.18);
    leftSleeve.rotation.set(-0.95, -0.25, 0.55);
    g.add(leftSleeve);
    const flash = new THREE.Mesh(new THREE.PlaneGeometry(0.32, 0.32), new THREE.MeshBasicMaterial({
      color: 0xffcf7a, transparent: true, opacity: 0.95, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide,
    }));
    flash.position.set(0, 0.03, -0.91);
    flash.visible = false;
    g.add(flash);
    this.muzzleFlashes.push(flash);
    g.traverse((o) => { if (o.isMesh) { o.castShadow = false; o.receiveShadow = false; } });
  }

  buildPistol() {
    const g = this.pistol;
    g.add(box(0.09, 0.11, 0.42, weaponMaterials.metal, 0, 0.02, -0.12));
    g.add(box(0.075, 0.16, 0.09, weaponMaterials.wood, 0, -0.12, 0.06));
    g.add(cylinder(0.018, 0.15, weaponMaterials.steel, 0, 0.025, -0.39));
    g.add(box(0.035, 0.035, 0.04, weaponMaterials.steel, 0, 0.085, -0.3));
    const hand = new THREE.Mesh(new THREE.SphereGeometry(0.085, 7, 6), weaponMaterials.glove);
    hand.position.set(0, -0.12, 0.07);
    hand.scale.set(1, 1.2, 1);
    g.add(hand);
    const sleeve = new THREE.Mesh(new THREE.CapsuleGeometry(0.085, 0.4, 3, 7), weaponMaterials.sleeve);
    sleeve.position.set(0.1, -0.35, 0.26);
    sleeve.rotation.set(-0.9, 0.1, -0.35);
    g.add(sleeve);
    const flash = new THREE.Mesh(new THREE.PlaneGeometry(0.22, 0.22), new THREE.MeshBasicMaterial({
      color: 0xffd082, transparent: true, opacity: 0.9, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide,
    }));
    flash.position.set(0, 0.025, -0.5);
    flash.visible = false;
    g.add(flash);
    this.muzzleFlashes.push(flash);
    g.traverse((o) => { if (o.isMesh) { o.castShadow = false; o.receiveShadow = false; } });
  }

  setWeapon(id) {
    this.current = id;
    this.rifle.visible = id === 'rifle';
    this.pistol.visible = id === 'pistol';
    this.switchOffset = 1;
  }

  fire() {
    this.recoilVelocity += 3.4;
    const flash = this.muzzleFlashes[this.current === 'rifle' ? 0 : 1];
    if (flash) {
      flash.visible = true;
      flash.rotation.z = Math.random() * Math.PI;
      flash.scale.setScalar(0.8 + Math.random() * 0.6);
      this.flashTimer = 0.045;
    }
  }

  update(dt, state) {
    const speed = state.speed || 0;
    const moving = speed > 0.3 && state.grounded;
    this.bobPhase += dt * (moving ? 7 + speed * 0.9 : 1.5);
    const bobAmount = moving ? clamp(speed / 7, 0.2, 1) : 0.18;
    this.recoilVelocity *= Math.exp(-16 * dt);
    this.recoil = damp(this.recoil, 0, 14, dt);
    this.recoil += this.recoilVelocity * dt * 0.1;
    this.switchOffset = damp(this.switchOffset, 0, 12, dt);

    const reload = state.reloadProgress || 0;
    const reloadDip = reload > 0 ? Math.sin(Math.min(1, reload) * Math.PI) : 0;
    const x = 0.34 + Math.sin(this.bobPhase * 0.5) * 0.006 * bobAmount - reloadDip * 0.09;
    const y = -0.3 + Math.abs(Math.sin(this.bobPhase)) * 0.012 * bobAmount - reloadDip * 0.16 - this.switchOffset * 0.25;
    const z = -0.58 + this.recoil * 0.11 + reloadDip * 0.03;
    this.root.position.set(x, y, z);
    this.root.rotation.x = this.recoil * 0.03 - reloadDip * 0.25;
    this.root.rotation.y = Math.sin(this.bobPhase * 0.5) * 0.01 - reloadDip * 0.35;
    this.root.rotation.z = reloadDip * 0.25;

    if (this.flashTimer > 0) {
      this.flashTimer -= dt;
      if (this.flashTimer <= 0) {
        for (const flash of this.muzzleFlashes) flash.visible = false;
      }
    }
  }
}

export class Player {
  constructor({ scene, camera, world, audio, settings }) {
    this.scene = scene;
    this.camera = camera;
    this.world = world;
    this.audio = audio;
    this.settings = settings;
    this.position = new THREE.Vector3(0, 0, 0);
    this.velocity = new THREE.Vector3();
    this.yaw = 0;
    this.pitch = 0;
    this.health = CONFIG.player.maxHealth;
    this.armor = 100;
    this.alive = true;
    this.grounded = true;
    this.crouched = false;
    this.eye = CONFIG.player.standEye;
    this.recoilPitch = 0;
    this.recoilYaw = 0;
    this.stepDistance = 0;
    this.landKick = 0;
    this.world = world;
    this.weaponId = 'rifle';
    this.ammo = {
      rifle: { mag: CONFIG.weapons.rifle.magazine, reserve: CONFIG.weapons.rifle.reserve },
      pistol: { mag: CONFIG.weapons.pistol.magazine, reserve: CONFIG.weapons.pistol.reserve },
    };
    this.fireCooldown = 0;
    this.reloadTimer = 0;
    this.reloadTotal = 0;
    this.shots = 0;
    this.lastShot = 0;
    this.view = new ViewWeapon(camera);
    this.deathTimer = 0;
    this.respawnTimer = 0;
    this.lastDamageTime = -10;
    this.lastDamageDirection = new THREE.Vector3();
    this.stats = { kills: 0, deaths: 0, headshots: 0 };
    this.camera.rotation.order = 'YXZ';
    this.camera.fov = settings.get('fov');
    this.camera.updateProjectionMatrix();
    this.baseFov = settings.get('fov');
    this.currentSpread = 0;
    scene.add(camera);
  }

  get weapon() {
    return CONFIG.weapons[this.weaponId];
  }

  get currentAmmo() {
    return this.ammo[this.weaponId];
  }

  respawn(spawn, yaw = 0) {
    this.position.set(spawn.x, spawn.y ?? 0, spawn.z);
    this.velocity.set(0, 0, 0);
    this.yaw = yaw;
    this.pitch = 0;
    this.health = CONFIG.player.maxHealth;
    this.armor = 100;
    this.alive = true;
    this.grounded = true;
    this.crouched = false;
    this.eye = CONFIG.player.standEye;
    this.ammo.rifle = { mag: CONFIG.weapons.rifle.magazine, reserve: CONFIG.weapons.rifle.reserve };
    this.ammo.pistol = { mag: CONFIG.weapons.pistol.magazine, reserve: CONFIG.weapons.pistol.reserve };
    this.fireCooldown = 0;
    this.reloadTimer = 0;
    this.recoilPitch = 0;
    this.recoilYaw = 0;
    this.weaponId = 'rifle';
    this.view.setWeapon('rifle');
    this.view.root.visible = true;
    this.deathTimer = 0;
    this.respawnTimer = 0;
    this.updateCamera(0, 0);
  }

  look(dx, dy) {
    if (!this.alive) return;
    const sensitivity = this.settings.get('sensitivity') * 0.0021;
    this.yaw -= dx * sensitivity;
    this.pitch -= dy * sensitivity * (this.settings.get('invertY') ? -1 : 1);
    this.pitch = clamp(this.pitch, -1.35, 1.35);
  }

  update(dt, input) {
    if (!this.alive) {
      this.deathTimer += dt;
      this.respawnTimer -= dt;
      this.camera.position.y = damp(this.camera.position.y, this.position.y + 0.45, 3, dt);
      this.camera.rotation.x = damp(this.camera.rotation.x, -0.35, 3, dt);
      this.view.root.visible = false;
      return;
    }

    this.fireCooldown = Math.max(0, this.fireCooldown - dt);
    this.landKick = damp(this.landKick, 0, 9, dt);
    this.recoilPitch = damp(this.recoilPitch, 0, 7, dt);
    this.recoilYaw = damp(this.recoilYaw, 0, 7, dt);

    if (this.reloadTimer > 0) {
      this.reloadTimer -= dt;
      if (this.reloadTimer <= 0) this.finishReload();
    }

    const crouchWanted = Boolean(input.crouch);
    this.crouched = crouchWanted;
    const height = this.crouched ? CONFIG.player.crouchHeight : CONFIG.player.standHeight;

    const forward = new THREE.Vector3(-Math.sin(this.yaw), 0, -Math.cos(this.yaw));
    const right = new THREE.Vector3(Math.cos(this.yaw), 0, -Math.sin(this.yaw));
    const wish = new THREE.Vector3();
    if (input.forward) wish.add(forward);
    if (input.back) wish.sub(forward);
    if (input.right) wish.add(right);
    if (input.left) wish.sub(right);
    if (wish.lengthSq() > 0) wish.normalize();

    const sprinting = input.sprint && !this.crouched && (!input.back);
    let targetSpeed = this.crouched ? CONFIG.player.crouchSpeed : sprinting ? CONFIG.player.sprintSpeed : CONFIG.player.walkSpeed;
    if (this.reloadTimer > 0) targetSpeed *= 0.85;
    const accel = this.grounded ? CONFIG.player.accel : CONFIG.player.airAccel;
    const lerpAmount = 1 - Math.exp(-accel * dt);
    const desiredX = wish.x * targetSpeed;
    const desiredZ = wish.z * targetSpeed;
    this.velocity.x += (desiredX - this.velocity.x) * lerpAmount;
    this.velocity.z += (desiredZ - this.velocity.z) * lerpAmount;
    if (wish.lengthSq() === 0 && this.grounded) {
      const friction = Math.exp(-CONFIG.player.friction * dt);
      this.velocity.x *= friction;
      this.velocity.z *= friction;
    }

    // Jump
    if (input.jump && this.grounded) {
      this.velocity.y = CONFIG.player.jumpSpeed;
      this.grounded = false;
      if (this.audio) this.audio.footstep(true);
    }

    // Horizontal sweep, axis by axis. Step-height colliders are ignored.
    const step = CONFIG.player.stepHeight;
    const radius = CONFIG.player.radius;
    const feet = this.position.y;
    let nx = this.position.x + this.velocity.x * dt;
    if (!this.world.collidesCircle(nx, this.position.z, radius, feet + step, feet + height)) {
      this.position.x = nx;
    } else {
      this.velocity.x *= 0.1;
    }
    let nz = this.position.z + this.velocity.z * dt;
    if (!this.world.collidesCircle(this.position.x, nz, radius, feet + step, feet + height)) {
      this.position.z = nz;
    } else {
      this.velocity.z *= 0.1;
    }
    this.world.clampToBounds(this.position, radius);

    // Vertical integration and ground snapping.
    this.velocity.y -= CONFIG.player.gravity * dt;
    const newY = this.position.y + this.velocity.y * dt;
    const ground = this.world.groundAt(this.position.x, this.position.z, radius * 0.92, this.position.y + step + 0.05);
    if (this.grounded && this.position.y > ground + step + 0.02) {
      this.grounded = false;
    }
    if (newY <= ground + 0.001 && this.velocity.y <= 0) {
      if (!this.grounded && this.velocity.y < -4.5) {
        this.landKick = Math.min(0.11, Math.abs(this.velocity.y) * 0.012);
        if (this.audio) this.audio.footstep(true);
      }
      this.position.y = ground;
      this.velocity.y = 0;
      this.grounded = true;
    } else {
      this.position.y = newY;
      if (newY > ground + 0.02) this.grounded = false;
    }
    // Safety net: never fall out of the arena.
    if (this.position.y < -6) {
      this.position.y = 0;
      this.velocity.set(0, 0, 0);
    }
    if (this.grounded && Math.abs(this.velocity.x) + Math.abs(this.velocity.z) > 0.01) {
      this.stepDistance += Math.hypot(this.velocity.x, this.velocity.z) * dt;
      const stepInterval = sprinting || Math.hypot(this.velocity.x, this.velocity.z) > 5.5 ? 2.1 : 1.65;
      if (this.stepDistance > stepInterval) {
        this.stepDistance = 0;
        if (this.audio) this.audio.footstep(sprinting);
      }
    }

    // Smooth eye height and camera bob.
    const targetEye = this.crouched ? CONFIG.player.crouchEye : CONFIG.player.standEye;
    this.eye = damp(this.eye, targetEye, 13, dt);
    const bobSpeed = Math.hypot(this.velocity.x, this.velocity.z);
    const bob = this.grounded ? Math.sin(this.stepDistance * 7.5) * Math.min(0.045, bobSpeed * 0.006) : 0;
    const targetFov = this.baseFov + (sprinting && bobSpeed > 5.2 ? 3 : 0);
    this.camera.fov = damp(this.camera.fov, targetFov, 6, dt);
    this.camera.updateProjectionMatrix();
    this.updateCamera(dt, bob);

    const reloadProgress = this.reloadTimer > 0 ? 1 - this.reloadTimer / this.reloadTotal : 0;
    this.view.update(dt, {
      speed: bobSpeed,
      grounded: this.grounded,
      reloadProgress,
      crouched: this.crouched,
    });
    this.currentSpread = this.calculateSpread(bobSpeed);
  }

  updateCamera(dt, bob) {
    const shakeX = this.recoilYaw * 0.2;
    this.camera.position.set(this.position.x, this.position.y + this.eye + bob - this.landKick, this.position.z);
    this.camera.rotation.set(this.pitch + this.recoilPitch, this.yaw + shakeX, 0, 'YXZ');
  }

  calculateSpread(speed = 0) {
    const weapon = this.weapon;
    if (!weapon) return 0.01;
    let spread = weapon.spread;
    const horizontal = Math.hypot(this.velocity.x, this.velocity.z);
    spread += (horizontal / CONFIG.player.sprintSpeed) * weapon.movingSpread;
    if (!this.grounded) spread += 0.055;
    if (this.crouched) spread *= 0.7;
    spread += Math.min(this.shots * 0.0025, weapon.maxSpread);
    return spread;
  }

  canFire() {
    return this.alive && this.fireCooldown <= 0 && this.reloadTimer <= 0 && this.currentAmmo.mag > 0;
  }

  fire(game) {
    if (!this.alive || this.reloadTimer > 0 || this.fireCooldown > 0) return false;
    const ammo = this.currentAmmo;
    if (ammo.mag <= 0) {
      this.startReload();
      return false;
    }
    const weapon = this.weapon;
    ammo.mag--;
    this.fireCooldown = weapon.fireRate;
    this.shots = Math.min(this.shots + 1, 12);
    const spread = this.calculateSpread(Math.hypot(this.velocity.x, this.velocity.z));
    this.recoilPitch += weapon.recoil * (this.crouched ? 0.8 : 1);
    this.recoilYaw += rand(-1, 1) * weapon.recoil * 0.55;
    this.view.fire();
    game.playerShoot(this, weapon, spread);
    if (ammo.mag === 0) this.startReload();
    return true;
  }

  releaseTrigger() {
    this.shots = 0;
  }

  startReload() {
    if (this.reloadTimer > 0 || !this.alive) return false;
    const ammo = this.currentAmmo;
    const weapon = this.weapon;
    if (ammo.mag >= weapon.magazine || ammo.reserve <= 0) return false;
    this.reloadTotal = weapon.reloadTime;
    this.reloadTimer = this.reloadTotal;
    if (this.audio) this.audio.reload();
    this.shots = 0;
    return true;
  }

  finishReload() {
    const ammo = this.currentAmmo;
    const weapon = this.weapon;
    const needed = weapon.magazine - ammo.mag;
    const take = Math.min(needed, ammo.reserve);
    ammo.mag += take;
    ammo.reserve -= take;
    this.reloadTimer = 0;
  }

  switchWeapon(id) {
    if (!CONFIG.weapons[id] || id === this.weaponId || this.reloadTimer > 0 || !this.alive) return;
    this.weaponId = id;
    this.fireCooldown = Math.max(this.fireCooldown, 0.35);
    this.shots = 0;
    this.view.setWeapon(id);
    if (this.audio) this.audio.uiClick();
  }

  takeDamage(amount, attackerPosition, game) {
    if (!this.alive) return false;
    const previousArmor = this.armor;
    let remaining = amount;
    if (this.armor > 0) {
      const absorbed = Math.min(this.armor, remaining * 0.5);
      this.armor -= absorbed;
      remaining -= absorbed * 0.72;
    }
    this.health -= remaining;
    this.lastDamageTime = game.time;
    if (attackerPosition) {
      this.lastDamageDirection.set(attackerPosition.x - this.position.x, 0, attackerPosition.z - this.position.z).normalize();
    }
    if (this.audio) this.audio.hurt();
    if (this.health <= 0) {
      this.health = 0;
      this.alive = false;
      this.velocity.set(0, 0, 0);
      this.deathTimer = 0;
      this.respawnTimer = CONFIG.player.respawnTime;
      this.stats.deaths++;
      if (this.audio) this.audio.death();
      return true;
    }
    if (previousArmor <= 0 && this.armor <= 0) { /* armor already gone */ }
    return false;
  }

  dispose() {
    this.scene.remove(this.camera);
    this.view.root.traverse((obj) => {
      if (obj.isMesh) {
        obj.geometry.dispose();
        if (Array.isArray(obj.material)) obj.material.forEach((m) => m.dispose());
        else obj.material.dispose();
      }
    });
  }
}

import * as THREE from 'three';
import { Character } from '../entities/character.js';
import { CONFIG } from '../core/config.js';
import { clamp, damp, dampAngle, distance2D, rand, randInt } from '../core/utils.js';

const tempA = new THREE.Vector3();
const tempB = new THREE.Vector3();

// Finite-state tactical bot. Navigation and perception are real systems: every
// route comes from the map nav graph and every shot requires live line of sight.

export class Bot {
  constructor({ scene, world, nav, team, visualTeam, name, difficulty, mode, index, game }) {
    this.scene = scene;
    this.world = world;
    this.nav = nav;
    this.team = team;
    this.visualTeam = visualTeam;
    this.name = name;
    this.mode = mode;
    this.game = game;
    this.index = index;
    this.difficultyName = difficulty;
    this.character = new Character(scene, visualTeam, { name });
    this.position = new THREE.Vector3();
    this.velocity = new THREE.Vector3();
    this.yaw = Math.PI;
    this.health = 100;
    this.alive = true;
    this.grounded = true;
    this.state = 'patrol';
    this.stateTimer = rand(0, 2);
    this.respawnTimer = 0;
    this.path = [];
    this.pathGoal = null;
    this.pathTimer = 0;
    this.perceptionTimer = rand(0, 0.15);
    this.target = null;
    this.targetVisible = false;
    this.lastSeen = new THREE.Vector3();
    this.lastSeenAt = -100;
    this.reactionTimer = 0;
    this.fireTimer = rand(0.2, 0.8);
    this.burstRemaining = 0;
    this.burstPause = 0;
    this.turnSpeed = 8;
    this.crouched = false;
    this.stuckTimer = 0;
    this.stuckCheckTimer = 0;
    this.lastPosition = new THREE.Vector3();
    this.strafeDir = Math.random() > 0.5 ? 1 : -1;
    this.strafeTimer = rand(0.7, 1.6);
    this.patrolGoalNode = null;
    this.idleLook = 0;
    this.kills = 0;
    this.deaths = 0;
    this.headshots = 0;
    this.damageDealt = 0;
    this.aimPitch = 0;
    this.skill = {
      reaction: rand(0.85, 1.18),
      accuracy: rand(0.82, 1.18),
      aggression: rand(0.75, 1.25),
      perception: rand(0.9, 1.12),
    };
    this.currentSpeed = 0;
    this.deadTime = 0;
    this.footstepTimer = 0;
    this.lastNoise = new THREE.Vector3();
  }

  configure(difficulty, mode) {
    this.difficultyName = difficulty;
    this.mode = mode;
  }

  spawn(spawn) {
    this.position.set(spawn.x, spawn.y ?? 0, spawn.z);
    this.velocity.set(0, 0, 0);
    this.health = 100;
    this.alive = true;
    this.grounded = true;
    this.state = 'patrol';
    this.stateTimer = rand(0, 1.2);
    this.path = [];
    this.pathGoal = null;
    this.target = null;
    this.targetVisible = false;
    this.lastSeenAt = -100;
    this.reactionTimer = 0;
    this.burstRemaining = 0;
    this.respawnTimer = 0;
    this.deadTime = 0;
    this.stuckTimer = 0;
    this.character.reset();
    this.character.setPosition(spawn.x, spawn.y ?? 0, spawn.z);
    this.character.setYaw(this.yaw = Math.atan2(-spawn.x, -spawn.z));
    this.choosePatrolPath(true);
  }

  get eyePosition() {
    return tempA.set(this.position.x, this.position.y + 1.55, this.position.z);
  }

  get difficulty() {
    return CONFIG.difficulties[this.difficultyName] || CONFIG.difficulties.Normal;
  }

  isEnemy(entity) {
    if (!entity || entity === this || !entity.alive) return false;
    if (this.mode === 'ffa') return entity !== this;
    return entity.team !== this.team;
  }

  receiveAlert(position, sourceTeam) {
    if (!this.alive) return;
    if (this.mode !== 'ffa' && sourceTeam === this.team) return;
    if (this.state === 'engage') return;
    this.lastSeen.copy(position);
    this.lastSeenAt = this.game.time;
    this.state = 'investigate';
    this.stateTimer = rand(2.5, 4.5);
    this.path = this.nav.findPath(this.position, position) || [];
    this.pathTimer = 0.8;
  }

  hear(position, sourceTeam) {
    if (!this.alive || this.state === 'engage') return;
    if (distance2D(this.position, position) > 28) return;
    if (this.mode !== 'ffa' && sourceTeam === this.team) return;
    this.lastSeen.copy(position);
    this.lastSeenAt = this.game.time;
    if (this.state === 'patrol' || this.state === 'idle' || this.state === 'regroup') {
      this.state = 'investigate';
      this.stateTimer = rand(3, 5);
      this.path = this.nav.findPath(this.position, position) || [];
      this.pathTimer = 1;
    }
  }

  choosePatrolPath(initial = false) {
    const self = this.position;
    for (let attempt = 0; attempt < 8; attempt++) {
      let node = this.nav.randomNode();
      if (!node) return;
      if (distance2D(self, node) < (initial ? 8 : 12)) continue;
      const path = this.nav.findPath(self, node);
      if (path && path.length) {
        this.path = path;
        this.pathGoal = node;
        this.patrolGoalNode = node;
        this.pathTimer = 3;
        return;
      }
    }
    this.path = [];
  }

  chooseRetreatPath() {
    const threat = this.target && this.target.position ? this.target.position : this.position;
    const candidates = this.nav.nodes.filter((node) => distance2D(node, threat) > 16 && distance2D(node, this.position) > 3);
    const shuffled = candidates.sort(() => Math.random() - 0.5).slice(0, 8);
    for (const node of shuffled) {
      const path = this.nav.findPath(this.position, node);
      if (path && path.length) {
        this.path = path;
        this.pathGoal = node;
        this.pathTimer = 2;
        return true;
      }
    }
    return false;
  }

  faceTarget(target, dt, speed) {
    const dx = target.x - this.position.x;
    const dz = target.z - this.position.z;
    const desired = Math.atan2(dx, dz);
    this.yaw = dampAngle(this.yaw, desired, speed, dt);
  }

  faceMovement(dx, dz, dt) {
    if (Math.abs(dx) + Math.abs(dz) < 0.001) return;
    this.yaw = dampAngle(this.yaw, Math.atan2(dx, dz), 8, dt);
  }

  moveToward(point, speed, dt, allowSprint = false) {
    const dx = point.x - this.position.x;
    const dz = point.z - this.position.z;
    const distance = Math.hypot(dx, dz);
    if (distance < 0.08) return 0;
    const nx = dx / distance;
    const nz = dz / distance;
    const step = CONFIG.player.stepHeight;
    const radius = CONFIG.player.radius;
    let moveSpeed = speed;
    if (allowSprint && distance > 8) moveSpeed = Math.min(CONFIG.player.sprintSpeed * 0.86, speed * 1.35);
    const nextX = this.position.x + nx * moveSpeed * dt;
    const nextZ = this.position.z + nz * moveSpeed * dt;
    const feet = this.position.y;
    let moved = 0;
    if (!this.world.collidesCircle(nextX, this.position.z, radius, feet + step, feet + 1.7)) {
      moved += Math.abs(nextX - this.position.x);
      this.position.x = nextX;
    }
    if (!this.world.collidesCircle(this.position.x, nextZ, radius, feet + step, feet + 1.7)) {
      moved += Math.abs(nextZ - this.position.z);
      this.position.z = nextZ;
    }
    this.world.clampToBounds(this.position, radius);
    this.currentSpeed = moved / Math.max(dt, 0.001);
    this.faceMovement(nx, nz, dt);
    return distance;
  }

  followPath(dt, speed, allowSprint) {
    if (!this.path.length) return false;
    const point = this.path[0];
    const distance = Math.hypot(point.x - this.position.x, point.z - this.position.z);
    if (distance < 0.9) {
      this.path.shift();
      if (!this.path.length) return false;
    }
    this.moveToward(this.path[0], speed, dt, allowSprint);
    return true;
  }

  updateVertical(dt) {
    this.velocity.y -= 20 * dt;
    this.position.y += this.velocity.y * dt;
    const ground = this.world.groundAt(this.position.x, this.position.z, 0.34, this.position.y + CONFIG.player.stepHeight + 0.04);
    if (this.position.y <= ground + 0.001) {
      this.position.y = ground;
      this.velocity.y = 0;
      this.grounded = true;
    } else {
      this.grounded = false;
    }
    if (this.position.y < -5) {
      this.position.y = 0;
      this.velocity.y = 0;
    }
  }

  perceive(ctx) {
    const diff = this.difficulty;
    const eye = this.eyePosition.clone();
    const candidates = [];
    if (this.isEnemy(ctx.player)) candidates.push(ctx.player);
    for (const bot of ctx.bots) {
      if (bot !== this && bot.alive && this.isEnemy(bot)) candidates.push(bot);
    }

    let best = null;
    let bestScore = Infinity;
    const forwardX = Math.sin(this.yaw);
    const forwardZ = Math.cos(this.yaw);
    const range = diff.perception * this.skill.perception;

    for (const entity of candidates) {
      const targetPos = entity.position;
      const dx = targetPos.x - this.position.x;
      const dz = targetPos.z - this.position.z;
      const distance = Math.hypot(dx, dz);
      if (distance > range) continue;
      const dot = (dx * forwardX + dz * forwardZ) / Math.max(distance, 0.001);
      const inFov = dot > Math.cos((diff.fov * Math.PI / 180) / 2) || distance < 5;
      if (!inFov && entity !== this.target) continue;
      const chest = tempB.set(targetPos.x, targetPos.y + 1.2, targetPos.z);
      if (this.world.segmentBlocked(eye, chest)) continue;
      let score = distance;
      if (entity === this.target) score *= 0.7;
      if (entity.health < 40) score *= 0.8;
      if (score < bestScore) { bestScore = score; best = entity; }
    }

    if (best) {
      if (best !== this.target) {
        this.target = best;
        this.reactionTimer = rand(diff.reaction[0], diff.reaction[1]) * this.skill.reaction;
        this.burstRemaining = 0;
        this.lastSeen.copy(best.position);
        this.lastSeenAt = ctx.time;
      }
      this.targetVisible = true;
      this.lastSeen.copy(best.position);
      this.lastSeenAt = ctx.time;
      if (this.state !== 'engage' && this.state !== 'retreat') {
        if (this.health <= diff.retreatHealth && Math.random() < 0.45) {
          this.enterRetreat(ctx);
        } else {
          this.state = 'engage';
          this.stateTimer = 0;
          this.game.alertTeam(this, best);
        }
      }
    } else {
      this.targetVisible = false;
      if (this.target && !this.target.alive) this.target = null;
    }
  }

  enterRetreat(ctx) {
    this.state = 'retreat';
    this.stateTimer = rand(2.5, 4);
    this.chooseRetreatPath();
    this.game.alertTeam(this, this.target || { position: this.lastSeen });
  }

  handleCombat(dt, ctx) {
    const target = this.target;
    if (!target || !target.alive) {
      this.target = null;
      this.targetVisible = false;
      this.state = 'investigate';
      this.stateTimer = 3;
      return;
    }
    const diff = this.difficulty;
    const diffX = target.position.x - this.position.x;
    const diffZ = target.position.z - this.position.z;
    const distance = Math.hypot(diffX, diffZ);
    this.reactionTimer -= dt;
    this.faceTarget(target.position, dt, diff.turnSpeed);
    if (!this.targetVisible) {
      if (ctx.time - this.lastSeenAt > 1.4) {
        this.state = 'investigate';
        this.stateTimer = rand(3.5, 6);
        this.path = this.nav.findPath(this.position, this.lastSeen) || [];
        this.pathTimer = 1.2;
        this.target = null;
      }
      return;
    }

    // Keep a sensible fighting distance and strafe between bursts.
    this.strafeTimer -= dt;
    if (this.strafeTimer <= 0) {
      this.strafeTimer = rand(0.7, 1.8);
      this.strafeDir *= -1;
    }
    const preferred = 8 + (1 - diff.aggression) * 7;
    let moveSpeed = 0;
    if (distance > preferred + 2) {
      const pathReady = this.pathTimer <= 0 || !this.path.length;
      if (pathReady && distance > 16) {
        this.path = this.nav.findPath(this.position, target.position) || [];
        this.pathTimer = 0.8;
      }
      if (this.path.length) this.followPath(dt, 3.4, false);
      else this.moveToward(target.position, 3.4, dt, false);
      moveSpeed = this.currentSpeed;
    } else if (distance < preferred - 3) {
      const nx = -diffX / Math.max(distance, 0.001);
      const nz = -diffZ / Math.max(distance, 0.001);
      const strafe = (Math.sin(ctx.time * 1.7 + this.index) > 0 ? 1 : -1);
      const move = tempA.set(nx + (-nz) * strafe * 0.7, 0, nz + nx * strafe * 0.7).normalize();
      const speed = 2.6;
      const nextX = this.position.x + move.x * speed * dt;
      const nextZ = this.position.z + move.z * speed * dt;
      if (!this.world.collidesCircle(nextX, nextZ, 0.36, this.position.y + 0.44, this.position.y + 1.7)) {
        this.position.x = nextX; this.position.z = nextZ;
        this.currentSpeed = speed;
        moveSpeed = speed;
      }
    } else {
      // Lateral strafe
      const nx = -diffZ / Math.max(distance, 0.001);
      const nz = diffX / Math.max(distance, 0.001);
      const speed = 2.0 + this.skill.aggression;
      const nextX = this.position.x + nx * this.strafeDir * speed * dt;
      const nextZ = this.position.z + nz * this.strafeDir * speed * dt;
      if (!this.world.collidesCircle(nextX, nextZ, 0.36, this.position.y + 0.44, this.position.y + 1.7)) {
        this.position.x = nextX; this.position.z = nextZ;
        this.currentSpeed = speed;
        moveSpeed = speed;
      } else {
        this.strafeDir *= -1;
      }
    }

    // Shooting: reaction delay, aim cone and a live line-of-sight re-check.
    if (this.reactionTimer <= 0 && this.fireTimer <= 0) {
      const dx = target.position.x - this.position.x;
      const dz = target.position.z - this.position.z;
      const desiredYaw = Math.atan2(dx, dz);
      const aimError = Math.abs(((desiredYaw - this.yaw + Math.PI * 3) % (Math.PI * 2)) - Math.PI);
      if (aimError < 0.3 && this.world.segmentBlocked(this.eyePosition, tempB.set(target.position.x, target.position.y + 1.15, target.position.z)) === false) {
        if (this.burstRemaining <= 0) {
          this.burstRemaining = randInt(diff.burst[0], diff.burst[1]);
          this.fireTimer = 0.05;
        } else {
          this.game.botShoot(this, target, diff);
          this.character.muzzle();
          this.burstRemaining--;
          this.fireTimer = rand(0.11, 0.17);
          if (this.burstRemaining <= 0) this.fireTimer = rand(diff.burstPause[0], diff.burstPause[1]) * (1.2 - diff.accuracySkill * 0.4);
        }
      } else {
        this.fireTimer = 0.08;
      }
    }
    this.fireTimer = Math.max(0, this.fireTimer - dt);
    return moveSpeed;
  }

  update(dt, ctx) {
    if (!this.alive) {
      this.deadTime += dt;
      this.respawnTimer -= dt;
      this.character.update(dt, { aiming: false });
      if (this.respawnTimer <= 0) ctx.game.respawnBot(this);
      return;
    }

    const diff = this.difficulty;
    this.stateTimer -= dt;
    this.perceptionTimer -= dt;
    this.pathTimer -= dt;
    this.fireTimer = Math.max(0, this.fireTimer - dt);
    this.currentSpeed = 0;

    if (this.perceptionTimer <= 0) {
      this.perceptionTimer = rand(0.1, 0.19);
      this.perceive(ctx);
    }

    if (this.state === 'engage' && this.target) {
      this.handleCombat(dt, ctx);
    } else if (this.state === 'retreat') {
      if (this.path.length) this.followPath(dt, 4.9, true);
      else if (!this.chooseRetreatPath()) this.state = 'patrol';
      this.updateVertical(dt);
      if (this.stateTimer <= 0) {
        this.state = 'regroup';
        this.stateTimer = 4;
        this.path = [];
      }
    } else if (this.state === 'investigate') {
      if (this.path.length) {
        this.followPath(dt, 3.4, true);
      } else {
        this.currentSpeed = 0;
        this.idleLook += dt;
        this.yaw += Math.sin(this.idleLook * 1.8) * dt * 1.2;
      }
      this.updateVertical(dt);
      if (this.stateTimer <= 0) {
        this.state = 'patrol';
        this.choosePatrolPath();
      }
    } else if (this.state === 'regroup') {
      // Move toward the nearest living teammate, then resume patrolling.
      let ally = null, best = Infinity;
      for (const bot of ctx.bots) {
        if (bot !== this && bot.alive && bot.team === this.team) {
          const d = distance2D(bot.position, this.position);
          if (d < best) { best = d; ally = bot; }
        }
      }
      if (this.mode === 'ffa' || !ally || best < 5) {
        this.state = 'patrol';
        this.choosePatrolPath();
      } else {
        if (this.pathTimer <= 0 || !this.path.length) {
          this.path = this.nav.findPath(this.position, ally.position) || [];
          this.pathTimer = 1.4;
        }
        this.followPath(dt, 3.6, false);
        if (this.stateTimer <= 0) this.state = 'patrol';
      }
      this.updateVertical(dt);
    } else if (this.state === 'idle') {
      this.idleLook += dt;
      this.yaw += Math.sin(this.idleLook * 1.4) * dt * 0.8;
      this.moveToward = null;
      this.updateVertical(dt);
      if (this.stateTimer <= 0) {
        this.state = 'patrol';
        this.choosePatrolPath();
      }
    } else {
      // patrol
      if (!this.path.length) {
        if (this.stateTimer > 0) {
          this.state = 'idle';
          this.stateTimer = rand(0.8, 2.4);
          this.idleLook = 0;
        } else {
          this.choosePatrolPath();
          this.stateTimer = rand(8, 16);
        }
      } else {
        const hadPath = this.followPath(dt, 3.8, true);
        if (!hadPath) {
          this.state = 'idle';
          this.stateTimer = rand(0.7, 2.2);
          this.idleLook = 0;
        }
      }
      this.updateVertical(dt);
    }

    // Stuck recovery: re-route, then relocate to a valid node as a last resort.
    this.stuckCheckTimer += dt;
    if (this.stuckCheckTimer > 1) {
      const moved = distance2D(this.position, this.lastPosition);
      const wantMove = this.currentSpeed > 0.2;
      if (wantMove && moved < 0.3) this.stuckTimer += this.stuckCheckTimer;
      else this.stuckTimer = Math.max(0, this.stuckTimer - 0.5);
      this.lastPosition.copy(this.position);
      this.stuckCheckTimer = 0;
      if (this.stuckTimer > 1.8) {
        this.choosePatrolPath();
        this.stuckTimer = 0;
      }
      if (this.stuckTimer > 4.5) {
        const node = this.nav.nearestNode(this.position);
        if (node) {
          this.position.set(node.x, node.y, node.z);
          this.velocity.set(0, 0, 0);
          this.stuckTimer = 0;
          this.path = [];
        }
      }
    }

    // Separation so squads do not occupy the same space.
    for (const bot of ctx.bots) {
      if (bot === this || !bot.alive) continue;
      const dx = this.position.x - bot.position.x;
      const dz = this.position.z - bot.position.z;
      const d = Math.hypot(dx, dz);
      if (d > 0.01 && d < 0.85) {
        this.position.x += (dx / d) * (0.85 - d) * 0.5;
        this.position.z += (dz / d) * (0.85 - d) * 0.5;
      }
    }

    this.world.clampToBounds(this.position, 0.36);
    this.character.setPosition(this.position.x, this.position.y, this.position.z);
    this.character.setYaw(this.yaw);
    const aiming = this.state === 'engage' || this.state === 'investigate' || this.state === 'retreat';
    this.character.update(dt, {
      speed: this.currentSpeed,
      grounded: this.grounded,
      crouched: this.crouched,
      aiming,
    });
  }

  takeDamage(amount) {
    if (!this.alive) return false;
    this.health -= amount;
    if (this.health <= 0) {
      this.health = 0;
      this.alive = false;
      this.deadTime = 0;
      this.respawnTimer = 4.2;
      this.deaths++;
      this.target = null;
      this.targetVisible = false;
      this.state = 'respawn';
      this.character.setDead();
      return true;
    }
    return false;
  }

  dispose() {
    this.character.dispose();
  }
}

import { CONFIG, MAP_LIST, MODE_LIST, DIFFICULTY_LIST } from '../core/config.js';
import { settingsStore } from '../core/settings.js';
import { escapeHtml, formatTime } from '../core/utils.js';
import { audio } from '../audio/audio.js';

const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];

export class UI {
  constructor(game) {
    this.game = game;
    this.menu = $('#menu-screen');
    this.panelScreen = $('#panel-screen');
    this.hud = $('#hud');
    this.toastEl = $('#toast');
    this.toastTimer = 0;
    this.bannerTimer = 0;
    this.introTimer = 0;
    this.damageTimer = 0;
    this.hitmarkerTimer = 0;
    this.scoreboardVisible = false;
    this.pointerLocked = false;
    this.fps = 0;
    this.fpsAccumulator = 0;
    this.fpsFrames = 0;
    this.radarBg = null;
    this.radarBounds = null;
    this.mapRuntime = null;
    this.lastRadar = 0;
    this.matchData = null;
    this.bind();
  }

  bind() {
    // Main menu
    this.menu.addEventListener('click', (event) => {
      const button = event.target.closest('button[data-action]');
      if (!button) return;
      audio.init();
      audio.uiClick();
      const action = button.dataset.action;
      if (action === 'play') this.game.quickStart();
      else if (action === 'setup') this.openMatchSetup('OFFLINE MATCH');
      else if (action === 'servers') this.openOnlineInfo();
      else if (action === 'settings') this.openSettings();
      else if (action === 'profile') this.openProfile();
      else if (action === 'credits') this.openCredits();
    });

    this.panelScreen.addEventListener('click', (event) => {
      audio.init();
      const close = event.target.closest('[data-close]');
      if (close) {
        audio.uiClick();
        this.closePanel();
        return;
      }
      const button = event.target.closest('button[data-action]');
      if (!button) return;
      audio.uiClick();
      const action = button.dataset.action;
      if (action === 'start-match') this.startFromSetup();
      else if (action === 'save-settings') this.saveSettings();
      else if (action === 'reset-settings') this.resetSettings();
      else if (action === 'fullscreen') this.toggleFullscreen();
      else if (action === 'save-profile') this.saveProfile();
      else if (action === 'reset-profile') this.resetProfile();
      else if (action === 'offline-setup') { this.closePanel(); this.openMatchSetup('OFFLINE MATCH'); }
      else if (action === 'credits') this.openCredits();
    });

    this.panelScreen.addEventListener('keydown', (event) => {
      if (event.key === 'Escape') { event.stopPropagation(); this.closePanel(); }
    });

    this.hud.addEventListener('click', (event) => {
      const button = event.target.closest('button[data-action]');
      if (!button) return;
      audio.init();
      audio.uiClick();
      const action = button.dataset.action;
      if (action === 'resume') this.game.resume();
      else if (action === 'restart') this.game.restartMatch();
      else if (action === 'pause-settings') this.openSettings();
      else if (action === 'quit') this.game.leaveMatch();
      else if (action === 'play-again') this.game.restartMatch();
      else if (action === 'new-match') { this.hideResults(); this.game.leaveMatch(false); this.openMatchSetup('NEW MATCH'); }
      else if (action === 'main-menu') this.game.leaveMatch();
    });
  }

  // ---- menu and panels -----------------------------------------------------

  showMenu() {
    this.menu.classList.add('visible');
    this.hud.classList.add('hidden');
  }

  hideMenu() {
    this.menu.classList.remove('visible');
    this.hud.classList.remove('hidden');
  }

  showPanel(content, { wide = false } = {}) {
    this.panelScreen.innerHTML = `
      <div class="panel-backdrop" data-close></div>
      <div class="panel ${wide ? 'panel-wide' : ''}" role="dialog" aria-modal="true">
        <button class="panel-close" data-close aria-label="Close">&times;</button>
        ${content}
      </div>`;
    this.panelScreen.classList.add('visible');
    const first = this.panelScreen.querySelector('select, input, button:not(.panel-close)');
    if (first) setTimeout(() => first.focus(), 20);
  }

  closePanel() {
    this.panelScreen.classList.remove('visible');
    this.panelScreen.innerHTML = '';
  }

  openMatchSetup(title = 'OFFLINE MATCH') {
    audio.init();
    const previous = this.game.matchConfig || { mapId: 'old_quarter', mode: 'tdm', difficulty: 'Normal' };
    const team = settingsStore.profile.team || 'CT';
    const mapOptions = MAP_LIST.map((map) => `<option value="${map.id}" ${map.id === previous.mapId ? 'selected' : ''}>${map.name} — ${map.subtitle}</option>`).join('');
    const modeOptions = MODE_LIST.map((mode) => `<option value="${mode.id}" ${mode.id === previous.mode ? 'selected' : ''}>${mode.name}</option>`).join('');
    const difficultyOptions = DIFFICULTY_LIST.map((d) => `<option value="${d}" ${d === previous.difficulty ? 'selected' : ''}>${d.toUpperCase()}</option>`).join('');
    const map = CONFIG.maps[previous.mapId] || CONFIG.maps.old_quarter;
    this.showPanel(`
      <div class="panel-kicker">LOCAL OPERATIONS</div>
      <h2>${title}</h2>
      <p class="panel-sub">Offline match against map-aware bots. No connection required.</p>
      <div class="form-grid">
        <label class="field full">MAP
          <select id="cfg-map">${mapOptions}</select>
          <span class="field-hint" id="cfg-map-description">${map.description}</span>
        </label>
        <label class="field">GAME MODE<select id="cfg-mode">${modeOptions}</select></label>
        <label class="field">BOT DIFFICULTY<select id="cfg-difficulty">${difficultyOptions}</select></label>
        <label class="field">NUMBER OF BOTS<select id="cfg-bots">
          ${[4, 6, 8, 10, 12].map((n) => `<option value="${n}" ${n === (previous.botCount || 8) ? 'selected' : ''}>${n} bots</option>`).join('')}
        </select></label>
        <label class="field" id="team-field">YOUR TEAM<select id="cfg-team">
          <option value="CT" ${team === 'CT' ? 'selected' : ''}>Counter-Terrorists (CT)</option>
          <option value="T" ${team === 'T' ? 'selected' : ''}>Terrorists (T)</option>
        </select></label>
        <label class="field">MATCH LENGTH<select id="cfg-time">
          <option value="120" ${previous.timeLimit === 120 ? 'selected' : ''}>2 minutes</option>
          <option value="180" ${previous.timeLimit === 180 || !previous.timeLimit ? 'selected' : ''}>3 minutes</option>
          <option value="300" ${previous.timeLimit === 300 ? 'selected' : ''}>5 minutes</option>
        </select></label>
        <label class="field">SCORE LIMIT<select id="cfg-score">
          <option value="15" ${previous.scoreLimit === 15 ? 'selected' : ''}>15 kills</option>
          <option value="25" ${previous.scoreLimit === 25 || !previous.scoreLimit ? 'selected' : ''}>25 kills</option>
          <option value="40" ${previous.scoreLimit === 40 ? 'selected' : ''}>40 kills</option>
        </select></label>
      </div>
      <div class="mode-note" id="cfg-mode-note">First team to the score limit or the highest team score at time-up wins.</div>
      <div class="panel-actions">
        <button data-close>CANCEL</button>
        <button class="accent" data-action="start-match">START MATCH</button>
      </div>`);
    const mapSelect = $('#cfg-map');
    mapSelect.addEventListener('change', () => {
      const selected = CONFIG.maps[mapSelect.value];
      $('#cfg-map-description').textContent = selected.description;
    });
    const modeSelect = $('#cfg-mode');
    const updateMode = () => {
      const isFFA = modeSelect.value === 'ffa';
      $('#team-field').style.opacity = isFFA ? '0.4' : '1';
      $('#cfg-team').disabled = isFFA;
      $('#cfg-mode-note').textContent = isFFA
        ? 'Every participant competes independently. Highest individual score wins.'
        : 'First team to the score limit or the highest team score at time-up wins.';
    };
    modeSelect.addEventListener('change', updateMode);
    updateMode();
  }

  startFromSetup() {
    const mapId = $('#cfg-map')?.value || 'old_quarter';
    const mode = $('#cfg-mode')?.value || 'tdm';
    const difficulty = $('#cfg-difficulty')?.value || 'Normal';
    const botCount = Number($('#cfg-bots')?.value || 8);
    const team = mode === 'ffa' ? 'CT' : ($('#cfg-team')?.value || 'CT');
    const timeLimit = Number($('#cfg-time')?.value || 180);
    const scoreLimit = Number($('#cfg-score')?.value || 25);
    this.closePanel();
    this.game.startMatch({ mapId, mode, botCount, difficulty, team, timeLimit, scoreLimit });
  }

  openSettings() {
    audio.init();
    const s = settingsStore.get();
    this.showPanel(`
      <div class="panel-kicker">CONFIGURATION</div>
      <h2>SETTINGS</h2>
      <p class="panel-sub">Changes are applied immediately and saved on this device.</p>
      <div class="settings-section">
        <h3>CONTROLS</h3>
        <label class="field slider-field">MOUSE SENSITIVITY <output id="out-sensitivity">${s.sensitivity.toFixed(2)}</output>
          <input id="set-sensitivity" type="range" min="0.15" max="2.5" step="0.05" value="${s.sensitivity}">
        </label>
        <label class="field slider-field">FIELD OF VIEW <output id="out-fov">${Math.round(s.fov)}&deg;</output>
          <input id="set-fov" type="range" min="62" max="95" step="1" value="${s.fov}">
        </label>
        <label class="check-field"><input id="set-invert" type="checkbox" ${s.invertY ? 'checked' : ''}> INVERT MOUSE Y-AXIS</label>
      </div>
      <div class="settings-section">
        <h3>AUDIO</h3>
        <label class="field slider-field">MASTER VOLUME <output id="out-master">${Math.round(s.masterVolume * 100)}%</output>
          <input id="set-master" type="range" min="0" max="1" step="0.05" value="${s.masterVolume}">
        </label>
        <label class="field slider-field">EFFECTS VOLUME <output id="out-effects">${Math.round(s.effectsVolume * 100)}%</output>
          <input id="set-effects" type="range" min="0" max="1" step="0.05" value="${s.effectsVolume}">
        </label>
        <label class="field slider-field">MUSIC VOLUME <output id="out-music">${Math.round(s.musicVolume * 100)}%</output>
          <input id="set-music" type="range" min="0" max="1" step="0.05" value="${s.musicVolume}">
        </label>
      </div>
      <div class="settings-section">
        <h3>VIDEO</h3>
        <div class="form-grid compact">
          <label class="field">GRAPHICS QUALITY<select id="set-quality">
            ${['low', 'medium', 'high'].map((q) => `<option value="${q}" ${s.quality === q ? 'selected' : ''}>${q.toUpperCase()}</option>`).join('')}
          </select></label>
          <label class="field">SHADOWS<select id="set-shadows">
            <option value="on" ${s.shadows ? 'selected' : ''}>ENABLED</option>
            <option value="off" ${!s.shadows ? 'selected' : ''}>DISABLED</option>
          </select></label>
          <label class="field slider-field full">RENDER SCALE <output id="out-resolution">${Math.round(s.resolutionScale * 100)}%</output>
            <input id="set-resolution" type="range" min="0.6" max="1.25" step="0.05" value="${s.resolutionScale}">
          </label>
          <label class="field">CROSSHAIR COLOR<input id="set-crosshair" type="color" value="${s.crosshairColor}"></label>
          <label class="check-field"><input id="set-fps" type="checkbox" ${s.showFps ? 'checked' : ''}> SHOW FRAME-RATE COUNTER</label>
        </div>
        <button class="inline-button" data-action="fullscreen">TOGGLE FULLSCREEN</button>
      </div>
      <div class="panel-actions">
        <button data-close>CANCEL</button>
        <button data-action="reset-settings">RESET DEFAULTS</button>
        <button class="accent" data-action="save-settings">APPLY &amp; SAVE</button>
      </div>`);
    const bindOutput = (id, output, format = (v) => v) => {
      const input = $(id);
      input?.addEventListener('input', () => { if (output) $(output).textContent = format(input.value); });
    };
    bindOutput('#set-sensitivity', '#out-sensitivity', (v) => Number(v).toFixed(2));
    bindOutput('#set-fov', '#out-fov', (v) => `${Math.round(v)}°`);
    bindOutput('#set-master', '#out-master', (v) => `${Math.round(v * 100)}%`);
    bindOutput('#set-effects', '#out-effects', (v) => `${Math.round(v * 100)}%`);
    bindOutput('#set-music', '#out-music', (v) => `${Math.round(v * 100)}%`);
    bindOutput('#set-resolution', '#out-resolution', (v) => `${Math.round(v * 100)}%`);
  }

  saveSettings() {
    settingsStore.update({
      sensitivity: Number($('#set-sensitivity').value),
      fov: Number($('#set-fov').value),
      invertY: $('#set-invert').checked,
      masterVolume: Number($('#set-master').value),
      effectsVolume: Number($('#set-effects').value),
      musicVolume: Number($('#set-music').value),
      quality: $('#set-quality').value,
      shadows: $('#set-shadows').value === 'on',
      resolutionScale: Number($('#set-resolution').value),
      showFps: $('#set-fps').checked,
      crosshairColor: $('#set-crosshair').value,
    });
    audio.init();
    audio.setVolumes();
    this.game.applySettings();
    this.closePanel();
    this.toast('SETTINGS SAVED');
  }

  resetSettings() {
    settingsStore.reset();
    this.game.applySettings();
    this.toast('DEFAULTS RESTORED');
    this.openSettings();
  }

  toggleFullscreen() {
    if (!document.fullscreenElement) {
      document.documentElement.requestFullscreen?.().catch(() => this.toast('FULLSCREEN WAS BLOCKED BY THE BROWSER'));
    } else {
      document.exitFullscreen?.().catch(() => {});
    }
  }

  openProfile() {
    const profile = settingsStore.profile;
    const kd = profile.deaths > 0 ? (profile.kills / profile.deaths).toFixed(2) : profile.kills.toFixed(2);
    const winRate = profile.matches > 0 ? Math.round((profile.wins / profile.matches) * 100) : 0;
    this.showPanel(`
      <div class="panel-kicker">OPERATOR DOSSIER</div>
      <h2>PLAYER PROFILE</h2>
      <p class="panel-sub">Career statistics are stored locally on this device.</p>
      <div class="profile-layout">
        <div class="profile-identity">
          <div class="profile-patch">${escapeHtml(profile.name.slice(0, 2).toUpperCase())}</div>
          <label class="field full">CALLSIGN<input id="profile-name" maxlength="18" value="${escapeHtml(profile.name)}"></label>
          <label class="field full">PREFERRED TEAM<select id="profile-team">
            <option value="CT" ${profile.team === 'CT' ? 'selected' : ''}>Counter-Terrorists</option>
            <option value="T" ${profile.team === 'T' ? 'selected' : ''}>Terrorists</option>
          </select></label>
          <div class="profile-rank">FIELD OPERATIVE <span>LOCAL RECORD</span></div>
        </div>
        <div class="profile-stats">
          <div><strong>${profile.matches}</strong><span>MATCHES</span></div>
          <div><strong>${profile.wins}</strong><span>WINS</span></div>
          <div><strong>${winRate}%</strong><span>WIN RATE</span></div>
          <div><strong>${profile.kills}</strong><span>TOTAL KILLS</span></div>
          <div><strong>${profile.deaths}</strong><span>DEATHS</span></div>
          <div><strong>${kd}</strong><span>K/D RATIO</span></div>
        </div>
      </div>
      <p class="profile-note">Callsigns and settings persist through browser reloads using local storage.</p>
      <div class="panel-actions">
        <button data-action="reset-profile" class="danger-quiet">RESET RECORD</button>
        <button data-action="save-profile" class="accent">SAVE PROFILE</button>
      </div>`);
  }

  saveProfile() {
    const name = ($('#profile-name').value.trim() || 'Operator').slice(0, 18);
    const team = $('#profile-team').value;
    settingsStore.updateProfile({ name, team });
    this.game.player.name = name;
    this.closePanel();
    this.toast('PROFILE SAVED');
  }

  resetProfile() {
    settingsStore.resetProfile();
    this.openProfile();
    this.toast('CAREER RECORD RESET');
  }

  openCredits() {
    this.showPanel(`
      <div class="panel-kicker">ABOUT THIS BUILD</div>
      <h2>CREDITS</h2>
      <div class="credits-body">
        <p><b>TACTICAL FPS — CLASSIC COMBAT</b><br>Build 2.0.0 &bull; Original browser game</p>
        <p>An offline-first tactical shooter inspired by the feel of early-2000s PC shooters. All maps, textures, models, animation, audio and interface artwork in this project are generated procedurally or authored specifically for it. No Counter-Strike, Combat Online or other commercial game assets are included.</p>
        <p><b>ENGINE</b><br>Three.js &bull; WebGL2 &bull; Vite</p>
        <p><b>SYSTEMS</b><br>Procedural map construction &bull; A* navigation graph &bull; finite-state tactical AI &bull; hit-scan ballistics &bull; procedural character animation &bull; generated WebAudio effects</p>
        <p class="muted">Third-party software: Three.js (MIT), Vite (MIT). See package licenses for details.</p>
      </div>
      <div class="panel-actions"><button data-close>CLOSE</button></div>`);
  }

  openOnlineInfo() {
    this.showPanel(`
      <div class="panel-kicker">NETWORK STATUS</div>
      <h2>ONLINE MULTIPLAYER</h2>
      <div class="status-banner unavailable"><span class="status-dot"></span> ONLINE SERVICES UNAVAILABLE</div>
      <div class="credits-body">
        <p>This build is a complete <b>offline</b> game. It does not contain a lobby server or an authoritative networking backend, so online matchmaking and remote players are not available.</p>
        <p>No fake server list is shown and no bots are presented as human players. Every opponent in a match is clearly a local computer-controlled bot.</p>
        <p>The offline game includes two maps, Team Deathmatch, Free For All, three bot difficulties, full match scoring and saved preferences.</p>
      </div>
      <div class="panel-actions">
        <button data-close>BACK</button>
        <button class="accent" data-action="offline-setup">PLAY OFFLINE</button>
      </div>`);
  }

  // ---- toast and notifications --------------------------------------------

  toast(message, duration = 2300) {
    this.toastEl.textContent = message;
    this.toastEl.classList.add('show');
    clearTimeout(this.toastTimer);
    this.toastTimer = setTimeout(() => this.toastEl.classList.remove('show'), duration);
  }

  banner(message, duration = 2400) {
    const el = $('#objective-banner');
    el.textContent = message;
    el.classList.add('show');
    clearTimeout(this.bannerTimer);
    this.bannerTimer = setTimeout(() => { el.textContent = ''; el.classList.remove('show'); }, duration);
  }

  showIntro(mapName, modeName) {
    const intro = $('#match-intro');
    $('#intro-map').textContent = mapName;
    $('#intro-mode').textContent = modeName;
    intro.classList.remove('hidden');
    intro.classList.add('show');
    clearTimeout(this.introTimer);
    this.introTimer = setTimeout(() => {
      intro.classList.remove('show');
      setTimeout(() => intro.classList.add('hidden'), 350);
    }, 2400);
  }

  // ---- HUD -----------------------------------------------------------------

  setMap(mapRuntime) {
    this.mapRuntime = mapRuntime;
    this.buildRadarBackground();
  }

  buildRadarBackground() {
    if (!this.mapRuntime) return;
    const bounds = this.mapRuntime.world.bounds;
    this.radarBounds = bounds;
    const size = 200;
    const canvas = document.createElement('canvas');
    canvas.width = canvas.height = size;
    const ctx = canvas.getContext('2d');
    ctx.fillStyle = 'rgba(8, 18, 14, 0.74)';
    ctx.fillRect(0, 0, size, size);
    const scale = 176 / Math.max(bounds.maxX - bounds.minX, bounds.maxZ - bounds.minZ);
    const cx = (bounds.minX + bounds.maxX) / 2;
    const cz = (bounds.minZ + bounds.maxZ) / 2;
    const tx = (x) => size / 2 + (x - cx) * scale;
    const tz = (z) => size / 2 + (z - cz) * scale;
    for (const c of this.mapRuntime.world.colliders) {
      if (c.minY > 3 || c.maxY < 0.3) continue;
      const w = (c.maxX - c.minX) * scale;
      const h = (c.maxZ - c.minZ) * scale;
      if (w < 0.5 && h < 0.5) continue;
      ctx.fillStyle = c.maxY > 2 ? 'rgba(128, 134, 115, 0.34)' : 'rgba(149, 137, 105, 0.26)';
      ctx.fillRect(tx(c.minX), tz(c.minZ), Math.max(0.7, w), Math.max(0.7, h));
    }
    ctx.strokeStyle = 'rgba(206, 199, 164, 0.35)';
    ctx.lineWidth = 1.5;
    ctx.strokeRect(tx(bounds.minX), tz(bounds.minZ), (bounds.maxX - bounds.minX) * scale, (bounds.maxZ - bounds.minZ) * scale);
    this.radarBg = canvas;
  }

  updateRadar(game) {
    if (!this.radarBg || !this.mapRuntime) return;
    const canvas = $('#radar');
    const ctx = canvas.getContext('2d');
    const size = canvas.width;
    ctx.clearRect(0, 0, size, size);
    ctx.save();
    ctx.beginPath();
    ctx.arc(size / 2, size / 2, size / 2 - 4, 0, Math.PI * 2);
    ctx.clip();
    ctx.drawImage(this.radarBg, 0, 0, size, size);
    const bounds = this.radarBounds;
    const scale = (176 / Math.max(bounds.maxX - bounds.minX, bounds.maxZ - bounds.minZ)) * (size / 200);
    const cx = (bounds.minX + bounds.maxX) / 2;
    const cz = (bounds.minZ + bounds.maxZ) / 2;
    const tx = (x) => size / 2 + (x - cx) * scale;
    const tz = (z) => size / 2 + (z - cz) * scale;
    const player = game.player;
    const px = tx(player.position.x);
    const py = tz(player.position.z);

    // View cone
    const yaw = player.yaw;
    const angle = Math.atan2(Math.cos(yaw), -Math.sin(yaw));
    ctx.fillStyle = 'rgba(196, 207, 167, 0.12)';
    ctx.beginPath();
    ctx.moveTo(px, py);
    ctx.arc(px, py, 26, angle - 0.48, angle + 0.48);
    ctx.closePath();
    ctx.fill();

    for (const bot of game.bots) {
      if (!bot.alive) continue;
      const enemy = game.isEnemy(player, bot);
      const x = tx(bot.position.x);
      const y = tz(bot.position.z);
      if (Math.hypot(x - size / 2, y - size / 2) > size / 2 - 7) continue;
      ctx.beginPath();
      ctx.fillStyle = enemy ? '#d2674f' : '#6ea4ba';
      ctx.shadowColor = enemy ? 'rgba(210,103,79,.8)' : 'rgba(110,164,186,.8)';
      ctx.shadowBlur = 5;
      ctx.arc(x, y, enemy ? 3.6 : 3, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.shadowBlur = 0;
    // Player arrow
    ctx.save();
    ctx.translate(px, py);
    ctx.rotate(angle + Math.PI / 2);
    ctx.fillStyle = '#e3d7aa';
    ctx.beginPath();
    ctx.moveTo(0, -6);
    ctx.lineTo(4.2, 4.5);
    ctx.lineTo(0, 2.5);
    ctx.lineTo(-4.2, 4.5);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
    ctx.restore();
    ctx.strokeStyle = 'rgba(216, 207, 172, 0.34)';
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.arc(size / 2, size / 2, size / 2 - 4, 0, Math.PI * 2);
    ctx.stroke();
  }

  updateHUD(game) {
    if (!game.active) return;
    const player = game.player;
    $('#round-mode').textContent = game.modeDef.name;
    $('#round-clock').textContent = formatTime(game.timeLeft);
    $('#round-state').textContent = game.matchPoint ? 'MATCH POINT' : 'LIVE';
    $('#round-state').classList.toggle('match-point', Boolean(game.matchPoint));
    $('#health-value').textContent = Math.max(0, Math.ceil(player.health));
    $('#armor-value').textContent = Math.max(0, Math.ceil(player.armor));
    $('#health-value').classList.toggle('critical', player.health <= 30);
    const weapon = player.weapon;
    $('#weapon-name').textContent = weapon ? weapon.name : '—';
    $('#ammo-value').textContent = player.currentAmmo.mag;
    $('#reserve-value').textContent = player.currentAmmo.reserve;
    $('#ammo-value').classList.toggle('empty', player.currentAmmo.mag === 0);
    $('#match-mode-label').textContent = game.modeDef.name;

    if (game.mode === 'tdm') {
      $('#left-team-label').textContent = 'CT';
      $('#right-team-label').textContent = 'T';
      $('#ct-score').textContent = game.scores.CT;
      $('#t-score').textContent = game.scores.T;
      $('#match-score-label').textContent = `${game.scores.CT} – ${game.scores.T}`;
    } else {
      const sorted = game.getSortedParticipants();
      const playerPlace = sorted.findIndex((p) => p.isPlayer) + 1;
      const leader = sorted[0];
      $('#left-team-label').textContent = 'YOU';
      $('#right-team-label').textContent = 'LEADER';
      $('#ct-score').textContent = game.player.stats.kills;
      $('#t-score').textContent = leader ? leader.kills : 0;
      $('#match-score-label').textContent = `RANK ${playerPlace} / ${sorted.length}`;
    }

    const respawn = $('#respawn-panel');
    if (!player.alive && game.active && !game.results) {
      respawn.classList.remove('hidden');
      $('#respawn-count').textContent = Math.max(0, Math.ceil(player.respawnTimer));
      $('#respawn-killer').textContent = game.lastDeathMessage || 'RESPAWNING';
    } else {
      respawn.classList.add('hidden');
    }

    const prompt = $('#pointer-prompt');
    const shouldPrompt = game.active && !game.paused && !game.results && !this.pointerLocked && player.alive;
    prompt.classList.toggle('hidden', !shouldPrompt);
  }

  updateCrosshair(game) {
    const crosshair = $('#crosshair');
    const spread = Math.min(26, 4 + (game.player.currentSpread || 0) * 260);
    crosshair.style.setProperty('--spread', `${spread.toFixed(1)}px`);
  }

  setPointerLocked(locked) {
    this.pointerLocked = locked;
    if (this.game.active) this.updatePrompt();
  }

  updatePrompt() {
    const game = this.game;
    const shouldPrompt = game.active && !game.paused && !game.results && !this.pointerLocked && game.player.alive;
    $('#pointer-prompt').classList.toggle('hidden', !shouldPrompt);
  }

  setFps(fps) {
    this.fps = fps;
    const el = $('#fps-counter');
    const show = settingsStore.get('showFps');
    el.classList.toggle('hidden', !show);
    if (show) el.textContent = `FPS ${Math.round(fps)}`;
  }

  feed(killer, victim, killerTeam, victimTeam, headshot) {
    const feed = $('#kill-feed');
    const row = document.createElement('div');
    row.className = 'kill-row';
    row.innerHTML = `<span class="killer team-${killerTeam}">${escapeHtml(killer)}</span><span class="weapon-mark">${headshot ? '&#10022;' : '&#9656;'}</span><span class="victim team-${victimTeam}">${escapeHtml(victim)}</span>`;
    feed.prepend(row);
    while (feed.children.length > 6) feed.lastChild.remove();
    setTimeout(() => row.remove(), 4800);
  }

  hitmarker(headshot = false) {
    const el = $('#hitmarker');
    el.classList.remove('show', 'headshot');
    void el.offsetWidth;
    el.classList.add('show');
    if (headshot) el.classList.add('headshot');
    clearTimeout(this.hitmarkerTimer);
    this.hitmarkerTimer = setTimeout(() => el.classList.remove('show'), 140);
  }

  damage(direction, intensity = 1) {
    const vignette = $('#damage-vignette');
    vignette.style.opacity = String(Math.min(0.85, 0.25 + intensity * 0.55));
    vignette.classList.add('show');
    clearTimeout(this.damageTimer);
    this.damageTimer = setTimeout(() => {
      vignette.classList.remove('show');
      vignette.style.opacity = '0';
    }, 220);

    if (direction) {
      const dir = $('#damage-direction');
      const angle = Math.atan2(direction.x, -direction.z) * (180 / Math.PI);
      dir.style.transform = `translate(-50%, -50%) rotate(${angle}deg)`;
      dir.classList.add('show');
      clearTimeout(this.directionTimer);
      this.directionTimer = setTimeout(() => dir.classList.remove('show'), 800);
    }
  }

  showScoreboard(game) {
    this.scoreboardVisible = true;
    const el = $('#scoreboard');
    el.innerHTML = this.scoreboardHtml(game);
    el.classList.remove('hidden');
  }

  hideScoreboard() {
    this.scoreboardVisible = false;
    $('#scoreboard').classList.add('hidden');
  }

  scoreboardHtml(game) {
    const participants = game.getSortedParticipants();
    if (game.mode === 'tdm') {
      const ct = participants.filter((p) => p.team === 'CT').sort((a, b) => b.kills - a.kills);
      const t = participants.filter((p) => p.team === 'T').sort((a, b) => b.kills - a.kills);
      return `
        <div class="scoreboard-head"><span>${escapeHtml(game.mapDef.name)}</span><b>${game.scores.CT} : ${game.scores.T}</b><span>${game.modeDef.name}</span></div>
        <div class="scoreboard-teams">
          ${this.teamTable('COUNTER-TERRORISTS', ct, 'ct')}
          ${this.teamTable('TERRORISTS', t, 't')}
        </div>
        <div class="scoreboard-foot">TAB HOLD TO VIEW &bull; ${formatTime(game.timeLeft)} REMAINING &bull; FIRST TO ${game.matchConfig.scoreLimit}</div>`;
    }
    return `
      <div class="scoreboard-head"><span>${escapeHtml(game.mapDef.name)}</span><b>FREE FOR ALL</b><span>${formatTime(game.timeLeft)}</span></div>
      <table class="score-table">
        <thead><tr><th>#</th><th>OPERATOR</th><th>KILLS</th><th>DEATHS</th><th>STATUS</th></tr></thead>
        <tbody>${participants.map((p, i) => `
          <tr class="${p.isPlayer ? 'you' : ''}">
            <td>${i + 1}</td>
            <td><span class="team-dot team-${p.team}"></span>${escapeHtml(p.name)}${p.isPlayer ? ' <em>YOU</em>' : ''}</td>
            <td><b>${p.kills}</b></td><td>${p.deaths}</td><td>${p.alive ? 'ACTIVE' : 'DOWN'}</td>
          </tr>`).join('')}
        </tbody>
      </table>
      <div class="scoreboard-foot">TAB HOLD TO VIEW &bull; ${formatTime(game.timeLeft)} REMAINING &bull; FIRST TO ${game.matchConfig.scoreLimit} KILLS</div>`;
  }

  teamTable(title, players, team) {
    return `
      <div class="score-team team-${team}">
        <h3>${title}</h3>
        <table class="score-table">
          <thead><tr><th>OPERATOR</th><th>K</th><th>D</th><th>STATUS</th></tr></thead>
          <tbody>${players.map((p) => `
            <tr class="${p.isPlayer ? 'you' : ''}">
              <td>${escapeHtml(p.name)}${p.isPlayer ? ' <em>YOU</em>' : ''}</td>
              <td>${p.kills}</td><td>${p.deaths}</td><td>${p.alive ? 'ACTIVE' : 'DOWN'}</td>
            </tr>`).join('')}
          </tbody>
        </table>
      </div>`;
  }

  showPause(show, game) {
    $('#pause-panel').classList.toggle('hidden', !show);
    if (show && game) {
      $('#pause-subtitle').textContent = `${game.mapDef.name} • ${game.modeDef.name} • ${formatTime(game.timeLeft)}`;
    }
  }

  hidePause() {
    $('#pause-panel').classList.add('hidden');
  }

  showResults(data) {
    this.matchData = data;
    const el = $('#results-content');
    const winnerClass = data.playerWon ? 'won' : data.draw ? 'draw' : 'lost';
    const title = data.draw ? 'DRAW' : data.playerWon ? 'VICTORY' : 'DEFEAT';
    const sub = data.mode === 'tdm'
      ? `${data.winnerLabel} wins ${data.finalScore}`
      : `${escapeHtml(data.winnerName)} wins with ${data.winnerScore} kills`;
    el.className = `modal-frame results-frame ${winnerClass}`;
    el.innerHTML = `
      <div class="modal-kicker">MATCH COMPLETE &bull; ${escapeHtml(data.mapName)}</div>
      <h2>${title}</h2>
      <p class="result-sub">${sub}</p>
      <div class="result-scoreline">
        ${data.mode === 'tdm'
          ? `<div class="team-result ct"><span>CT</span><strong>${data.scores.CT}</strong></div><div class="vs">:</div><div class="team-result t"><span>T</span><strong>${data.scores.T}</strong></div>`
          : `<div class="ffa-result"><span>YOUR PLACEMENT</span><strong>#${data.playerPlace}</strong><small>${data.playerKills} KILLS &bull; ${data.playerDeaths} DEATHS</small></div>`}
      </div>
      <div class="result-stats">
        <div><strong>${data.playerKills}</strong><span>KILLS</span></div>
        <div><strong>${data.playerDeaths}</strong><span>DEATHS</span></div>
        <div><strong>${data.playerKd}</strong><span>K/D</span></div>
        <div><strong>${data.headshots}</strong><span>HEADSHOTS</span></div>
      </div>
      <div class="result-table">${data.table}</div>
      <div class="panel-actions">
        <button data-action="main-menu">MAIN MENU</button>
        <button data-action="new-match">NEW MATCH</button>
        <button class="accent" data-action="play-again">PLAY AGAIN</button>
      </div>`;
    $('#results-panel').classList.remove('hidden');
    this.hideScoreboard();
    this.hidePause();
  }

  hideResults() {
    $('#results-panel').classList.add('hidden');
  }

  showLoading(message = 'DEPLOYING TO MATCH…') {
    this.toast(message, 900);
  }
}

