import { Game } from './game/game.js';
import { audio } from './audio/audio.js';

const canvas = document.querySelector('#game-canvas');
const bootError = document.querySelector('#boot-error');

function fail(error) {
  console.error(error);
  if (bootError) {
    bootError.classList.remove('hidden');
    bootError.innerHTML = `<strong>THE GAME COULD NOT START</strong><span>${String(error?.message || error)}</span><small>Try a current desktop browser with WebGL2 enabled.</small>`;
  }
}

try {
  if (!canvas) throw new Error('Game canvas was not found.');
  const game = new Game(canvas);
  window.game = game;

  // Unlock procedural audio as soon as the player interacts with the page.
  const unlock = () => {
    audio.init();
    audio.startMusic();
    audio.setVolumes();
  };
  window.addEventListener('pointerdown', unlock, { once: true });
  window.addEventListener('keydown', unlock, { once: true });

  window.addEventListener('error', (event) => {
    if (event.error) console.error('Runtime error:', event.error);
  });
  window.addEventListener('unhandledrejection', (event) => {
    console.error('Unhandled rejection:', event.reason);
  });
} catch (error) {
  fail(error);
}

/* ==========================================================================
   TACTICAL FPS — classic PC-shooter interface
   ========================================================================== */

:root {
  --amber: #d9a95c;
  --amber-soft: #b7935f;
  --bone: #e8e4d7;
  --muted: #a19d8d;
  --dim: #6d6c61;
  --panel: rgba(17, 18, 15, 0.94);
  --line: rgba(216, 203, 166, 0.22);
  --ct: #6f9bb0;
  --t: #bd7d4a;
  --ffa: #c4b78e;
  --danger: #c35b46;
  --crosshair-color: #d9e2c4;
  --ui-font: "Barlow Condensed", "Arial Narrow", "Roboto Condensed", "Trebuchet MS", sans-serif;
  --mono: "IBM Plex Mono", "Consolas", "Courier New", monospace;
}

* { box-sizing: border-box; }
html, body, #game-shell {
  margin: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
}
body {
  background: #12130f;
  color: var(--bone);
  font-family: var(--mono);
  -webkit-font-smoothing: antialiased;
  user-select: none;
}
button, input, select { font-family: inherit; }
button { cursor: pointer; }
.hidden { display: none !important; }

#game-shell {
  position: relative;
  background: #14150f;
  isolation: isolate;
}
#game-canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  outline: none;
}
#grain {
  pointer-events: none;
  position: absolute;
  inset: 0;
  z-index: 3;
  opacity: 0.09;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.85' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.35'/%3E%3C/svg%3E");
  mix-blend-mode: soft-light;
}

/* --------------------------------------------------------------------------
   Shared screen / brand
   -------------------------------------------------------------------------- */

.screen {
  position: absolute;
  inset: 0;
  z-index: 6;
  display: none;
}
.screen.visible { display: block; }

#menu-screen {
  overflow: hidden;
}
.menu-backdrop {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(90deg, rgba(6, 8, 7, 0.96) 0%, rgba(7, 9, 8, 0.9) 37%, rgba(12, 13, 10, 0.42) 73%, rgba(12, 13, 10, 0.6) 100%),
    linear-gradient(0deg, #10110e 0%, transparent 30%, rgba(4, 5, 4, 0.35) 100%);
  backdrop-filter: blur(1.5px) saturate(0.8);
}
.menu-backdrop::after {
  content: "";
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(0deg, rgba(255, 255, 255, 0.018) 0 1px, transparent 1px 3px);
  opacity: 0.35;
}

.brand {
  position: absolute;
  top: 6.6%;
  left: 7%;
  z-index: 2;
  display: flex;
  gap: 15px;
  align-items: center;
}
.brand-mark {
  width: 52px;
  height: 55px;
  display: grid;
  place-items: center;
  background: linear-gradient(145deg, #e0b56b, #7d5935);
  clip-path: polygon(0 0, 100% 0, 100% 74%, 50% 100%, 0 74%);
  font: 800 36px/1 var(--ui-font);
  color: #1a1a14;
  text-shadow: 0 1px rgba(255, 255, 255, 0.35);
  box-shadow: 0 3px 18px rgba(0, 0, 0, 0.5);
}
.brand h1 {
  font: 800 31px/0.95 var(--ui-font);
  letter-spacing: 3.4px;
  margin: 0;
  color: #f1eee4;
  text-shadow: 0 2px 12px rgba(0, 0, 0, 0.7);
}
.brand h1 span { color: var(--amber); }
.brand p {
  margin: 5px 0 0;
  font-size: 8.5px;
  letter-spacing: 2.7px;
  color: #928e7f;
}

.menu-layout {
  position: absolute;
  left: 7%;
  right: 7%;
  top: 23%;
  bottom: 12.5%;
  display: grid;
  grid-template-columns: 290px minmax(390px, 660px);
  gap: 8%;
  align-items: center;
  z-index: 2;
}
.main-menu { display: flex; flex-direction: column; gap: 5px; }
.main-menu button {
  position: relative;
  color: #dedacc;
  text-align: left;
  background: linear-gradient(90deg, rgba(123, 110, 82, 0.16), rgba(35, 36, 30, 0.5));
  border: 1px solid rgba(185, 167, 122, 0.22);
  border-left: 3px solid #6e6346;
  padding: 9px 16px 10px;
  font: 600 16px/1.1 var(--ui-font);
  letter-spacing: 1.3px;
  transition: 0.15s ease;
}
.main-menu button span { display: block; }
.main-menu button small {
  display: block;
  margin-top: 3px;
  font: 9px/1.2 var(--mono);
  letter-spacing: 0;
  color: #8f8b7d;
}
.main-menu button:hover,
.main-menu button:focus-visible {
  outline: none;
  color: #fff4d8;
  border-color: #cfa25b;
  border-left-color: var(--amber);
  background: linear-gradient(90deg, rgba(181, 136, 71, 0.42), rgba(54, 46, 33, 0.5));
  transform: translateX(4px);
  padding-left: 20px;
}
.main-menu button.primary {
  background: linear-gradient(90deg, rgba(153, 112, 51, 0.55), rgba(52, 43, 29, 0.55));
  border-color: rgba(224, 181, 102, 0.55);
  border-left-color: var(--amber);
}
.main-menu button.primary small { color: #cbb78f; }

.menu-card {
  max-width: 660px;
  border: 1px solid rgba(221, 203, 160, 0.24);
  background: linear-gradient(135deg, rgba(36, 37, 32, 0.9), rgba(16, 18, 16, 0.92));
  padding: 22px 25px 14px;
  box-shadow: 0 26px 80px rgba(0, 0, 0, 0.6);
  backdrop-filter: blur(3px);
}
.card-kicker {
  font-size: 8px;
  letter-spacing: 2.2px;
  color: #c79852;
}
.menu-card h2 {
  font: 700 39px/1 var(--ui-font);
  letter-spacing: 0.4px;
  margin: 9px 0 3px;
}
.menu-card > p { margin: 0 0 17px; font-size: 10.5px; color: #aaa595; }
.feature-image {
  position: relative;
  height: 232px;
  overflow: hidden;
  border: 1px solid #685d47;
  background: linear-gradient(#8f9c9c 0%, #c9b98e 48%, #77664e 49%, #514b3c 100%);
  image-rendering: pixelated;
}
.feature-image::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(30, 43, 50, 0.35), transparent 38%, rgba(40, 30, 17, 0.38));
  z-index: 3;
}
.feature-image::after {
  content: "";
  position: absolute;
  z-index: 2;
  left: -5%;
  bottom: 0;
  width: 112%;
  height: 58px;
  background: repeating-linear-gradient(6deg, #6d6046 0 3px, #7c6e50 4px 8px);
  transform: rotate(-0.6deg);
}
.sun {
  position: absolute;
  right: 16%;
  top: 16%;
  width: 43px;
  height: 43px;
  border-radius: 50%;
  background: #ead29a;
  box-shadow: 0 0 55px 26px rgba(223, 193, 131, 0.35);
}
.ridge {
  position: absolute;
  bottom: 46px;
  left: -10%;
  width: 120%;
  height: 88px;
  background: #7b6c4e;
  clip-path: polygon(0 100%, 0 62%, 9% 55%, 17% 63%, 26% 29%, 35% 56%, 45% 23%, 56% 58%, 66% 40%, 78% 57%, 89% 33%, 100% 60%, 100% 100%);
}
.ridge-back {
  bottom: 56px;
  background: #93815a;
  opacity: 0.72;
  transform: scaleX(-1);
}
.ridge-front {
  z-index: 1;
  background: #4f4939;
  bottom: 35px;
  height: 68px;
  clip-path: polygon(0 100%, 0 59%, 12% 52%, 26% 66%, 39% 33%, 52% 58%, 68% 30%, 82% 56%, 100% 36%, 100% 100%);
}
.watchtower {
  position: absolute;
  z-index: 2;
  right: 24%;
  bottom: 58px;
  width: 41px;
  height: 73px;
  border: 5px solid #514936;
  border-bottom: 0;
  background: linear-gradient(90deg, #89734e, #68593e);
  clip-path: polygon(13% 0, 87% 0, 100% 14%, 100% 25%, 88% 25%, 88% 100%, 10% 100%, 10% 25%, 0 25%, 0 14%);
}
.watchtower::before {
  content: "";
  position: absolute;
  top: 17px;
  left: 8px;
  width: 16px;
  height: 18px;
  background: #34362e;
  border: 2px solid #9a8358;
}
.watchtower i {
  position: absolute;
  left: -9px;
  bottom: 0;
  width: 46px;
  height: 6px;
  background: #544934;
}
.dust-label {
  position: absolute;
  z-index: 4;
  left: 16px;
  bottom: 12px;
  font-size: 8px;
  letter-spacing: 1.7px;
  color: #e3d3a9;
  text-shadow: 0 1px 4px #000;
}
.menu-foot {
  display: flex;
  justify-content: space-between;
  padding-top: 12px;
  font-size: 7.5px;
  letter-spacing: 0.8px;
  color: #989483;
}
.live-dot {
  display: inline-block;
  width: 6px;
  height: 6px;
  margin-right: 6px;
  border-radius: 50%;
  background: #8aa66b;
  box-shadow: 0 0 8px #8aa66b;
}
.menu-footer {
  position: absolute;
  z-index: 2;
  left: 7%;
  right: 7%;
  bottom: 4.2%;
  display: flex;
  justify-content: space-between;
  font-size: 7.5px;
  letter-spacing: 1px;
  color: #6e6d61;
}

/* --------------------------------------------------------------------------
   Panels
   -------------------------------------------------------------------------- */

#panel-screen { z-index: 20; }
.panel-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(6, 7, 6, 0.66);
  backdrop-filter: blur(3px);
}
.panel {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  width: min(690px, 93vw);
  max-height: 89vh;
  overflow: auto;
  padding: 27px 31px 24px;
  background: linear-gradient(160deg, rgba(24, 25, 21, 0.985), rgba(13, 14, 12, 0.99));
  border: 1px solid #a78d5d;
  box-shadow: 0 28px 110px rgba(0, 0, 0, 0.8), inset 0 0 0 1px rgba(255, 243, 208, 0.04);
  scrollbar-width: thin;
  scrollbar-color: #6e5e40 #181a16;
}
.panel-wide { width: min(900px, 94vw); }
.panel::before {
  content: "";
  position: absolute;
  inset: 5px;
  border: 1px solid rgba(213, 194, 149, 0.09);
  pointer-events: none;
}
.panel h2 {
  margin: 0 0 5px;
  font: 700 31px/1 var(--ui-font);
  letter-spacing: 2.2px;
  color: #e6c37f;
}
.panel-kicker {
  font-size: 8px;
  letter-spacing: 2.4px;
  color: #c29450;
  margin-bottom: 8px;
}
.panel-sub {
  margin: 0 0 21px;
  font-size: 10px;
  line-height: 1.6;
  color: #969283;
}
.panel-close {
  position: absolute;
  right: 17px;
  top: 14px;
  width: 30px;
  height: 30px;
  padding: 0;
  border: 1px solid #5d5542;
  background: #24251f;
  color: #cfc6ad;
  font-size: 18px;
  line-height: 1;
}
.panel-close:hover { border-color: var(--amber); color: #fff; }

.form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px 18px;
}
.form-grid.compact { gap: 12px 16px; }
.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  font-size: 9px;
  letter-spacing: 0.7px;
  color: #b9b4a4;
}
.field.full { grid-column: 1 / -1; }
.field input,
.field select {
  width: 100%;
  padding: 9px 10px;
  background: #24251f;
  border: 1px solid #565347;
  color: #e8e3d3;
  font: 11.5px var(--mono);
  outline: none;
}
.field input:focus,
.field select:focus { border-color: #c9a25e; background: #292a23; }
.field-hint {
  display: block;
  margin-top: 2px;
  color: #7f7b6d;
  font-size: 9px;
  line-height: 1.5;
  letter-spacing: 0;
}
.field input[type="range"] {
  padding: 0;
  accent-color: var(--amber);
  background: transparent;
  border: 0;
  height: 18px;
}
.field input[type="color"] {
  height: 35px;
  padding: 3px;
}
.slider-field output {
  float: right;
  color: #e1c58e;
  font-size: 10px;
}
.check-field {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 9.5px;
  color: #b9b4a4;
  padding-top: 9px;
}
.check-field input { accent-color: var(--amber); width: 14px; height: 14px; }

.panel-actions {
  display: flex;
  justify-content: flex-end;
  align-items: center;
  flex-wrap: wrap;
  gap: 9px;
  margin-top: 22px;
}
.panel-actions button,
.panel .inline-button {
  padding: 10px 17px;
  text-align: center;
  color: #dedacc;
  background: linear-gradient(90deg, rgba(115, 103, 77, 0.2), rgba(40, 41, 34, 0.5));
  border: 1px solid rgba(185, 167, 122, 0.27);
  font: 600 12px var(--ui-font);
  letter-spacing: 1.2px;
}
.panel-actions button:hover,
.panel .inline-button:hover {
  color: #fff3d6;
  border-color: var(--amber);
  background: linear-gradient(90deg, rgba(181, 136, 71, 0.38), rgba(54, 46, 33, 0.55));
}
.panel-actions .accent {
  border-color: #cfa25b;
  background: linear-gradient(90deg, rgba(157, 115, 51, 0.55), rgba(64, 51, 30, 0.6));
  color: #fff1cc;
}
.panel-actions .danger-quiet { color: #bd8c80; border-color: #5d4540; }
.panel .inline-button { margin-top: 13px; padding: 8px 13px; font-size: 10px; }
.mode-note {
  margin-top: 15px;
  padding: 10px 12px;
  font-size: 9px;
  line-height: 1.6;
  color: #a7a18e;
  background: rgba(99, 86, 57, 0.12);
  border-left: 2px solid #887446;
}

.settings-section {
  margin-top: 19px;
  padding-top: 15px;
  border-top: 1px solid #3b392f;
}
.settings-section h3 {
  margin: 0 0 13px;
  font: 600 11px var(--ui-font);
  letter-spacing: 2px;
  color: #c8a665;
}
.settings-section .field { margin-bottom: 12px; }

.credits-body p {
  margin: 0 0 14px;
  font-size: 10.5px;
  line-height: 1.8;
  color: #b2ad9c;
}
.credits-body b { color: #e2d3ae; }
.credits-body .muted { color: #7c796c; font-size: 9px; }
.status-banner {
  display: flex;
  align-items: center;
  gap: 9px;
  margin: 16px 0;
  padding: 12px 14px;
  border: 1px solid #5e5040;
  background: rgba(90, 60, 39, 0.18);
  font-size: 10px;
  letter-spacing: 1.3px;
  color: #d1b28a;
}
.status-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #bd6a50;
  box-shadow: 0 0 9px rgba(189, 106, 80, 0.7);
}
.profile-layout {
  display: grid;
  grid-template-columns: 1fr 1.2fr;
  gap: 25px;
  align-items: start;
}
.profile-patch {
  width: 70px;
  height: 74px;
  display: grid;
  place-items: center;
  margin-bottom: 16px;
  background: linear-gradient(145deg, #9a7b47, #4b3d28);
  clip-path: polygon(0 0, 100% 0, 100% 76%, 50% 100%, 0 76%);
  color: #1d1c15;
  font: 800 27px var(--ui-font);
  letter-spacing: 1px;
}
.profile-rank {
  margin-top: 15px;
  padding: 9px 10px;
  color: #d8bd83;
  font: 600 11px var(--ui-font);
  letter-spacing: 1.2px;
  border: 1px solid #4f4737;
  background: #1f211b;
}
.profile-rank span { float: right; color: #7f7a6b; font: 8px var(--mono); }
.profile-stats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 7px;
}
.profile-stats div {
  padding: 12px;
  background: #1e201a;
  border: 1px solid #393a31;
}
.profile-stats strong {
  display: block;
  color: #e5cf9d;
  font: 600 22px var(--mono);
}
.profile-stats span {
  display: block;
  margin-top: 3px;
  color: #898578;
  font-size: 8px;
  letter-spacing: 1px;
}
.profile-note {
  margin: 16px 0 0;
  font-size: 9.5px;
  line-height: 1.7;
  color: #8f8b7e;
}

/* --------------------------------------------------------------------------
   HUD
   -------------------------------------------------------------------------- */

#hud {
  position: absolute;
  inset: 0;
  z-index: 4;
  pointer-events: none;
  color: #e9e9df;
  text-shadow: 1px 1px 2px #000, 0 1px 7px rgba(0, 0, 0, 0.7);
}
.top-strip {
  position: absolute;
  top: 14px;
  left: 50%;
  transform: translateX(-50%);
  min-width: 330px;
  height: 57px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 14px;
  padding: 6px 19px;
  background: linear-gradient(90deg, rgba(12, 14, 11, 0.9), rgba(34, 34, 27, 0.94), rgba(12, 14, 11, 0.9));
  border-top: 1px solid rgba(200, 189, 153, 0.25);
  border-bottom: 1px solid rgba(200, 189, 153, 0.14);
}
.team-chip {
  display: flex;
  align-items: center;
  gap: 7px;
  font: 700 12px var(--ui-font);
  letter-spacing: 0.8px;
}
.team-chip strong { font: 600 18px var(--mono); }
.team-chip i {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--ct);
  box-shadow: 0 0 6px var(--ct);
}
.t-chip i { background: var(--t); box-shadow: 0 0 6px var(--t); }
.ct-chip { color: #9ec3d2; }
.t-chip { color: #d5a578; }
.round-info {
  min-width: 110px;
  padding: 0 16px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1px;
  border-left: 1px solid rgba(199, 189, 154, 0.2);
  border-right: 1px solid rgba(199, 189, 154, 0.2);
}
.round-info span { font-size: 7.5px; letter-spacing: 1.1px; color: #cdb987; }
.round-info b { font-size: 16px; letter-spacing: 1px; }
.round-info small { font-size: 7px; letter-spacing: 1.2px; color: #a5a291; }
.round-info small.match-point { color: #e9b767; text-shadow: 0 0 8px rgba(233, 183, 103, 0.5); }

.radar-wrap {
  position: absolute;
  top: 17px;
  left: 19px;
  width: 148px;
  height: 165px;
}
.radar-wrap canvas {
  width: 148px;
  height: 148px;
  border-radius: 50%;
  border: 1px solid rgba(211, 204, 173, 0.4);
  box-shadow: 0 0 0 3px rgba(10, 18, 14, 0.35), 0 8px 26px rgba(0, 0, 0, 0.4);
}
.radar-wrap b {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 1px;
  text-align: center;
  font-size: 7px;
  letter-spacing: 2px;
  color: #b9b5a0;
}

.kill-feed {
  position: absolute;
  top: 92px;
  right: 20px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  align-items: flex-end;
  font-size: 10px;
}
.kill-row {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 5px 10px;
  background: linear-gradient(90deg, rgba(13, 16, 13, 0), rgba(13, 16, 13, 0.86));
  border-right: 2px solid rgba(204, 186, 139, 0.35);
  animation: feed-in 0.18s ease-out;
}
@keyframes feed-in { from { opacity: 0; transform: translateX(12px); } }
.kill-row .killer { color: #e2c685; }
.kill-row .victim { color: #d08f7f; }
.kill-row .weapon-mark { color: #918b78; font-size: 9px; }
.team-CT { color: #9ec3d2; }
.team-T { color: #d5a578; }
.team-FFA { color: #c4b78e; }

.objective-banner {
  position: absolute;
  top: 88px;
  left: 50%;
  transform: translateX(-50%) translateY(-4px);
  font: 600 11px var(--ui-font);
  letter-spacing: 1.8px;
  color: #f0d98a;
  opacity: 0;
  transition: 0.2s ease;
  text-align: center;
}
.objective-banner.show { opacity: 1; transform: translateX(-50%) translateY(0); }

.crosshair {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 0;
  height: 0;
  --spread: 7px;
  color: var(--crosshair-color);
  transition: opacity 0.15s ease;
}
.crosshair i {
  position: absolute;
  background: currentColor;
  box-shadow: 0 0 2px #111, 0 0 1px #111;
}
.crosshair .ch-top { width: 2px; height: 8px; left: -1px; bottom: var(--spread); }
.crosshair .ch-bottom { width: 2px; height: 8px; left: -1px; top: var(--spread); }
.crosshair .ch-left { width: 8px; height: 2px; top: -1px; right: var(--spread); }
.crosshair .ch-right { width: 8px; height: 2px; top: -1px; left: var(--spread); }
.crosshair > b {
  position: absolute;
  width: 2px;
  height: 2px;
  left: -1px;
  top: -1px;
  background: currentColor;
}
.hitmarker {
  position: absolute;
  left: -12px;
  top: -12px;
  width: 24px;
  height: 24px;
  opacity: 0;
  transform: scale(0.7);
  transition: opacity 0.06s, transform 0.06s;
}
.hitmarker::before,
.hitmarker::after {
  content: "";
  position: absolute;
  left: 11px;
  top: -3px;
  width: 2px;
  height: 30px;
  background: #f3e6bd;
  box-shadow: 0 0 3px #000;
}
.hitmarker::before { transform: rotate(45deg); }
.hitmarker::after { transform: rotate(-45deg); }
.hitmarker.show { opacity: 1; transform: scale(1); }
.hitmarker.headshot::before,
.hitmarker.headshot::after { background: #ef9c68; }

.damage-vignette {
  position: absolute;
  inset: 0;
  opacity: 0;
  pointer-events: none;
  background: radial-gradient(ellipse at center, transparent 34%, rgba(131, 26, 19, 0.14) 67%, rgba(151, 28, 18, 0.7) 100%);
  transition: opacity 0.22s ease-out;
}
.damage-vignette.show { transition: opacity 0.02s; }
.damage-direction {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 150px;
  height: 150px;
  border-radius: 50%;
  border-top: 5px solid rgba(219, 91, 67, 0.85);
  opacity: 0;
  transform: translate(-50%, -50%) rotate(0deg);
  transition: opacity 0.25s ease-out;
}
.damage-direction.show { opacity: 1; transition: opacity 0.03s; }

.bottom-hud {
  position: absolute;
  left: 25px;
  right: 25px;
  bottom: 34px;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
}
.status-group,
.ammo-box {
  height: 60px;
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 8px 13px;
  background: linear-gradient(90deg, rgba(11, 13, 11, 0.84), rgba(25, 27, 23, 0.58));
  border-top: 1px solid rgba(221, 214, 176, 0.32);
}
.status-group { min-width: 240px; }
.status-group small,
.ammo-box small {
  display: block;
  font-size: 7.5px;
  letter-spacing: 0.8px;
  color: #aaa99a;
}
.status-group strong { font-size: 18px; }
.status-group strong.critical { color: #e57b63; }
.health-icon { font-size: 20px; color: #8bbb8e; }
.shield-icon { font-size: 18px; color: #8fabba; }
.hud-divider { width: 1px; height: 27px; margin: 0 7px; background: rgba(204, 196, 160, 0.26); }
.ammo-box { min-width: 245px; justify-content: space-between; }
.weapon-name strong { font: 700 17px var(--ui-font); letter-spacing: 1.1px; }
.ammo-count { text-align: right; }
.ammo-count strong { font-size: 24px; }
.ammo-count strong.empty { color: #e57b63; }
.ammo-count span { font-size: 11px; color: #aaa; }
.ammo-count small { display: inline-block; margin-left: 7px; }
.match-status {
  flex: 1;
  max-width: 220px;
  text-align: center;
  padding-bottom: 8px;
}
.match-status small {
  display: block;
  font-size: 7.5px;
  letter-spacing: 1.5px;
  color: #b7b19a;
}
.match-status strong {
  font: 600 17px var(--mono);
  letter-spacing: 2px;
  color: #ded3b1;
}
.hint-bar {
  position: absolute;
  left: 50%;
  bottom: 10px;
  transform: translateX(-50%);
  font-size: 7.5px;
  letter-spacing: 0.4px;
  color: rgba(202, 200, 185, 0.68);
  white-space: nowrap;
}
.hint-bar b { margin: 0 4px; color: var(--amber); }
.fps-counter {
  position: absolute;
  right: 20px;
  top: 16px;
  padding: 4px 7px;
  background: rgba(10, 12, 10, 0.6);
  border: 1px solid rgba(205, 193, 156, 0.2);
  font-size: 9px;
  color: #c8c3ad;
