   -------------------------------------------------------------------------- */

.scoreboard {
  position: absolute;
  z-index: 8;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  width: min(720px, 92vw);
  max-height: 78vh;
  overflow: auto;
  padding: 19px 23px;
  background: rgba(15, 17, 14, 0.95);
  border: 1px solid #ae9663;
  box-shadow: 0 24px 90px rgba(0, 0, 0, 0.75);
  pointer-events: auto;
}
.scoreboard-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  padding-bottom: 13px;
  margin-bottom: 12px;
  border-bottom: 1px solid #403d31;
  font-size: 9px;
  letter-spacing: 1.2px;
  color: #b5ae97;
}
.scoreboard-head b {
  font: 600 20px var(--mono);
  color: #e4cb92;
  letter-spacing: 2px;
}
.scoreboard-teams {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}
.score-team h3 {
  margin: 0 0 7px;
  font: 600 11px var(--ui-font);
  letter-spacing: 1.4px;
}
.score-team.team-ct h3 { color: var(--ct); }
.score-team.team-t h3 { color: var(--t); }
.score-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 9.5px;
}
.score-table th {
  padding: 6px 5px;
  text-align: left;
  font-weight: 500;
  color: #837f70;
  border-bottom: 1px solid #464336;
  letter-spacing: 0.6px;
}
.score-table td {
  padding: 6px 5px;
  border-bottom: 1px solid #2f3028;
  color: #c8c3b2;
}
.score-table tr.you td { background: rgba(185, 145, 77, 0.14); color: #f1e4c3; }
.score-table em { font-style: normal; color: #d5a95e; font-size: 7px; letter-spacing: 1px; }
.scoreboard-foot {
  margin-top: 13px;
  padding-top: 10px;
  border-top: 1px solid #3c3a2f;
  text-align: center;
  font-size: 7.5px;
  letter-spacing: 1px;
  color: #898676;
}
.team-dot {
  display: inline-block;
  width: 6px;
  height: 6px;
  margin-right: 6px;
  border-radius: 50%;
  background: currentColor;
}
.team-dot.team-CT { background: var(--ct); }
.team-dot.team-T { background: var(--t); }
.team-dot.team-FFA { background: var(--ffa); }

.modal-panel {
  position: absolute;
  z-index: 11;
  inset: 0;
  display: grid;
  place-items: center;
  pointer-events: auto;
  background: rgba(5, 6, 5, 0.48);
  backdrop-filter: blur(2px);
}
.modal-frame {
  width: min(390px, 92vw);
  padding: 25px 28px;
  background: rgba(17, 19, 16, 0.97);
  border: 1px solid #a68d5e;
  box-shadow: 0 30px 100px rgba(0, 0, 0, 0.8);
  text-align: center;
}
.modal-kicker {
  font-size: 7.5px;
  letter-spacing: 2.2px;
  color: #c09550;
}
.modal-frame h2 {
  margin: 7px 0 4px;
  font: 700 34px/1 var(--ui-font);
  letter-spacing: 3px;
  color: #e6c37f;
}
.modal-frame p {
  margin: 0 0 17px;
  font-size: 8.5px;
  letter-spacing: 1.1px;
  color: #9d9888;
}
.modal-frame button {
  display: block;
  width: 100%;
  margin: 5px 0;
  padding: 10px;
  text-align: center;
  color: #dedacc;
  background: linear-gradient(90deg, rgba(115, 103, 77, 0.2), rgba(40, 41, 34, 0.55));
  border: 1px solid rgba(185, 167, 122, 0.27);
  font: 600 12px var(--ui-font);
  letter-spacing: 1.3px;
}
.modal-frame button:hover { color: #fff2d1; border-color: var(--amber); background: linear-gradient(90deg, rgba(181, 136, 71, 0.38), rgba(54, 46, 33, 0.55)); }
.modal-frame button.danger { color: #c9988a; border-color: #5b423b; }
.pause-frame { width: min(330px, 92vw); }

.results-frame {
  width: min(680px, 94vw);
  max-height: 90vh;
  overflow: auto;
  text-align: center;
}
.results-frame.won h2 { color: #e9c979; text-shadow: 0 0 30px rgba(217, 169, 92, 0.3); }
.results-frame.lost h2 { color: #c48674; }
.results-frame.draw h2 { color: #c4b78e; }
.result-sub { font-size: 9.5px; letter-spacing: 1.2px; color: #a9a28d; }
.result-scoreline {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 24px;
  margin: 17px 0;
  padding: 14px;
  background: rgba(32, 34, 28, 0.55);
  border-top: 1px solid #3d3b30;
  border-bottom: 1px solid #3d3b30;
}
.team-result { min-width: 80px; }
.team-result span { display: block; font-size: 8px; letter-spacing: 1.5px; color: #8e897a; }
.team-result strong { font: 600 30px var(--mono); }
.team-result.ct strong { color: #9ec3d2; }
.team-result.t strong { color: #d5a578; }
.vs { color: #6f6b5d; font-size: 18px; }
.ffa-result span { display: block; font-size: 8px; letter-spacing: 1.4px; color: #8e897a; }
.ffa-result strong { display: block; font: 600 36px var(--mono); color: #e6c37f; }
.ffa-result small { color: #9e9886; font-size: 8px; letter-spacing: 1px; }
.result-stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 5px;
  margin: 13px 0 17px;
}
.result-stats div {
  padding: 9px 4px;
  background: rgba(38, 40, 33, 0.55);
  border: 1px solid #34352c;
}
.result-stats strong { display: block; font: 600 19px var(--mono); color: #e2cf9f; }
.result-stats span { display: block; margin-top: 2px; font-size: 7px; letter-spacing: 1px; color: #827e70; }
.result-table { max-height: 210px; overflow: auto; text-align: left; }
.result-table .score-table { font-size: 9px; }
.results-frame .panel-actions { justify-content: center; }
.results-frame .panel-actions button { width: auto; min-width: 110px; padding: 10px 15px; }

.respawn-panel {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  text-align: center;
  padding: 20px 32px;
  background: linear-gradient(180deg, rgba(27, 18, 15, 0.15), rgba(41, 17, 13, 0.72));
  border-top: 1px solid rgba(199, 105, 83, 0.35);
  border-bottom: 1px solid rgba(199, 105, 83, 0.35);
}
.respawn-panel .kicker { font-size: 8px; letter-spacing: 2.4px; color: #cf8d7a; }
.respawn-panel h2 { margin: 7px 0 4px; font: 700 27px var(--ui-font); letter-spacing: 2px; color: #e8c9a4; }
.respawn-count { font: 600 40px var(--mono); color: #e4d7b7; line-height: 1.15; }
.respawn-panel p { margin: 2px 0 0; font-size: 7.5px; letter-spacing: 1.2px; color: #9e9483; }

.pointer-prompt {
  position: absolute;
  left: 50%;
  top: 58%;
  transform: translate(-50%, -50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 7px;
  padding: 15px 25px;
  background: rgba(12, 14, 12, 0.84);
  border: 1px solid rgba(210, 195, 155, 0.35);
  pointer-events: none;
  text-align: center;
}
.pointer-prompt strong { font: 600 12px var(--ui-font); letter-spacing: 1.5px; color: #ecdfb8; }
.pointer-prompt span { font-size: 8px; letter-spacing: 0.5px; color: #a9a491; }
.mouse-icon {
  width: 17px;
  height: 26px;
  border: 1px solid #cfc6a9;
  border-radius: 8px;
  position: relative;
}
.mouse-icon::after {
  content: "";
  position: absolute;
  left: 7px;
  top: 4px;
  width: 1px;
  height: 7px;
  background: #cfc6a9;
}
.match-intro {
  position: absolute;
  left: 50%;
  top: 43%;
  transform: translate(-50%, -50%);
  text-align: center;
  opacity: 0;
  transition: opacity 0.35s ease;
}
.match-intro.show { opacity: 1; }
.match-intro .kicker { font-size: 8px; letter-spacing: 3px; color: #d2b071; }
.match-intro h2 {
  margin: 7px 0 2px;
  font: 800 46px/1 var(--ui-font);
  letter-spacing: 4px;
  color: #f0e5c4;
  text-shadow: 0 3px 24px rgba(0, 0, 0, 0.8);
}
.match-intro p { margin: 0; font-size: 9px; letter-spacing: 2px; color: #b5ad93; }

/* --------------------------------------------------------------------------
   Toast / boot error
   -------------------------------------------------------------------------- */

.toast {
  position: absolute;
  z-index: 30;
  left: 50%;
  top: 15%;
  transform: translate(-50%, -8px);
  opacity: 0;
  padding: 9px 16px;
  background: rgba(20, 22, 18, 0.94);
  border: 1px solid #8b7851;
  font-size: 9px;
  letter-spacing: 0.8px;
  color: #ddd4bc;
  pointer-events: none;
  transition: 0.18s ease;
}
.toast.show { opacity: 1; transform: translate(-50%, 0); }
.boot-error {
  position: absolute;
  z-index: 50;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 30px;
  text-align: center;
  background: #10110e;
}
.boot-error strong { font: 700 27px var(--ui-font); letter-spacing: 2px; color: #d9a95c; }
.boot-error span { font-size: 11px; color: #cfc6b3; max-width: 600px; }
.boot-error small { font-size: 9px; color: #807c6e; }

/* --------------------------------------------------------------------------
   Responsive layout
   -------------------------------------------------------------------------- */

@media (max-width: 980px) {
  .menu-layout {
    grid-template-columns: 240px 1fr;
    gap: 4%;
    left: 5%;
    right: 5%;
  }
  .feature-image { height: 190px; }
  .menu-card h2 { font-size: 31px; }
  .main-menu button { padding: 8px 12px; }
  .main-menu button small { display: none; }
  .brand { left: 5%; }
  .menu-footer { left: 5%; right: 5%; }
  .scoreboard-teams { grid-template-columns: 1fr; }
}

@media (max-width: 700px) {
  .menu-layout {
    display: flex;
    flex-direction: column;
    justify-content: center;
    top: 20%;
    gap: 17px;
  }
  .menu-card { display: none; }
  .main-menu { width: min(360px, 92vw); }
  .brand { top: 5%; }
  .radar-wrap { width: 100px; height: 112px; top: 9px; left: 9px; }
  .radar-wrap canvas { width: 100px; height: 100px; }
  .top-strip { top: 7px; min-width: 245px; padding: 4px 9px; gap: 6px; }
  .round-info { padding: 0 7px; min-width: 78px; }
  .round-info span, .round-info small { font-size: 6px; }
  .round-info b { font-size: 13px; }
  .team-chip { font-size: 9px; gap: 4px; }
  .team-chip strong { font-size: 14px; }
  .bottom-hud { left: 7px; right: 7px; bottom: 29px; gap: 5px; }
  .status-group, .ammo-box { height: 48px; min-width: 0; padding: 6px; gap: 5px; }
  .status-group { min-width: 130px; }
  .status-group strong { font-size: 14px; }
  .status-group small, .ammo-box small { font-size: 6px; }
  .health-icon, .shield-icon { font-size: 14px; }
  .hud-divider { margin: 0 2px; }
  .ammo-box { min-width: 140px; }
  .weapon-name strong { font-size: 13px; }
  .ammo-count strong { font-size: 18px; }
  .ammo-count span { font-size: 8px; }
  .ammo-count small { display: none; }
  .match-status { display: none; }
  .hint-bar { display: none; }
  .kill-feed { top: 64px; right: 7px; font-size: 8px; }
  .profile-layout { grid-template-columns: 1fr; gap: 15px; }
  .form-grid { grid-template-columns: 1fr; }
  .field.full { grid-column: auto; }
  .results-frame { padding: 19px; }
  .result-stats { grid-template-columns: 1fr 1fr; }
  .scoreboard { padding: 14px; }
  .quest { display: none; }
}

@media (max-height: 650px) {
  .brand { top: 3%; }
  .menu-layout { top: 17%; bottom: 8%; }
  .feature-image { height: 165px; }
  .menu-card h2 { font-size: 28px; }
  .menu-card > p { margin-bottom: 10px; }
}

