238:       size: 0.075,
239:       transparent: true,
240:       opacity: 0.3,
241:       depthWrite: false,
242:       sizeAttenuation: true,
243:     });
244:     this.dust = new THREE.Points(geometry, material);
245:     this.effectsGroup.add(this.dust);
