328:   createBots(config) {
329:     this.bots = [];
330:     const names = shuffle(CONFIG.botNames);
331:     let ctBots = 0;
332:     let tBots = 0;
333:     if (config.mode === 'tdm') {
334:       const totalPlayers = config.botCount + 1;
335:       const ctTotal = Math.ceil(totalPlayers / 2);
336:       ctBots = Math.max(0, ctTotal - (config.team === 'CT' ? 1 : 0));
337:       tBots = Math.max(0, config.botCount - ctBots);
338:       // Rebalance if the player's chosen side left an uneven count.
339:       const tTotal = totalPlayers - ctTotal;
340:       if (tBots > tTotal) { ctBots += tBots - tTotal; tBots = tTotal; }
341:       if (ctBots + tBots < config.botCount) ctBots += config.botCount - ctBots - tBots;
342:     }
343: 
344:     for (let i = 0; i < config.botCount; i++) {
345:       let team;
346:       let visualTeam;
347:       if (config.mode === 'tdm') {
348:         team = i < ctBots ? 'CT' : 'T';
349:         visualTeam = team;
350:       } else {
351:         team = 'FFA';
352:         visualTeam = i % 2 === 0 ? 'CT' : 'T';
353:       }
354:       const bot = new Bot({
355:         scene: this.scene,
356:         world: this.mapRuntime.world,
357:         nav: this.mapRuntime.nav,
358:         team,
359:         visualTeam,
360:         name: names[i % names.length] + (i >= names.length ? ` ${i + 1}` : ''),
361:         difficulty: config.difficulty,
362:         mode: config.mode,
363:         index: i,
364:         game: this,
365:       });
366:       const spawn = this.chooseSpawn(team, []);
367:       bot.spawn(spawn);
368:       this.bots.push(bot);
369:     }
370:   }
371: 
372:   chooseSpawn(team, enemies = []) {
373:     const pool = this.mode === 'ffa'
374:       ? this.mapDef.ffaSpawns
375:       : (this.mapDef.spawns[team] || this.mapDef.spawns.CT);
376:     if (!pool?.length) return { x: 0, z: 0, y: 0 };
377:     const allEnemies = enemies.length ? enemies : [
378:       ...this.bots.filter((b) => b.alive && (this.mode === 'ffa' || b.team !== team)),
379:       ...(this.player?.alive && (this.mode === 'ffa' || this.player.team !== team) ? [this.player] : []),
380:     ];
381:     let best = pool[0];
382:     let bestScore = -Infinity;
383:     for (const spawn of pool) {
384:       let nearest = 100;
385:       for (const enemy of allEnemies) {
386:         if (!enemy?.position) continue;
387:         nearest = Math.min(nearest, Math.hypot(spawn.x - enemy.position.x, spawn.z - enemy.position.z));
388:       }
389:       const score = nearest + rand(0, 4);
390:       if (score > bestScore) { bestScore = score; best = spawn; }
391:     }
392:     return { x: best.x, z: best.z, y: best.y ?? 0 };
393:   }
394: 
395:   playerYaw(spawn) {
396:     return Math.atan2(spawn.x, spawn.z);
397:   }
