399:   respawnPlayer() {
400:     if (!this.active || this.results) return;
401:     const spawn = this.chooseSpawn(this.player.team, []);
402:     this.player.respawn(spawn, this.playerYaw(spawn));
403:     this.lastDeathMessage = '';
404:     this.ui.banner('BACK IN THE FIGHT', 1400);
405:     this.requestPointerLock();
406:   }
