414:   getSortedParticipants() {
415:     if (!this.player) return [];
416:     const participants = [{
417:       name: this.player.name,
418:       team: this.mode === 'ffa' ? 'FFA' : this.player.team,
419:       kills: this.player.stats.kills,
420:       deaths: this.player.stats.deaths,
421:       alive: this.player.alive,
422:       isPlayer: true,
423:     }];
424:     for (const bot of this.bots) {
425:       participants.push({
426:         name: bot.name,
427:         team: this.mode === 'ffa' ? 'FFA' : bot.team,
428:         kills: bot.kills,
429:         deaths: bot.deaths,
430:         alive: bot.alive,
431:         isPlayer: false,
432:       });
433:     }
434:     participants.sort((a, b) => {
435:       if (this.mode === 'tdm' && a.team !== b.team) return a.team === 'CT' ? -1 : 1;
436:       if (b.kills !== a.kills) return b.kills - a.kills;
437:       return a.deaths - b.deaths;
438:     });
439:     return participants;
440:   }
441: 
442:   isEnemy(a, b) {
443:     if (!a || !b || a === b) return false;
444:     if (this.mode === 'ffa') return true;
445:     return a.team !== b.team;
446:   }
