448:   registerKill(killer, victim, weaponId = 'rifle', headshot = false) {
449:     if (!killer || !victim) return;
450:     if (killer === victim) return;
451:     const killerName = killer.name || 'Unknown';
452:     const victimName = victim.name || 'Unknown';
453:     const killerTeam = killer.team === 'FFA' ? 'FFA' : killer.team;
454:     const victimTeam = victim.team === 'FFA' ? 'FFA' : victim.team;
455:     if (killer === this.player) {
456:       this.player.stats.kills++;
457:       if (headshot) this.player.stats.headshots++;
458:       this.ui.banner(headshot ? 'HEADSHOT KILL' : 'TARGET DOWN', 1100);
459:     } else {
460:       killer.kills = (killer.kills || 0) + 1;
461:       if (headshot) killer.headshots = (killer.headshots || 0) + 1;
462:     }
463:     if (victim === this.player) {
464:       this.lastDeathMessage = `KILLED BY ${killerName.toUpperCase()}`;
465:     } else {
466:       victim.deaths = (victim.deaths || 0) + 1;
467:     }
468:     if (this.mode === 'tdm' && killer.team !== victim.team) {
469:       this.scores[killer.team] = (this.scores[killer.team] || 0) + 1;
470:     }
471:     this.ui.feed(killerName, victimName, killerTeam, victimTeam, headshot);
472:     if (killer === this.player) {
473:       audio.hitmarker(headshot);
474:     }
475:     this.updateMatchPoint();
476:     if (this.uiTimer <= 0) this.ui.updateHUD(this);
477:   }
