479:   updateMatchPoint() {
480:     const limit = this.matchConfig.scoreLimit;
481:     if (this.mode === 'tdm') {
482:       this.matchPoint = this.scores.CT === limit - 1 || this.scores.T === limit - 1;
483:     } else {
484:       const top = Math.max(this.player.stats.kills, ...this.bots.map((b) => b.kills));
485:       this.matchPoint = top === limit - 1;
486:     }
487:   }
