489:   checkEndConditions() {
490:     if (!this.active || this.results) return false;
491:     const limit = this.matchConfig.scoreLimit;
492:     if (this.mode === 'tdm') {
493:       if (this.scores.CT >= limit || this.scores.T >= limit) { this.endMatch('score limit'); return true; }
494:     } else if (Math.max(this.player.stats.kills, ...this.bots.map((b) => b.kills)) >= limit) {
495:       this.endMatch('score limit'); return true;
496:     }
497:     return false;
498:   }
