500:   endMatch(reason = 'time expired') {
501:     if (this.results || !this.active) return;
502:     this.results = true;
503:     this.paused = false;
504:     this.mouseDown = false;
505:     this.ui.hidePause();
506:     this.ui.hideScoreboard();
507:     if (document.pointerLockElement) document.exitPointerLock?.();
508:     const sorted = this.getSortedParticipants();
509:     const playerTeam = this.player.team;
510:     let playerWon = false;
511:     let draw = false;
512:     let winnerLabel = '';
513:     let winnerName = '';
514:     let winnerScore = 0;
515:     let finalScore = '';
516:     let playerPlace = sorted.findIndex((p) => p.isPlayer) + 1;
517: 
518:     if (this.mode === 'tdm') {
519:       finalScore = `${this.scores.CT} : ${this.scores.T}`;
520:       if (this.scores.CT === this.scores.T) {
521:         draw = true;
522:         winnerLabel = 'DRAW';
523:       } else {
524:         const winnerTeam = this.scores.CT > this.scores.T ? 'CT' : 'T';
525:         winnerLabel = winnerTeam === 'CT' ? 'COUNTER-TERRORISTS' : 'TERRORISTS';
526:         playerWon = winnerTeam === playerTeam;
527:       }
528:     } else {
529:       const winner = sorted[0];
530:       if (winner) {
531:         winnerName = winner.name;
532:         winnerScore = winner.kills;
533:         playerWon = winner.isPlayer;
534:         draw = sorted.length > 1 && sorted[0].kills === sorted[1].kills && sorted[0].deaths === sorted[1].deaths && !winner.isPlayer;
535:         if (draw) winnerLabel = 'DRAW';
536:       }
537:     }
538:     if (draw) playerWon = false;
539: 
540:     const playerKills = this.player.stats.kills;
541:     const playerDeaths = this.player.stats.deaths;
542:     const kd = playerDeaths > 0 ? (playerKills / playerDeaths).toFixed(2) : playerKills.toFixed(2);
543:     const rows = this.mode === 'tdm'
544:       ? sorted.map((p) => `<tr class="${p.isPlayer ? 'you' : ''}"><td><span class="team-dot team-${p.team}"></span>${escapeHtml(p.name)}${p.isPlayer ? ' <em>YOU</em>' : ''}</td><td>${p.team}</td><td>${p.kills}</td><td>${p.deaths}</td></tr>`).join('')
545:       : sorted.map((p, index) => `<tr class="${p.isPlayer ? 'you' : ''}"><td>${index + 1}</td><td>${escapeHtml(p.name)}${p.isPlayer ? ' <em>YOU</em>' : ''}</td><td>${p.kills}</td><td>${p.deaths}</td></tr>`).join('');
546:     const tableHead = this.mode === 'tdm'
547:       ? '<tr><th>OPERATOR</th><th>TEAM</th><th>K</th><th>D</th></tr>'
548:       : '<tr><th>#</th><th>OPERATOR</th><th>K</th><th>D</th></tr>';
549:     const table = `<table class="score-table"><thead>${tableHead}</thead><tbody>${rows}</tbody></table>`;
550: 
551:     if (!this.resultsRecorded) {
552:       settingsStore.recordMatch({ won: playerWon, kills: playerKills, deaths: playerDeaths });
553:       this.resultsRecorded = true;
554:     }
555:     this.ui.showResults({
556:       mode: this.mode,
557:       mapName: this.mapDef.name,
558:       scores: { ...this.scores },
559:       finalScore,
560:       winnerLabel,
561:       winnerName,
562:       winnerScore,
563:       draw,
564:       playerWon,
565:       playerPlace,
566:       playerKills,
567:       playerDeaths,
568:       playerKd: kd,
569:       headshots: this.player.stats.headshots,
570:       table,
571:       reason,
572:     });
573:     if (playerWon) audio.victory();
574:     else if (draw) audio.uiClick();
575:     else audio.defeat();
576:   }
