631:   bindInput() {
632:     window.addEventListener('keydown', (event) => {
633:       if (this.ui.panelScreen.classList.contains('visible')) return;
634:       if (event.target instanceof HTMLInputElement || event.target instanceof HTMLSelectElement || event.target instanceof HTMLTextAreaElement) return;
635:       if (['Space', 'Tab'].includes(event.code)) event.preventDefault();
636:       if (event.repeat) {
637:         if (this.active && !this.paused && !this.results) this.keys[event.code] = true;
638:         return;
639:       }
640:       if (!this.active || this.paused || this.results) return;
641:       this.keys[event.code] = true;
642:       if (event.code === 'Escape') {
643:         this.pause();
644:       } else if (event.code === 'Tab') {
645:         this.ui.showScoreboard(this);
646:       } else if (event.code === 'KeyR') {
647:         this.player?.startReload();
648:       } else if (event.code === 'Digit1') {
649:         this.player?.switchWeapon('rifle');
650:       } else if (event.code === 'Digit2') {
651:         this.player?.switchWeapon('pistol');
652:       }
653:     });
654: 
655:     window.addEventListener('keyup', (event) => {
656:       if (event.code === 'Tab' && this.ui.scoreboardVisible) this.ui.hideScoreboard();
657:       this.keys[event.code] = false;
658:     });
659: 
660:     window.addEventListener('blur', () => {
661:       this.keys = {};
662:       this.mouseDown = false;
663:       if (this.active && !this.paused && !this.results) this.pause();
664:     });
665: 
666:     document.addEventListener('visibilitychange', () => {
667:       if (document.hidden && this.active && !this.paused && !this.results) this.pause();
668:     });
669: 
670:     document.addEventListener('pointerlockchange', () => {
671:       const locked = document.pointerLockElement === this.canvas;
672:       this.ui.setPointerLocked(locked);
673:       if (!locked && this.wasPointerLocked && this.active && !this.paused && !this.results) {
674:         this.pause();
675:       }
676:       this.wasPointerLocked = locked;
677:     });
678: 
679:     document.addEventListener('pointerlockerror', () => {
680:       this.ui.toast('MOUSE CAPTURE WAS BLOCKED — CLICK THE GAME VIEW');
681:       this.ui.updatePrompt();
682:     });
683: 
684:     this.canvas.addEventListener('mousedown', (event) => {
685:       if (!this.active || this.paused || this.results) return;
686:       if (event.button !== 0) return;
687:       if (document.pointerLockElement !== this.canvas) {
688:         this.requestPointerLock();
689:         return;
690:       }
691:       this.mouseDown = true;
692:       this.player?.fire(this);
693:     });
694: 
695:     window.addEventListener('mouseup', (event) => {
696:       if (event.button === 0) {
697:         this.mouseDown = false;
698:         this.player?.releaseTrigger();
699:       }
700:     });
701: 
702:     document.addEventListener('mousemove', (event) => {
703:       if (document.pointerLockElement !== this.canvas || !this.active || this.paused || this.results) return;
704:       this.player?.look(event.movementX || 0, event.movementY || 0);
705:     });
706: 
707:     this.canvas.addEventListener('contextmenu', (event) => event.preventDefault());
708:     window.addEventListener('wheel', (event) => {
709:       if (!this.active || this.paused || this.results || !this.player?.alive) return;
710:       if (event.deltaY > 0) this.player.switchWeapon(this.player.weaponId === 'rifle' ? 'pistol' : 'rifle');
711:       else this.player.switchWeapon(this.player.weaponId === 'rifle' ? 'pistol' : 'rifle');
712:     }, { passive: true });
713: 
714:     window.addEventListener('resize', () => this.resize());
715:   }
