735:   animate() {
736:     requestAnimationFrame(this.animate);
737:     const dt = Math.min(0.05, this.clock.getDelta());
738:     this.fpsFrames++;
739:     this.fpsTimer += dt;
740:     if (this.fpsTimer >= 0.5) {
741:       this.fps = this.fpsFrames / this.fpsTimer;
742:       this.fpsFrames = 0;
743:       this.fpsTimer = 0;
744:       this.ui.setFps(this.fps);
745:     }
746: 
747:     if (!this.active) {
748:       this.updateMenu(dt);
749:       this.updateEffects(dt);
750:       this.renderer.render(this.scene, this.menuCamera);
751:       return;
752:     }
753: 
754:     if (!this.paused && !this.results) this.update(dt);
755:     else this.updateEffects(dt);
