19:   for (let i = 0; i < position.count; i++) {
20:     const y = position.getY(i) / 190;
21:     const t = Math.max(0, Math.min(1, (y + 0.15) / 0.9));
22:     color.copy(bottom).lerp(top, Math.pow(t, 0.72));
23:     colors.push(color.r, color.g, color.b);
24:   }
25:   geo.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
26:   const material = new THREE.MeshBasicMaterial({ vertexColors: true, side: THREE.BackSide, fog: false, depthWrite: false });
27:   const sky = new THREE.Mesh(geo, material);
28:   sky.renderOrder = -10;
29:   scene.add(sky);
30: 
31:   // A soft, static sun disc drawn into a canvas sprite.
32:   if (theme.sunDisc) {
33:     const canvas = document.createElement('canvas');
34:     canvas.width = canvas.height = 128;
35:     const ctx = canvas.getContext('2d');
36:     const grad = ctx.createRadialGradient(64, 64, 2, 64, 64, 64);
37:     grad.addColorStop(0, 'rgba(255,245,215,1)');
38:     grad.addColorStop(0.18, 'rgba(255,225,165,.95)');
39:     grad.addColorStop(0.45, 'rgba(255,200,120,.26)');
40:     grad.addColorStop(1, 'rgba(255,190,110,0)');
41:     ctx.fillStyle = grad;
42:     ctx.fillRect(0, 0, 128, 128);
43:     const texture = new THREE.CanvasTexture(canvas);
44:     texture.colorSpace = THREE.SRGBColorSpace;
45:     const material = new THREE.SpriteMaterial({ map: texture, transparent: true, depthWrite: false, fog: false, blending: THREE.AdditiveBlending });
46:     const sprite = new THREE.Sprite(material);
47:     sprite.scale.setScalar(42);
48:     const dir = new THREE.Vector3(...theme.sunDirection).normalize().multiplyScalar(160);
49:     sprite.position.copy(dir);
50:     scene.add(sprite);
51:     sky.userData.sun = sprite;
52:   }
53:   return sky;
54: }
