56: function createLighting(scene, theme, quality) {
57:   scene.background = new THREE.Color(theme.fogColor);
58:   scene.fog = new THREE.Fog(theme.fogColor, theme.fogNear, theme.fogFar);
59:   const hemi = new THREE.HemisphereLight(theme.hemiSky, theme.hemiGround, theme.hemiIntensity);
60:   scene.add(hemi);
61: 
62:   const sun = new THREE.DirectionalLight(theme.sunColor, theme.sunIntensity);
63:   sun.position.set(...theme.sunPosition);
64:   sun.target.position.set(0, 0, 0);
65:   scene.add(sun, sun.target);
66:   sun.castShadow = Boolean(quality.shadows);
67:   sun.shadow.mapSize.set(quality.shadowMap, quality.shadowMap);
68:   const extent = theme.shadowExtent;
69:   sun.shadow.camera.left = -extent;
70:   sun.shadow.camera.right = extent;
71:   sun.shadow.camera.top = extent;
72:   sun.shadow.camera.bottom = -extent;
73:   sun.shadow.camera.near = 1;
74:   sun.shadow.camera.far = 160;
75:   sun.shadow.bias = -0.0004;
76:   sun.shadow.normalBias = 0.035;
77:   scene.add(new THREE.AmbientLight(theme.ambientColor, theme.ambientIntensity));
78:   return { hemi, sun };
79: }
