509: export function createMap(scene, mapId, qualitySettings = CONFIG.quality.medium) {
510:   const definition = MAPS[mapId] || MAPS.old_quarter;
511:   // Clear any previous map lights/fog children from a prior match.
512:   scene.clear();
513:   const sky = createSky(scene, definition.theme);
514:   const lights = createLighting(scene, definition.theme, qualitySettings);
515:   setTextureAnisotropy(qualitySettings.anisotropy);
516:   const world = new World(scene, definition.bounds);
517:   definition.build(world);
518:   world.finalize();
519:   const nav = new NavGraph(definition.navNodes, world, { radius: 0.38 });
520:   return { definition, world, nav, sky, lights };
521: }
