523: export function getSpawn(mapRuntime, team, mode, spawnIndex = 0) {
524:   const { definition } = mapRuntime;
525:   const pool = mode === 'ffa' ? definition.ffaSpawns : (definition.spawns[team] || definition.spawns.CT);
526:   if (!pool.length) return { x: 0, z: 0, y: 0 };
527:   const spawn = pool[spawnIndex % pool.length];
528:   return { x: spawn.x, z: spawn.z, y: spawn.y ?? 0 };
529: }

