409:   buildRadarBackground() {
410:     if (!this.mapRuntime) return;
411:     const bounds = this.mapRuntime.world.bounds;
412:     this.radarBounds = bounds;
413:     const size = 200;
414:     const canvas = document.createElement('canvas');
415:     canvas.width = canvas.height = size;
416:     const ctx = canvas.getContext('2d');
417:     ctx.fillStyle = 'rgba(8, 18, 14, 0.74)';
418:     ctx.fillRect(0, 0, size, size);
419:     const scale = 176 / Math.max(bounds.maxX - bounds.minX, bounds.maxZ - bounds.minZ);
420:     const cx = (bounds.minX + bounds.maxX) / 2;
421:     const cz = (bounds.minZ + bounds.maxZ) / 2;
422:     const tx = (x) => size / 2 + (x - cx) * scale;
423:     const tz = (z) => size / 2 + (z - cz) * scale;
424:     for (const c of this.mapRuntime.world.colliders) {
425:       if (c.minY > 3 || c.maxY < 0.3) continue;
426:       const w = (c.maxX - c.minX) * scale;
427:       const h = (c.maxZ - c.minZ) * scale;
428:       if (w < 0.5 && h < 0.5) continue;
429:       ctx.fillStyle = c.maxY > 2 ? 'rgba(128, 134, 115, 0.34)' : 'rgba(149, 137, 105, 0.26)';
430:       ctx.fillRect(tx(c.minX), tz(c.minZ), Math.max(0.7, w), Math.max(0.7, h));
431:     }
432:     ctx.strokeStyle = 'rgba(206, 199, 164, 0.35)';
433:     ctx.lineWidth = 1.5;
434:     ctx.strokeRect(tx(bounds.minX), tz(bounds.minZ), (bounds.maxX - bounds.minX) * scale, (bounds.maxZ - bounds.minZ) * scale);
435:     this.radarBg = canvas;
436:   }
437: 
438:   updateRadar(game) {
439:     if (!this.radarBg || !this.mapRuntime) return;
440:     const canvas = $('#radar');
441:     const ctx = canvas.getContext('2d');
442:     const size = canvas.width;
443:     ctx.clearRect(0, 0, size, size);
444:     ctx.save();
445:     ctx.beginPath();
446:     ctx.arc(size / 2, size / 2, size / 2 - 4, 0, Math.PI * 2);
447:     ctx.clip();
448:     ctx.drawImage(this.radarBg, 0, 0, size, size);
449:     const bounds = this.radarBounds;
450:     const scale = (176 / Math.max(bounds.maxX - bounds.minX, bounds.maxZ - bounds.minZ)) * (size / 200);
451:     const cx = (bounds.minX + bounds.maxX) / 2;
452:     const cz = (bounds.minZ + bounds.maxZ) / 2;
453:     const tx = (x) => size / 2 + (x - cx) * scale;
454:     const tz = (z) => size / 2 + (z - cz) * scale;
455:     const player = game.player;
456:     const px = tx(player.position.x);
457:     const py = tz(player.position.z);
458: 
459:     // View cone
460:     const yaw = player.yaw;
461:     const angle = Math.atan2(Math.cos(yaw), -Math.sin(yaw));
462:     ctx.fillStyle = 'rgba(196, 207, 167, 0.12)';
463:     ctx.beginPath();
464:     ctx.moveTo(px, py);
465:     ctx.arc(px, py, 26, angle - 0.48, angle + 0.48);
466:     ctx.closePath();
467:     ctx.fill();
468: 
469:     for (const bot of game.bots) {
470:       if (!bot.alive) continue;
471:       const enemy = game.isEnemy(player, bot);
472:       const x = tx(bot.position.x);
473:       const y = tz(bot.position.z);
474:       if (Math.hypot(x - size / 2, y - size / 2) > size / 2 - 7) continue;
475:       ctx.beginPath();
476:       ctx.fillStyle = enemy ? '#d2674f' : '#6ea4ba';
477:       ctx.shadowColor = enemy ? 'rgba(210,103,79,.8)' : 'rgba(110,164,186,.8)';
478:       ctx.shadowBlur = 5;
479:       ctx.arc(x, y, enemy ? 3.6 : 3, 0, Math.PI * 2);
480:       ctx.fill();
481:     }
482:     ctx.shadowBlur = 0;
483:     // Player arrow
484:     ctx.save();
485:     ctx.translate(px, py);
486:     ctx.rotate(angle + Math.PI / 2);
487:     ctx.fillStyle = '#e3d7aa';
488:     ctx.beginPath();
489:     ctx.moveTo(0, -6);
490:     ctx.lineTo(4.2, 4.5);
491:     ctx.lineTo(0, 2.5);
492:     ctx.lineTo(-4.2, 4.5);
493:     ctx.closePath();
494:     ctx.fill();
495:     ctx.restore();
496:     ctx.restore();
497:     ctx.strokeStyle = 'rgba(216, 207, 172, 0.34)';
498:     ctx.lineWidth = 1.5;
499:     ctx.beginPath();
500:     ctx.arc(size / 2, size / 2, size / 2 - 4, 0, Math.PI * 2);
501:     ctx.stroke();
502:   }
