312: function getTexture(name, args) {
313:   const key = args ? `${name}:${args.join(',')}` : name;
314:   if (!textureCache.has(key)) {
315:     const factory = textures[name];
316:     textureCache.set(key, factory ? factory(...(args || [])) : null);
317:   }
318:   return textureCache.get(key);
319: }
