321: export function getMaterial(name) {
322:   if (materials.has(name)) return materials.get(name);
323:   const def = materialDefs[name] || materialDefs.concrete;
324:   const options = { roughness: def.roughness ?? 0.9 };
325:   if (def.texture) options.map = getTexture(def.texture, def.textureArgs);
326:   if (def.color !== undefined) options.color = def.color;
327:   if (def.metalness !== undefined) options.metalness = def.metalness;
328:   if (def.emissive !== undefined) options.emissive = def.emissive;
329:   if (def.emissiveIntensity !== undefined) options.emissiveIntensity = def.emissiveIntensity;
330:   if (def.transparent) { options.transparent = true; options.opacity = def.opacity; }
331:   const material = new THREE.MeshStandardMaterial(options);
332:   material.userData.uv = def.uv ?? 0.35;
333:   materials.set(name, material);
