411:   buildRadarBackground() {
412:     if (!this.mapRuntime) return;
413:     const bounds = this.mapRuntime.world.bounds;
414:     this.radarBounds = bounds;
415:     const size = 200;
416:     const canvas = document.createElement('canvas');
417:     canvas.width = canvas.height = size;
418:     const ctx = canvas.getContext('2d');
419:     ctx.fillStyle = 'rgba(8, 18, 14, 0.74)';
420:     ctx.fillRect(0, 0, size, size);
421:     const scale = 176 / Math.max(bounds.maxX - bounds.minX, bounds.maxZ - bounds.minZ);
422:     const cx = (bounds.minX + bounds.maxX) / 2;
423:     const cz = (bounds.minZ + bounds.maxZ) / 2;
424:     const tx = (x) => size / 2 + (x - cx) * scale;
425:     const tz = (z) => size / 2 + (z - cz) * scale;
426:     for (const c of this.mapRuntime.world.colliders) {
427:       if (c.minY > 3 || c.maxY < 0.3) continue;
428:       const w = (c.maxX - c.minX) * scale;
429:       const h = (c.maxZ - c.minZ) * scale;
430:       if (w < 0.5 && h < 0.5) continue;
431:       ctx.fillStyle = c.maxY > 2 ? 'rgba(128, 134, 115, 0.34)' : 'rgba(149, 137, 105, 0.26)';
432:       ctx.fillRect(tx(c.minX), tz(c.minZ), Math.max(0.7, w), Math.max(0.7, h));
433:     }
434:     ctx.strokeStyle = 'rgba(206, 199, 164, 0.35)';
435:     ctx.lineWidth = 1.5;
436:     ctx.strokeRect(tx(bounds.minX), tz(bounds.minZ), (bounds.maxX - bounds.minX) * scale, (bounds.maxZ - bounds.minZ) * scale);
437:     this.radarBg = canvas;
438:   }
439: 
440:   updateRadar(game) {
441:     if (!this.radarBg || !this.mapRuntime) return;
442:     const canvas = $('#radar');
443:     const ctx = canvas.getContext('2d');
444:     const size = canvas.width;
445:     ctx.clearRect(0, 0, size, size);
446:     ctx.save();
447:     ctx.beginPath();
448:     ctx.arc(size / 2, size / 2, size / 2 - 4, 0, Math.PI * 2);
449:     ctx.clip();
450:     ctx.drawImage(this.radarBg, 0, 0, size, size);
451:     const bounds = this.radarBounds;
452:     const scale = (176 / Math.max(bounds.maxX - bounds.minX, bounds.maxZ - bounds.minZ)) * (size / 200);
453:     const cx = (bounds.minX + bounds.maxX) / 2;
454:     const cz = (bounds.minZ + bounds.maxZ) / 2;
455:     const tx = (x) => size / 2 + (x - cx) * scale;
456:     const tz = (z) => size / 2 + (z - cz) * scale;
457:     const player = game.player;
458:     const px = tx(player.position.x);
459:     const py = tz(player.position.z);
460: 
461:     // View cone. Canvas +Y is south, matching world +Z.
462:     const yaw = player.yaw;
463:     const angle = Math.atan2(-Math.cos(yaw), -Math.sin(yaw));
464:     ctx.fillStyle = 'rgba(196, 207, 167, 0.12)';
465:     ctx.beginPath();
466:     ctx.moveTo(px, py);
467:     ctx.arc(px, py, 26, angle - 0.48, angle + 0.48);
468:     ctx.closePath();
469:     ctx.fill();
470: 
471:     for (const bot of game.bots) {
472:       if (!bot.alive) continue;
473:       const enemy = game.isEnemy(player, bot);
474:       const x = tx(bot.position.x);
475:       const y = tz(bot.position.z);
476:       if (Math.hypot(x - size / 2, y - size / 2) > size / 2 - 7) continue;
477:       ctx.beginPath();
478:       ctx.fillStyle = enemy ? '#d2674f' : '#6ea4ba';
479:       ctx.shadowColor = enemy ? 'rgba(210,103,79,.8)' : 'rgba(110,164,186,.8)';
480:       ctx.shadowBlur = 5;
481:       ctx.arc(x, y, enemy ? 3.6 : 3, 0, Math.PI * 2);
482:       ctx.fill();
483:     }
484:     ctx.shadowBlur = 0;
485:     // Player arrow
486:     ctx.save();
487:     ctx.translate(px, py);
488:     ctx.rotate(angle + Math.PI / 2);
489:     ctx.fillStyle = '#e3d7aa';
490:     ctx.beginPath();
491:     ctx.moveTo(0, -6);
492:     ctx.lineTo(4.2, 4.5);
493:     ctx.lineTo(0, 2.5);
494:     ctx.lineTo(-4.2, 4.5);
495:     ctx.closePath();
496:     ctx.fill();
497:     ctx.restore();
498:     ctx.restore();
499:     ctx.strokeStyle = 'rgba(216, 207, 172, 0.34)';
500:     ctx.lineWidth = 1.5;
501:     ctx.beginPath();
502:     ctx.arc(size / 2, size / 2, size / 2 - 4, 0, Math.PI * 2);
503:     ctx.stroke();
504:   }
