23: function raySphere(origin, direction, center, radius) {
24:   const ox = center.x - origin.x;
25:   const oy = center.y - origin.y;
26:   const oz = center.z - origin.z;
27:   const tca = ox * direction.x + oy * direction.y + oz * direction.z;
28:   if (tca < 0) return null;
29:   const d2 = ox * ox + oy * oy + oz * oz - tca * tca;
30:   const r2 = radius * radius;
31:   if (d2 > r2) return null;
32:   const thc = Math.sqrt(r2 - d2);
33:   const t0 = tca - thc;
34:   const t1 = tca + thc;
35:   if (t1 < 0) return null;
36:   return t0 >= 0 ? t0 : t1;
37: }
