334:   createBots(config) {
335:     this.bots = [];
336:     const names = shuffle(CONFIG.botNames);
337:     let ctBots = 0;
338:     let tBots = 0;
339:     if (config.mode === 'tdm') {
340:       const totalPlayers = config.botCount + 1;
341:       const ctTotal = Math.ceil(totalPlayers / 2);
342:       ctBots = Math.max(0, ctTotal - (config.team === 'CT' ? 1 : 0));
343:       tBots = Math.max(0, config.botCount - ctBots);
344:       // Rebalance if the player's chosen side left an uneven count.
345:       const tTotal = totalPlayers - ctTotal;
346:       if (tBots > tTotal) { ctBots += tBots - tTotal; tBots = tTotal; }
347:       if (ctBots + tBots < config.botCount) ctBots += config.botCount - ctBots - tBots;
348:     }
349: 
350:     for (let i = 0; i < config.botCount; i++) {
351:       let team;
352:       let visualTeam;
353:       if (config.mode === 'tdm') {
354:         team = i < ctBots ? 'CT' : 'T';
355:         visualTeam = team;
356:       } else {
357:         team = 'FFA';
358:         visualTeam = i % 2 === 0 ? 'CT' : 'T';
359:       }
360:       const bot = new Bot({
361:         scene: this.scene,
362:         world: this.mapRuntime.world,
363:         nav: this.mapRuntime.nav,
364:         team,
365:         visualTeam,
366:         name: names[i % names.length] + (i >= names.length ? ` ${i + 1}` : ''),
367:         difficulty: config.difficulty,
368:         mode: config.mode,
369:         index: i,
370:         game: this,
371:       });
372:       const spawn = this.chooseSpawn(team, []);
373:       bot.spawn(spawn);
374:       this.bots.push(bot);
375:     }
376:   }
