378:   chooseSpawn(team, enemies = []) {
379:     const pool = this.mode === 'ffa'
380:       ? this.mapDef.ffaSpawns
381:       : (this.mapDef.spawns[team] || this.mapDef.spawns.CT);
382:     if (!pool?.length) return { x: 0, z: 0, y: 0 };
383:     const allEnemies = enemies.length ? enemies : [
384:       ...this.bots.filter((b) => b.alive && (this.mode === 'ffa' || b.team !== team)),
385:       ...(this.player?.alive && (this.mode === 'ffa' || this.player.team !== team) ? [this.player] : []),
386:     ];
387:     const occupied = [
388:       ...this.bots.filter((b) => b.alive),
389:       ...(this.player?.alive ? [this.player] : []),
390:     ];
391:     let best = pool[0];
392:     let bestScore = -Infinity;
393:     for (const spawn of pool) {
394:       let nearestEnemy = 100;
395:       for (const enemy of allEnemies) {
396:         if (!enemy?.position) continue;
397:         nearestEnemy = Math.min(nearestEnemy, Math.hypot(spawn.x - enemy.position.x, spawn.z - enemy.position.z));
398:       }
399:       // Also avoid dropping a wave of respawns onto the same marker.
400:       let nearestOccupied = 100;
401:       for (const other of occupied) {
402:         if (!other?.position) continue;
403:         nearestOccupied = Math.min(nearestOccupied, Math.hypot(spawn.x - other.position.x, spawn.z - other.position.z));
404:       }
405:       const spacing = Math.min(8, nearestOccupied) * 0.9;
406:       const score = nearestEnemy + spacing + rand(0, 4);
407:       if (score > bestScore) { bestScore = score; best = spawn; }
408:     }
409:     return { x: best.x, z: best.z, y: best.y ?? 0 };
410:   }
