431:   getSortedParticipants() {
432:     if (!this.player) return [];
433:     const participants = [{
434:       name: this.player.name,
435:       team: this.mode === 'ffa' ? 'FFA' : this.player.team,
436:       kills: this.player.stats.kills,
437:       deaths: this.player.stats.deaths,
438:       alive: this.player.alive,
439:       isPlayer: true,
440:     }];
441:     for (const bot of this.bots) {
442:       participants.push({
443:         name: bot.name,
444:         team: this.mode === 'ffa' ? 'FFA' : bot.team,
445:         kills: bot.kills,
446:         deaths: bot.deaths,
447:         alive: bot.alive,
448:         isPlayer: false,
449:       });
450:     }
451:     participants.sort((a, b) => {
452:       if (this.mode === 'tdm' && a.team !== b.team) return a.team === 'CT' ? -1 : 1;
453:       if (b.kills !== a.kills) return b.kills - a.kills;
454:       return a.deaths - b.deaths;
455:     });
456:     return participants;
457:   }
