465:   registerKill(killer, victim, weaponId = 'rifle', headshot = false) {
466:     if (!killer || !victim) return;
467:     if (killer === victim) return;
468:     const killerName = killer.name || 'Unknown';
469:     const victimName = victim.name || 'Unknown';
470:     const killerTeam = killer.team === 'FFA' ? 'FFA' : killer.team;
471:     const victimTeam = victim.team === 'FFA' ? 'FFA' : victim.team;
472:     if (killer === this.player) {
473:       this.player.stats.kills++;
474:       if (headshot) this.player.stats.headshots++;
475:       this.ui.banner(headshot ? 'HEADSHOT KILL' : 'TARGET DOWN', 1100);
476:     } else {
477:       killer.kills = (killer.kills || 0) + 1;
478:       if (headshot) killer.headshots = (killer.headshots || 0) + 1;
479:     }
480:     if (victim === this.player) {
481:       this.lastDeathMessage = `KILLED BY ${killerName.toUpperCase()}`;
482:     } else {
483:       victim.deaths = (victim.deaths || 0) + 1;
484:     }
485:     if (this.mode === 'tdm' && killer.team !== victim.team) {
486:       this.scores[killer.team] = (this.scores[killer.team] || 0) + 1;
487:     }
488:     this.ui.feed(killerName, victimName, killerTeam, victimTeam, headshot);
489:     if (killer === this.player) {
490:       audio.hitmarker(headshot);
491:     }
492:     this.updateMatchPoint();
493:     if (this.uiTimer <= 0) this.ui.updateHUD(this);
494:   }
