496:   updateMatchPoint() {
497:     const limit = this.matchConfig.scoreLimit;
498:     if (this.mode === 'tdm') {
499:       this.matchPoint = this.scores.CT === limit - 1 || this.scores.T === limit - 1;
500:     } else {
501:       const top = Math.max(this.player.stats.kills, ...this.bots.map((b) => b.kills));
502:       this.matchPoint = top === limit - 1;
503:     }
504:   }
505: 
506:   checkEndConditions() {
507:     if (!this.active || this.results) return false;
508:     const limit = this.matchConfig.scoreLimit;
509:     if (this.mode === 'tdm') {
510:       if (this.scores.CT >= limit || this.scores.T >= limit) { this.endMatch('score limit'); return true; }
511:     } else if (Math.max(this.player.stats.kills, ...this.bots.map((b) => b.kills)) >= limit) {
512:       this.endMatch('score limit'); return true;
513:     }
514:     return false;
515:   }
