517:   endMatch(reason = 'time expired') {
518:     if (this.results || !this.active) return;
519:     this.results = true;
520:     this.paused = false;
521:     this.mouseDown = false;
522:     this.ui.hidePause();
523:     this.ui.hideScoreboard();
524:     if (document.pointerLockElement) document.exitPointerLock?.();
525:     const sorted = this.getSortedParticipants();
526:     const playerTeam = this.player.team;
527:     let playerWon = false;
528:     let draw = false;
529:     let winnerLabel = '';
530:     let winnerName = '';
531:     let winnerScore = 0;
532:     let finalScore = '';
533:     let playerPlace = sorted.findIndex((p) => p.isPlayer) + 1;
534: 
535:     if (this.mode === 'tdm') {
536:       if (this.scores.CT === this.scores.T) {
537:         draw = true;
538:         winnerLabel = 'DRAW';
539:         finalScore = `${this.scores.CT} : ${this.scores.T}`;
540:       } else {
541:         const winnerTeam = this.scores.CT > this.scores.T ? 'CT' : 'T';
542:         winnerLabel = winnerTeam === 'CT' ? 'COUNTER-TERRORISTS' : 'TERRORISTS';
543:         finalScore = winnerTeam === 'CT'
544:           ? `${this.scores.CT} : ${this.scores.T}`
545:           : `${this.scores.T} : ${this.scores.CT}`;
546:         playerWon = winnerTeam === playerTeam;
547:       }
548:     } else {
549:       const winner = sorted[0];
550:       if (winner) {
551:         winnerName = winner.name;
552:         winnerScore = winner.kills;
553:         playerWon = winner.isPlayer;
554:         draw = sorted.length > 1 && sorted[0].kills === sorted[1].kills && sorted[0].deaths === sorted[1].deaths && !winner.isPlayer;
555:         if (draw) winnerLabel = 'DRAW';
556:       }
557:     }
558:     if (draw) playerWon = false;
559: 
560:     const playerKills = this.player.stats.kills;
561:     const playerDeaths = this.player.stats.deaths;
562:     const kd = playerDeaths > 0 ? (playerKills / playerDeaths).toFixed(2) : playerKills.toFixed(2);
563:     const rows = this.mode === 'tdm'
564:       ? sorted.map((p) => `<tr class="${p.isPlayer ? 'you' : ''}"><td><span class="team-dot team-${p.team}"></span>${escapeHtml(p.name)}${p.isPlayer ? ' <em>YOU</em>' : ''}</td><td>${p.team}</td><td>${p.kills}</td><td>${p.deaths}</td></tr>`).join('')
565:       : sorted.map((p, index) => `<tr class="${p.isPlayer ? 'you' : ''}"><td>${index + 1}</td><td>${escapeHtml(p.name)}${p.isPlayer ? ' <em>YOU</em>' : ''}</td><td>${p.kills}</td><td>${p.deaths}</td></tr>`).join('');
566:     const tableHead = this.mode === 'tdm'
567:       ? '<tr><th>OPERATOR</th><th>TEAM</th><th>K</th><th>D</th></tr>'
568:       : '<tr><th>#</th><th>OPERATOR</th><th>K</th><th>D</th></tr>';
569:     const table = `<table class="score-table"><thead>${tableHead}</thead><tbody>${rows}</tbody></table>`;
570: 
571:     if (!this.resultsRecorded) {
572:       settingsStore.recordMatch({ won: playerWon, kills: playerKills, deaths: playerDeaths });
573:       this.resultsRecorded = true;
574:     }
575:     this.ui.showResults({
576:       mode: this.mode,
577:       mapName: this.mapDef.name,
578:       scores: { ...this.scores },
579:       finalScore,
580:       winnerLabel,
581:       winnerName,
582:       winnerScore,
583:       draw,
584:       playerWon,
585:       playerPlace,
586:       playerKills,
587:       playerDeaths,
588:       playerKd: kd,
589:       headshots: this.player.stats.headshots,
590:       table,
591:       reason,
592:     });
593:     if (playerWon) audio.victory();
594:     else if (draw) audio.uiClick();
595:     else audio.defeat();
596:   }
