651:   bindInput() {
652:     window.addEventListener('keydown', (event) => {
653:       if (this.ui.panelScreen.classList.contains('visible')) return;
654:       if (event.target instanceof HTMLInputElement || event.target instanceof HTMLSelectElement || event.target instanceof HTMLTextAreaElement) return;
655:       if (['Space', 'Tab'].includes(event.code)) event.preventDefault();
656:       if (event.repeat) {
657:         if (this.active && !this.paused && !this.results) this.keys[event.code] = true;
658:         return;
659:       }
660:       if (!this.active || this.paused || this.results) return;
661:       this.keys[event.code] = true;
662:       if (event.code === 'Escape') {
663:         this.pause();
664:       } else if (event.code === 'Tab') {
665:         this.ui.showScoreboard(this);
666:       } else if (event.code === 'KeyR') {
667:         this.player?.startReload();
668:       } else if (event.code === 'Digit1') {
669:         this.player?.switchWeapon('rifle');
670:       } else if (event.code === 'Digit2') {
671:         this.player?.switchWeapon('pistol');
672:       }
673:     });
674: 
675:     window.addEventListener('keyup', (event) => {
676:       if (event.code === 'Tab' && this.ui.scoreboardVisible) this.ui.hideScoreboard();
677:       this.keys[event.code] = false;
678:     });
679: 
680:     window.addEventListener('blur', () => {
681:       this.keys = {};
682:       this.mouseDown = false;
683:       if (this.active && !this.paused && !this.results) this.pause();
684:     });
685: 
686:     document.addEventListener('visibilitychange', () => {
687:       if (document.hidden && this.active && !this.paused && !this.results) this.pause();
688:     });
689: 
690:     document.addEventListener('pointerlockchange', () => {
691:       const locked = document.pointerLockElement === this.canvas;
692:       this.ui.setPointerLocked(locked);
693:       if (!locked && this.wasPointerLocked && this.active && !this.paused && !this.results) {
694:         this.pause();
695:       }
696:       this.wasPointerLocked = locked;
697:     });
698: 
699:     document.addEventListener('pointerlockerror', () => {
700:       this.ui.toast('MOUSE CAPTURE WAS BLOCKED — CLICK THE GAME VIEW');
701:       this.ui.updatePrompt();
702:     });
703: 
704:     this.canvas.addEventListener('mousedown', (event) => {
705:       if (!this.active || this.paused || this.results) return;
706:       if (event.button !== 0) return;
707:       if (document.pointerLockElement !== this.canvas) {
708:         this.requestPointerLock();
709:         return;
710:       }
711:       this.mouseDown = true;
712:       this.player?.fire(this);
713:     });
714: 
715:     window.addEventListener('mouseup', (event) => {
716:       if (event.button === 0) {
717:         this.mouseDown = false;
718:         this.player?.releaseTrigger();
719:       }
720:     });
721: 
722:     document.addEventListener('mousemove', (event) => {
723:       if (document.pointerLockElement !== this.canvas || !this.active || this.paused || this.results) return;
724:       this.player?.look(event.movementX || 0, event.movementY || 0);
725:     });
726: 
727:     this.canvas.addEventListener('contextmenu', (event) => event.preventDefault());
728:     window.addEventListener('wheel', (event) => {
729:       if (!this.active || this.paused || this.results || !this.player?.alive) return;
730:       if (event.deltaY > 0) this.player.switchWeapon(this.player.weaponId === 'rifle' ? 'pistol' : 'rifle');
731:       else this.player.switchWeapon(this.player.weaponId === 'rifle' ? 'pistol' : 'rifle');
732:     }, { passive: true });
733: 
734:     window.addEventListener('resize', () => this.resize());
