755:   animate() {
756:     requestAnimationFrame(this.animate);
757:     const dt = Math.min(0.05, this.clock.getDelta());
758:     this.fpsFrames++;
759:     this.fpsTimer += dt;
760:     if (this.fpsTimer >= 0.5) {
761:       this.fps = this.fpsFrames / this.fpsTimer;
762:       this.fpsFrames = 0;
763:       this.fpsTimer = 0;
764:       this.ui.setFps(this.fps);
765:     }
766: 
767:     if (!this.active) {
768:       this.updateMenu(dt);
769:       this.updateEffects(dt);
770:       this.renderer.render(this.scene, this.menuCamera);
771:       return;
772:     }
773: 
774:     if (!this.paused && !this.results) this.update(dt);
775:     else this.updateEffects(dt);
776:     if (this.player) {
777:       this.ui.updateCrosshair(this);
778:       if (!this.paused && !this.results) this.ui.updatePrompt();
779:     }
780:     this.renderer.render(this.scene, this.player?.camera || this.menuCamera);
781:   }
