783:   updateMenu(dt) {
784:     this.menuTime += dt;
785:     const angle = this.menuTime * 0.055 + 0.8;
786:     const radius = 31;
787:     this.menuCamera.position.set(Math.cos(angle) * radius, 10.5 + Math.sin(this.menuTime * 0.13) * 1.2, Math.sin(angle) * radius);
788:     this.menuCamera.lookAt(0, 2.2, 0);
789:   }
