791:   update(dt) {
792:     this.elapsed += dt;
793:     this.uiTimer -= dt;
794:     this.radarTimer -= dt;
795: 
796:     if (this.player) {
797:       const input = {
798:         forward: Boolean(this.keys.KeyW || this.keys.ArrowUp),
799:         back: Boolean(this.keys.KeyS || this.keys.ArrowDown),
800:         left: Boolean(this.keys.KeyA || this.keys.ArrowLeft),
801:         right: Boolean(this.keys.KeyD || this.keys.ArrowRight),
802:         sprint: Boolean(this.keys.ShiftLeft || this.keys.ShiftRight),
803:         crouch: Boolean(this.keys.ControlLeft || this.keys.ControlRight || this.keys.KeyC),
804:         jump: Boolean(this.keys.Space),
805:       };
806:       this.player.update(dt, input);
807:       if (this.mouseDown && this.player.alive && this.player.weapon.automatic) {
808:         this.player.fire(this);
809:       }
810:       if (!this.player.alive && this.player.respawnTimer <= 0) this.respawnPlayer();
811:     }
812: 
813:     const ctx = {
814:       player: this.player,
815:       bots: this.bots,
816:       time: this.elapsed,
817:       game: this,
818:     };
819:     for (const bot of this.bots) bot.update(dt, ctx);
820: 
821:     this.timeLeft -= dt;
822:     if (this.timeLeft <= 0) {
823:       this.timeLeft = 0;
824:       this.endMatch('time expired');
825:       return;
826:     }
827: 
828:     this.updateEffects(dt);
829:     this.checkEndConditions();
830: 
831:     if (this.uiTimer <= 0) {
832:       this.uiTimer = 0.1;
833:       this.ui.updateHUD(this);
834:     }
835:     if (this.radarTimer <= 0) {
836:       this.radarTimer = 0.08;
837:       this.ui.updateRadar(this);
838:     }
839:   }
840: 
841:   updateEffects(dt) {
842:     for (const tracer of this.tracers) {
843:       if (tracer.life > 0) {
844:         tracer.life -= dt;
845:         tracer.line.material.opacity = clamp(tracer.life / tracer.maxLife, 0, 1) * 0.85;
846:         if (tracer.life <= 0) tracer.line.visible = false;
847:       }
848:     }
849:     for (const spark of this.sparks) {
850:       if (spark.life > 0) {
851:         spark.life -= dt;
852:         spark.mesh.position.addScaledVector(spark.velocity, dt);
853:         spark.velocity.y -= 9 * dt;
854:         const scale = Math.max(0.05, spark.life * 4);
855:         spark.mesh.scale.setScalar(scale);
856:         if (spark.life <= 0) spark.mesh.visible = false;
857:       }
858:     }
859:     if (this.dust) {
860:       this.dust.rotation.y += dt * 0.003;
861:       const positions = this.dust.geometry.attributes.position;
862:       for (let i = 0; i < positions.count; i += 5) {
863:         positions.setY(i, positions.getY(i) + Math.sin(this.elapsed * 0.2 + i) * dt * 0.06);
864:       }
865:       positions.needsUpdate = true;
866:     }
867:   }
868: 
869:   addTracer(from, to, color = 0xffd79a) {
870:     const tracer = this.tracers[this.tracerIndex];
871:     if (!tracer) return;
872:     this.tracerIndex = (this.tracerIndex + 1) % this.tracers.length;
873:     const positions = tracer.line.geometry.attributes.position;
874:     positions.setXYZ(0, from.x, from.y, from.z);
875:     positions.setXYZ(1, to.x, to.y, to.z);
876:     positions.needsUpdate = true;
877:     tracer.line.geometry.computeBoundingSphere();
878:     tracer.line.material.color.setHex(color);
879:     tracer.line.material.opacity = 0.85;
880:     tracer.line.visible = true;
881:     tracer.life = 0.055;
882:     tracer.maxLife = 0.055;
883:   }
884: 
885:   spawnImpact(point, color = 0xffc27d, count = 5) {
886:     for (let i = 0; i < count; i++) {
887:       const spark = this.sparks[this.sparkIndex];
888:       this.sparkIndex = (this.sparkIndex + 1) % this.sparks.length;
889:       spark.mesh.position.copy(point);
890:       spark.mesh.visible = true;
891:       spark.mesh.scale.setScalar(1);
892:       spark.mesh.material.color.setHex(color);
893:       spark.life = rand(0.12, 0.28);
894:       spark.velocity.set(rand(-2.2, 2.2), rand(0.8, 3.4), rand(-2.2, 2.2));
895:     }
896:   }
897: 
898:   muzzlePosition(side = 0.18) {
899:     const forward = new THREE.Vector3(0, 0, -1).applyQuaternion(this.camera.quaternion);
900:     const right = new THREE.Vector3(1, 0, 0).applyQuaternion(this.camera.quaternion);
901:     const up = new THREE.Vector3(0, 1, 0).applyQuaternion(this.camera.quaternion);
902:     return this.camera.position.clone().addScaledVector(forward, 0.8).addScaledVector(right, side).addScaledVector(up, -0.18);
903:   }
904: 
905:   playerShoot(player, weapon, spread) {
906:     if (!this.active || this.results || !player.alive) return;
907:     const origin = this.camera.position.clone();
908:     const forward = new THREE.Vector3(0, 0, -1).applyQuaternion(this.camera.quaternion).normalize();
909:     const right = new THREE.Vector3(1, 0, 0).applyQuaternion(this.camera.quaternion);
910:     const up = new THREE.Vector3(0, 1, 0).applyQuaternion(this.camera.quaternion);
911:     const tangent = Math.tan(spread);
912:     const direction = forward.clone()
913:       .addScaledVector(right, rand(-1, 1) * tangent)
914:       .addScaledVector(up, rand(-1, 1) * tangent)
915:       .normalize();
916:     const maxRange = weapon.range;
917:     const end = origin.clone().addScaledVector(direction, maxRange);
918:     // segmentHitFraction returns a 0..1 fraction along the segment. Convert it
919:     // to a world distance before comparing against sphere hits.
920:     const wallT = this.mapRuntime.world.segmentHitFraction(origin, end);
921:     let wallDistance = wallT === null ? maxRange : Math.min(maxRange, wallT * maxRange);
922:     // Ground plane
923:     if (direction.y < -0.001) {
924:       const groundDistance = -origin.y / direction.y;
925:       if (groundDistance > 0 && groundDistance < wallDistance) wallDistance = groundDistance;
926:     }
927:     let hitBot = null;
928:     let hitPart = null;
929:     let hitT = wallDistance;
930:     for (const bot of this.bots) {
931:       if (!bot.alive || !this.isEnemy(player, bot)) continue;
932:       const px = bot.position.x, py = bot.position.y, pz = bot.position.z;
933:       const spheres = [
934:         { x: px, y: py + 1.72, z: pz, r: 0.23, part: 'head' },
935:         { x: px, y: py + 1.25, z: pz, r: 0.36, part: 'body' },
936:         { x: px, y: py + 0.75, z: pz, r: 0.33, part: 'legs' },
937:       ];
938:       for (const sphere of spheres) {
939:         const t = raySphere(origin, direction, { x: sphere.x, y: sphere.y, z: sphere.z }, sphere.r);
940:         if (t !== null && t < hitT) {
941:           hitT = t;
942:           hitBot = bot;
943:           hitPart = sphere.part;
944:         }
945:       }
946:     }
947:     const muzzle = this.muzzlePosition();
948:     const hitPoint = origin.clone().addScaledVector(direction, Math.min(hitT, maxRange));
949:     this.addTracer(muzzle, hitPoint);
950:     if (hitBot) {
951:       const headshot = hitPart === 'head';
952:       const legMultiplier = hitPart === 'legs' ? 0.72 : 1;
953:       const falloff = clamp(1 - (hitT / maxRange) * 0.3, 0.7, 1);
954:       const damage = weapon.damage * (headshot ? weapon.headMultiplier : legMultiplier) * falloff;
955:       const killed = hitBot.takeDamage(damage);
956:       this.spawnImpact(hitPoint, headshot ? 0xff9a6a : 0xc99a6b, 6);
957:       this.ui.hitmarker(headshot);
958:       audio.hitmarker(headshot);
959:       if (killed) {
960:         this.registerKill(player, hitBot, weapon.id, headshot);
961:       } else {
962:         // Being shot should alert the bot without giving it perfect knowledge.
963:         hitBot.hear(player.position, player.team);
964:       }
965:       this.makeNoise(player.position, player.team);
966:     } else {
967:       this.spawnImpact(hitPoint, 0xffc27d, 4);
968:       audio.impact();
969:       this.makeNoise(player.position, player.team);
970:     }
971:     const distance = this.player ? player.position.distanceTo(this.player.position) : 0;
972:     audio.gunshot(weapon.id, distance);
973:     this.checkEndConditions();
974:   }
975: 
976:   botShoot(bot, target, difficulty) {
977:     if (!this.active || this.results || !bot.alive || !target?.alive) return;
978:     const origin = new THREE.Vector3(bot.position.x, bot.position.y + 1.5, bot.position.z);
979:     const isPlayer = target === this.player;
980:     const targetY = target.position.y + (isPlayer ? (target.crouched ? 0.9 : 1.15) : 1.2);
981:     const targetPoint = new THREE.Vector3(target.position.x, targetY, target.position.z);
982:     const distance = origin.distanceTo(targetPoint);
983:     const baseDir = targetPoint.clone().sub(origin).normalize();
984:     const right = new THREE.Vector3().crossVectors(baseDir, new THREE.Vector3(0, 1, 0)).normalize();
985:     const up = new THREE.Vector3().crossVectors(right, baseDir).normalize();
986:     const movePenalty = bot.currentSpeed > 1 ? 1.35 : 1;
987:     const spread = (difficulty.aimSpread / Math.max(0.5, bot.skill.accuracy)) * movePenalty;
988:     const direction = baseDir.clone()
989:       .addScaledVector(right, rand(-1, 1) * spread)
990:       .addScaledVector(up, rand(-1, 1) * spread)
991:       .normalize();
992:     const maxRange = 80;
993:     const end = origin.clone().addScaledVector(direction, maxRange);
994:     const wallT = this.mapRuntime.world.segmentHitFraction(origin, end);
995:     let wallDistance = wallT === null ? maxRange : Math.min(maxRange, wallT * maxRange);
996:     if (direction.y < -0.001) {
997:       const groundDistance = -origin.y / direction.y;
998:       if (groundDistance > 0 && groundDistance < wallDistance) wallDistance = groundDistance;
999:     }
1000:     let hitT = wallDistance;
1001:     let hitPart = null;
1002:     const spheres = isPlayer
1003:       ? [
1004:           { x: target.position.x, y: target.position.y + (target.crouched ? 1.1 : 1.62), z: target.position.z, r: 0.2, part: 'head' },
1005:           { x: target.position.x, y: target.position.y + (target.crouched ? 0.7 : 1.1), z: target.position.z, r: 0.37, part: 'body' },
1006:           { x: target.position.x, y: target.position.y + 0.43, z: target.position.z, r: 0.3, part: 'legs' },
1007:         ]
1008:       : [
1009:           { x: target.position.x, y: target.position.y + 1.68, z: target.position.z, r: 0.22, part: 'head' },
1010:           { x: target.position.x, y: target.position.y + 1.2, z: target.position.z, r: 0.36, part: 'body' },
1011:           { x: target.position.x, y: target.position.y + 0.72, z: target.position.z, r: 0.32, part: 'legs' },
1012:         ];
1013:     for (const sphere of spheres) {
1014:       const t = raySphere(origin, direction, sphere, sphere.r);
1015:       if (t !== null && t < hitT) { hitT = t; hitPart = sphere.part; }
1016:     }
1017:     const hitPoint = origin.clone().addScaledVector(direction, Math.min(hitT, maxRange));
1018:     this.addTracer(origin, hitPoint, 0xffb56e);
1019:     const distToPlayer = this.player ? origin.distanceTo(this.player.position) : 0;
1020:     audio.gunshot('rifle', distToPlayer);
1021:     bot.character.muzzle();
1022:     this.makeNoise(bot.position, bot.team);
1023:     if (hitPart) {
1024:       const damage = 8.6 * difficulty.damageScale * (hitPart === 'head' ? 1.4 : hitPart === 'legs' ? 0.8 : 1);
1025:       if (isPlayer) {
1026:         const killed = target.takeDamage(damage, bot.position, this);
1027:         this.ui.damage(new THREE.Vector3().subVectors(bot.position, target.position), damage / 20);
1028:         if (killed) {
1029:           this.registerKill(bot, target, 'rifle', hitPart === 'head');
1030:           this.ui.banner('YOU WERE ELIMINATED', 1800);
1031:         }
1032:       } else {
1033:         const falloff = clamp(1 - distance / 130, 0.65, 1);
1034:         const killed = target.takeDamage(damage * falloff);
1035:         if (killed) this.registerKill(bot, target, 'rifle', hitPart === 'head');
1036:       }
1037:     } else {
1038:       this.spawnImpact(hitPoint, 0xffc27d, 3);
1039:     }
1040:     this.checkEndConditions();
1041:   }
1042: 
1043:   makeNoise(position, sourceTeam) {
1044:     for (const bot of this.bots) {
1045:       if (!bot.alive) continue;
1046:       if (distance2D(bot.position, position) < 26) bot.hear(position, sourceTeam);
1047:     }
1048:   }
1049: 
1050:   alertTeam(source, target) {
1051:     if (this.mode === 'ffa' || !target) return;
1052:     const now = this.elapsed;
1053:     const key = source.team;
1054:     if ((this.alertCooldown.get(key) || 0) > now) return;
1055:     this.alertCooldown.set(key, now + 1.2);
1056:     for (const bot of this.bots) {
1057:       if (bot === source || !bot.alive || bot.team !== source.team) continue;
1058:       if (distance2D(bot.position, source.position) < 34) {
1059:         bot.receiveAlert(target.position, source.team);
1060:       }
1061:     }
1062:   }
