await page.goto('http://127.0.0.1:3002/', { waitUntil: 'networkidle' });
await page.waitForTimeout(1500);
await page.evaluate(() => document.querySelector('button[data-action="play"]').click());
await page.waitForTimeout(1000);
const snap = () => page.evaluate(() => {
  const g = window.game;
  return {
    active: g.active, paused: g.paused, results: g.results,
    keys: { ...g.keys }, pointer: !!document.pointerLockElement,
    focus: document.hasFocus(), visibility: document.visibilityState,
    pos: { x: g.player.position.x, y: g.player.position.y, z: g.player.position.z },
    vel: { x: g.player.velocity.x, y: g.player.velocity.y, z: g.player.velocity.z },
    eye: g.player.eye, grounded: g.player.grounded,
    timeLeft: g.timeLeft, pausePanel: document.querySelector('#pause-panel').className,
  };
});
console.log('start', await snap());
await page.keyboard.down('KeyW');
await page.waitForTimeout(300);
console.log('after 300ms', await snap());
await page.waitForTimeout(600);
console.log('after 900ms', await snap());
await page.keyboard.up('KeyW');
await page.waitForTimeout(100);
console.log('after release', await snap());
await page.keyboard.down('Space');
await page.waitForTimeout(250);
console.log('jump 250ms', await snap());
await page.waitForTimeout(400);
console.log('jump 650ms', await snap());
await page.keyboard.up('Space');
await page.waitForTimeout(800);
console.log('landed', await snap());
await browser.close();

import { chromium } from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright/index.mjs';

const browser = await chromium.launch({
  executablePath: '/usr/bin/chromium',
  headless: true,
  args: ['--no-sandbox', '--disable-dev-shm-usage', '--use-gl=swiftshader', '--enable-unsafe-swiftshader'],
});
const page = await browser.newPage({ viewport: { width: 1024, height: 640 } });
const logs = [];
const errors = [];
page.on('console', (msg) => {
  const text = `${msg.type()}: ${msg.text()}`;
  logs.push(text);
  if (msg.type() === 'error') errors.push(text);
});
page.on('pageerror', (err) => errors.push(`pageerror: ${err.stack}`));

const results = [];
function check(name, pass, detail = '') {
  results.push({ name, pass: Boolean(pass), detail });
  console.log(`${pass ? 'PASS' : 'FAIL'} ${name}${detail ? ' — ' + detail : ''}`);
}
const sleep = (ms) => page.waitForTimeout(ms);
const get = (fn, arg) => page.evaluate(fn, arg);
const state = () => get(() => window.__TACTICAL__.state());
const click = (selector) => get((sel) => document.querySelector(sel)?.click(), selector);
// Deterministic simulation tick. The headless software renderer is far slower
// than a real GPU, so hold inputs and advance the same game update loop manually.
const tick = (seconds, dt = 0.016) => get(({ seconds, dt }) => {
  const steps = Math.ceil(seconds / dt);
  for (let i = 0; i < steps; i++) window.__TACTICAL__.game.update(dt);
  return window.__TACTICAL__.state();
}, { seconds, dt });
const setKeys = (keys) => get((keys) => { window.__TACTICAL__.game.keys = { ...keys }; }, keys);
const clearBots = () => get(() => {
  const g = window.__TACTICAL__.game;
  for (const b of g.bots) {
    b.alive = false;
    b.respawnTimer = 999;
    b.position.set(30, 0, 30);
    b.velocity.set(0, 0, 0);
    b.state = 'idle';
    b.target = null;
    b.fireTimer = 999;
  }
});

await page.goto('http://127.0.0.1:3002/', { waitUntil: 'networkidle' });
await sleep(1600);
// Lower render cost for the software-rendered browser session.
await get(() => {
  window.__TACTICAL__.game.settings.update({ quality: 'low', resolutionScale: 0.6, shadows: false });
  window.__TACTICAL__.game.applySettings();
});

// --- boot / menu -----------------------------------------------------------
check('boot has no page errors', errors.length === 0, errors.join(' | '));
check('menu visible', await get(() => document.querySelector('#menu-screen').classList.contains('visible')));
check('menu buttons present', await get(() => document.querySelectorAll('#menu-screen button[data-action]').length) >= 6);

// --- quick start -----------------------------------------------------------
await click('button[data-action="play"]');
await sleep(1000);
let s = await state();
check('quick start active', s.active === true && !s.paused && !s.results, JSON.stringify({ active: s.active, paused: s.paused }));
check('quick start TDM / Old Quarter / 8 bots', s.mode === 'tdm' && s.map === 'old_quarter' && s.bots.length === 8, JSON.stringify({ mode: s.mode, map: s.map, bots: s.bots.length }));
check('nav graph connected', s.nav?.components === 1, JSON.stringify(s.nav));
const teamCounts = { CT: 1 + s.bots.filter((b) => b.team === 'CT').length, T: s.bots.filter((b) => b.team === 'T').length };
check('TDM teams differ by at most one player', Math.abs(teamCounts.CT - teamCounts.T) <= 1, JSON.stringify(teamCounts));
check('HUD visible', await get(() => !document.querySelector('#hud').classList.contains('hidden')));

// keyboard listener populates input state
await clearBots();
await page.keyboard.down('KeyW');
await sleep(80);
const keyCaptured = await get(() => window.__TACTICAL__.game.keys.KeyW === true);
await page.keyboard.up('KeyW');
check('keyboard input reaches controller', keyCaptured);

// --- movement --------------------------------------------------------------
await get(() => { window.__TACTICAL__.game.player.position.set(0, 0, 34); window.__TACTICAL__.game.player.yaw = 0; window.__TACTICAL__.game.player.velocity.set(0, 0, 0); });
await setKeys({ KeyW: true });
const walkState = await tick(0.9);
const walkDist = Math.hypot(walkState.player.pos.x, walkState.player.pos.z - 34);
check('WASD movement moves player', walkDist > 3, `moved ${walkDist.toFixed(2)}m in 0.9s sim`);

// collision against east boundary wall
await get(() => {
  const g = window.__TACTICAL__.game;
  g.player.position.set(37.4, 0, 0);
  g.player.yaw = -Math.PI / 2; // face +X
  g.player.pitch = 0;
  g.player.velocity.set(0, 0, 0);
});
await setKeys({ KeyW: true });
const wallState = await tick(1.2);
check('collision keeps player inside wall', wallState.player.pos.x < 38.75, `x=${wallState.player.pos.x.toFixed(2)}`);

// jump and gravity
await get(() => {
  const g = window.__TACTICAL__.game;
  g.player.position.set(0, 0, 30);
  g.player.yaw = 0;
  g.player.velocity.set(0, 0, 0);
  g.player.grounded = true;
});
await setKeys({ Space: true });
const jumpState = await tick(0.22);
await setKeys({});
const landState = await tick(1.5);
check('jump leaves the ground', jumpState.player.pos.y > 0.5, `apex sample y=${jumpState.player.pos.y.toFixed(2)}`);
check('gravity returns player to ground', Math.abs(landState.player.pos.y) < 0.02 && landState.player.alive, `landed y=${landState.player.pos.y.toFixed(2)}`);

// sprint vs walk
async function runDistance(keys, seconds = 0.7) {
  await get(() => {
    const g = window.__TACTICAL__.game;
    g.player.position.set(0, 0, 30);
    g.player.yaw = 0;
    g.player.velocity.set(0, 0, 0);
    g.player.grounded = true;
  });
  await setKeys(keys);
  const st = await tick(seconds);
  const dist = Math.hypot(st.player.pos.x, st.player.pos.z - 30);
  return dist;
}
const walkDist2 = await runDistance({ KeyW: true });
const sprintDist = await runDistance({ ShiftLeft: true, KeyW: true });
check('sprint exceeds walk speed', sprintDist > walkDist2 * 1.15, `walk ${walkDist2.toFixed(2)}m, sprint ${sprintDist.toFixed(2)}m`);

// crouch changes eye height
await setKeys({ ControlLeft: true });
const crouchState = await tick(0.6);
const crouchEye = await get(() => window.__TACTICAL__.game.player.eye);
await setKeys({});
const standState = await tick(0.6);
const standEye = await get(() => window.__TACTICAL__.game.player.eye);
check('crouch lowers eye height', crouchEye < standEye - 0.3, `crouch ${crouchEye.toFixed(2)}, stand ${standEye.toFixed(2)}`);

// --- weapons, reload, ammo, HUD -------------------------------------------
await get(() => {
  const g = window.__TACTICAL__.game;
  g.player.alive = true;
  g.player.health = 100;
  g.player.fireCooldown = 0;
  g.player.reloadTimer = 0;
});
await page.keyboard.press('Digit2');
await sleep(500);
s = await state();
check('weapon switch to pistol', s.player.weapon === 'pistol', s.player.weapon);
const pistolAmmoBefore = (await state()).player.ammo.mag;
await get(() => window.__TACTICAL__.game.player.fire(window.__TACTICAL__.game));
await sleep(150);
const pistolAmmoAfter = (await state()).player.ammo.mag;
check('firing consumes ammo', pistolAmmoAfter === pistolAmmoBefore - 1, `${pistolAmmoBefore} -> ${pistolAmmoAfter}`);
await get(() => {
  const g = window.__TACTICAL__.game;
  g.player.ammo.pistol.mag = 2;
  g.player.reloadTimer = 0;
  g.player.startReload();
});
await tick(1.5);
const pistolReloaded = (await state()).player.ammo;
check('reload refills magazine from reserve', pistolReloaded.mag === 12 && pistolReloaded.reserve < 60, JSON.stringify(pistolReloaded));
check('HUD ammo matches player ammo', await get(() => document.querySelector('#ammo-value').textContent) === '12');

// --- shooting and kill scoring --------------------------------------------
await get(() => {
  const g = window.__TACTICAL__.game;
  for (const b of g.bots) {
    b.alive = true;
    b.position.set(20, 0, 38);
    b.velocity.set(0, 0, 0);
    b.state = 'idle';
    b.stateTimer = 999;
    b.fireTimer = 999;
    b.target = null;
    b.targetVisible = false;
  }
  const p = g.player;
  p.position.set(0, 0, 38);
  p.velocity.set(0, 0, 0);
  p.yaw = 0;
  p.pitch = 0;
  p.weaponId = 'rifle';
  p.fireCooldown = 0;
  p.ammo.rifle = { mag: 30, reserve: 120 };
  const target = g.bots[0];
  target.position.set(0, 0, 30);
  target.health = 100;
  target.alive = true;
  target.character.setPosition(0, 0, 30);
  target.target = null;
  p.updateCamera(0, 0);
});
await get(() => window.__TACTICAL__.game.player.fire(window.__TACTICAL__.game));
await get(() => { window.__TACTICAL__.game.player.fireCooldown = 0; });
await sleep(100);
await get(() => window.__TACTICAL__.game.player.fire(window.__TACTICAL__.game));
await sleep(300);
s = await state();
check('shots damage the bot', s.bots[0].health < 100, `health ${s.bots[0].health}`);
check('bot death awards player kill', s.player.kills >= 1, `kills ${s.player.kills}`);
check('TDM score incremented', s.scores.CT >= 1, JSON.stringify(s.scores));
check('kill feed populated', await get(() => document.querySelectorAll('#kill-feed .kill-row').length) > 0);

// --- scoreboard ------------------------------------------------------------
await page.keyboard.down('Tab');
await sleep(150);
check('scoreboard opens on Tab', await get(() => !document.querySelector('#scoreboard').classList.contains('hidden')));
await page.keyboard.up('Tab');
await sleep(100);
check('scoreboard hides on Tab release', await get(() => document.querySelector('#scoreboard').classList.contains('hidden')));

// --- pause / resume --------------------------------------------------------
await get(() => window.__TACTICAL__.game.pause());
await sleep(150);
check('pause opens pause panel', (await state()).paused && await get(() => !document.querySelector('#pause-panel').classList.contains('hidden')));
await click('#pause-panel button[data-action="resume"]');
await sleep(300);
check('resume closes pause panel', !(await state()).paused && await get(() => document.querySelector('#pause-panel').classList.contains('hidden')));

// --- death / respawn -------------------------------------------------------
await get(() => window.__TACTICAL__.damagePlayer(1000));
await sleep(250);
s = await state();
check('lethal damage kills player', s.player.alive === false && s.player.health === 0, JSON.stringify({ alive: s.player.alive, health: s.player.health }));
check('respawn overlay visible', await get(() => !document.querySelector('#respawn-panel').classList.contains('hidden')));
await tick(4.2);
s = await state();
check('player respawns with full health', s.player.alive === true && s.player.health === 100, JSON.stringify({ alive: s.player.alive, health: s.player.health }));

// --- results / career persistence -----------------------------------------
await get(() => window.__TACTICAL__.forceEnd());
await sleep(350);
s = await state();
check('results screen appears', s.results && await get(() => !document.querySelector('#results-panel').classList.contains('hidden')));
check('results screen contains stats', await get(() => document.querySelector('#results-content').textContent.includes('KILLS')));
const career = await get(() => JSON.parse(localStorage.getItem('tacticalfps.profile.v2')));
check('career stats persisted locally', career.matches >= 1, JSON.stringify(career));

// --- play again ------------------------------------------------------------
await click('#results-panel button[data-action="play-again"]');
await sleep(900);
s = await state();
check('play again restarts match', s.active && !s.results && s.player.kills === 0 && s.timeLeft > 150, JSON.stringify({ active: s.active, results: s.results, kills: s.player.kills, time: Math.round(s.timeLeft) }));

// --- new match setup: industrial FFA --------------------------------------
await get(() => window.__TACTICAL__.game.leaveMatch());
await sleep(300);
await click('button[data-action="setup"]');
await sleep(180);
await get(() => {
  const map = document.querySelector('#cfg-map');
  map.value = 'industrial';
  map.dispatchEvent(new Event('change'));
  document.querySelector('#cfg-mode').value = 'ffa';
  document.querySelector('#cfg-mode').dispatchEvent(new Event('change'));
  document.querySelector('#cfg-bots').value = '6';
  document.querySelector('#cfg-difficulty').value = 'Hard';
  document.querySelector('#cfg-time').value = '120';
  document.querySelector('#cfg-score').value = '15';
});
await click('button[data-action="start-match"]');
await sleep(1100);
s = await state();
check('industrial map loads', s.map === 'industrial', s.map);
check('FFA mode loads with 6 bots', s.mode === 'ffa' && s.bots.length === 6, JSON.stringify({ mode: s.mode, bots: s.bots.length }));
check('FFA bots all independent', s.bots.every((b) => b.team === 'FFA'));
check('industrial nav connected', s.nav?.components === 1, JSON.stringify(s.nav));
const spawns = [s.player.pos, ...s.bots.map((b) => b.pos)];
const distinctSpawns = new Set(spawns.map((p) => `${p.x.toFixed(1)},${p.z.toFixed(1)}`)).size;
check('spawn points are distinct', distinctSpawns >= spawns.length - 1, `${distinctSpawns}/${spawns.length} distinct`);
check('FFA HUD rank display', (await get(() => document.querySelector('#match-score-label').textContent)).includes('RANK'));

// --- bots actually move / fight -------------------------------------------
const botSnapshot = s.bots.map((b) => ({ ...b.pos }));
const afterAi = await tick(2.5, 0.033);
let botMoved = 0;
for (let i = 0; i < afterAi.bots.length; i++) {
  if (Math.hypot(afterAi.bots[i].pos.x - botSnapshot[i].x, afterAi.bots[i].pos.z - botSnapshot[i].z) > 0.4) botMoved++;
}
check('bots navigate around the map', botMoved >= 3, `${botMoved}/${afterAi.bots.length} moved >0.4m in 2.5s sim`);

// --- time-limit completion ------------------------------------------------
await get(() => { window.__TACTICAL__.game.timeLeft = 0.25; });
await sleep(800);
s = await state();
check('time limit ends the match', s.results === true, JSON.stringify({ results: s.results, timeLeft: s.timeLeft }));

// --- settings and profile persistence -------------------------------------
await get(() => window.__TACTICAL__.game.leaveMatch());
await sleep(300);
await click('button[data-action="settings"]');
await sleep(150);
await get(() => {
  const set = (id, value, event = 'input') => {
    const el = document.querySelector(id);
    el.value = value;
    el.dispatchEvent(new Event(event));
  };
  set('#set-sensitivity', '1.65');
  set('#set-fov', '88');
  set('#set-master', '0.35');
  set('#set-music', '0.1');
  set('#set-quality', 'low', 'change');
  set('#set-resolution', '0.75');
  document.querySelector('#set-fps').checked = true;
  document.querySelector('#set-invert').checked = true;
});
await click('#panel-screen button[data-action="save-settings"]');
await sleep(500);
const savedSettings = await get(() => JSON.parse(localStorage.getItem('tacticalfps.settings.v2')));
const applied = await get(() => ({
  pixelRatio: window.__TACTICAL__.game.renderer.getPixelRatio(),
  shadows: window.__TACTICAL__.game.renderer.shadowMap.enabled,
  fpsVisible: !document.querySelector('#fps-counter').classList.contains('hidden'),
}));
check('settings saved to local storage', savedSettings.sensitivity === 1.65 && savedSettings.fov === 88 && savedSettings.quality === 'low', JSON.stringify(savedSettings));
check('render scale applied to renderer', applied.pixelRatio <= 0.85, `pixelRatio ${applied.pixelRatio}`);
check('FPS counter setting applied', applied.fpsVisible === true);

await click('button[data-action="profile"]');
await sleep(150);
await get(() => { document.querySelector('#profile-name').value = 'TestOperator'; document.querySelector('#profile-team').value = 'T'; });
await click('#panel-screen button[data-action="save-profile"]');
await sleep(200);
const savedProfile = await get(() => JSON.parse(localStorage.getItem('tacticalfps.profile.v2')));
check('profile saved to local storage', savedProfile.name === 'TestOperator' && savedProfile.team === 'T', JSON.stringify(savedProfile));

// reload and confirm persistence
await page.reload({ waitUntil: 'networkidle' });
await sleep(1400);
const afterReload = await get(() => ({
  profile: JSON.parse(localStorage.getItem('tacticalfps.profile.v2')),
  settings: JSON.parse(localStorage.getItem('tacticalfps.settings.v2')),
  menu: document.querySelector('#menu-screen').classList.contains('visible'),
  pixelRatio: window.__TACTICAL__.game.renderer.getPixelRatio(),
}));
check('settings survive reload', afterReload.settings.sensitivity === 1.65 && afterReload.settings.fov === 88);
check('profile survives reload', afterReload.profile.name === 'TestOperator' && afterReload.profile.team === 'T');
check('menu returns after reload', afterReload.menu === true);

// --- online status is honest ----------------------------------------------
await click('button[data-action="servers"]');
await sleep(150);
const onlineText = await get(() => document.querySelector('#panel-screen').textContent);
check('online panel labels services unavailable', onlineText.includes('ONLINE SERVICES UNAVAILABLE') && onlineText.includes('offline'));
check('no fake server rows shown', !/server #|ping|players online/i.test(onlineText));
await page.screenshot({ path: '/tmp/opencode/online-info.jpg', type: 'jpeg', quality: 70 });
await click('#panel-screen [data-close]');
await sleep(200);

// --- screenshots ----------------------------------------------------------
await get(() => window.__TACTICAL__.game.startMatch({ mapId: 'industrial', mode: 'tdm', botCount: 8, difficulty: 'Normal', team: 'CT', timeLimit: 180, scoreLimit: 25 }));
await sleep(1400);
await page.screenshot({ path: '/tmp/opencode/industrial.jpg', type: 'jpeg', quality: 70 });
await get(() => window.__TACTICAL__.game.startMatch({ mapId: 'old_quarter', mode: 'tdm', botCount: 8, difficulty: 'Normal', team: 'CT', timeLimit: 180, scoreLimit: 25 }));
await sleep(1400);
await page.screenshot({ path: '/tmp/opencode/oldquarter.jpg', type: 'jpeg', quality: 70 });

// runtime errors during the whole session
const serious = errors.filter((e) => !e.includes('ReadPixels') && !e.includes('GL Driver Message'));
check('no runtime errors during test session', serious.length === 0, serious.join(' | '));

const passed = results.filter((r) => r.pass).length;
console.log(`\nSUMMARY ${passed}/${results.length} checks passed`);
if (serious.length) console.log('ERRORS:', serious.join('\n'));
await browser.close();
if (passed !== results.length) process.exitCode = 1;

