import { chromium } from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright/index.mjs';

const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox', '--disable-dev-shm-usage', '--use-gl=swiftshader', '--enable-unsafe-swiftshader'] });
const page = await browser.newPage({ viewport: { width: 900, height: 560 } });
const errors = [];
page.on('console', (m) => { if (m.type() === 'error' && !m.text().includes('ReadPixels')) errors.push(m.text()); });
page.on('pageerror', (e) => errors.push(e.stack));
const results = [];
const check = (name, pass, detail = '') => { results.push({ name, pass: !!pass, detail }); console.log(`${pass ? 'PASS' : 'FAIL'} ${name}${detail ? ' — ' + detail : ''}`); };
const get = (fn, arg) => page.evaluate(fn, arg);
const state = () => get(() => window.__TACTICAL__.state());
const tick = (seconds, dt = 0.033) => get(({ seconds, dt }) => { const g = window.__TACTICAL__.game; for (let i = 0; i < Math.ceil(seconds / dt); i++) g.update(dt); return window.__TACTICAL__.state(); }, { seconds, dt });

await page.goto('http://127.0.0.1:3002/', { waitUntil: 'networkidle' });
await page.waitForTimeout(1200);
await get(() => { const g = window.__TACTICAL__.game; g.settings.update({ quality: 'low', resolutionScale: 0.6, shadows: false }); g.applySettings(); });

// --- hard FFA long simulation --------------------------------------------
await get(() => window.__TACTICAL__.game.startMatch({ mapId: 'industrial', mode: 'ffa', botCount: 8, difficulty: 'Hard', team: 'CT', timeLimit: 180, scoreLimit: 40 }));
await page.waitForTimeout(500);
let s = await state();
check('Hard difficulty is assigned to bots', await get(() => window.__TACTICAL__.game.bots.every((b) => b.difficultyName === 'Hard' && b.difficulty.damageScale === 1)));
const before = s.bots.map((b) => ({ ...b.pos }));
const after = await tick(20, 0.033);
const invalid = await get(() => {
  const g = window.__TACTICAL__.game;
  return g.bots.filter((b) => {
    if (!Number.isFinite(b.position.x) || !Number.isFinite(b.position.z) || !Number.isFinite(b.position.y)) return true;
    if (b.position.y < -1 || b.position.y > 8) return true;
    if (b.world.collidesCircle(b.position.x, b.position.z, 0.3, b.position.y + 0.5, b.position.y + 1.6)) return true;
    return false;
  }).map((b) => b.name);
});
check('bots remain finite and out of solid geometry after 20s', invalid.length === 0, invalid.join(','));
let traveled = 0;
for (let i = 0; i < after.bots.length; i++) traveled += Math.hypot(after.bots[i].pos.x - before[i].x, after.bots[i].pos.z - before[i].z);
check('bots keep navigating over 20 seconds', traveled > 30, `total travel ${traveled.toFixed(1)}m`);
const combatCounts = after.bots.reduce((n, b) => n + b.kills + b.deaths, 0);
check('bot combat produces score events', combatCounts > 0, `${combatCounts} kill/death events`);
check('match survived long simulation', after.results === false && after.active === true);

