  g.bots[0].deaths = 2;
  for (let i = 1; i < g.bots.length; i++) { g.bots[i].kills = 1; g.bots[i].deaths = 3; }
  g.endMatch('qa tie');
});
await page.waitForTimeout(200);
const tieText = await get(() => document.querySelector('#results-content').textContent);
check('FFA equal top scores produce a draw', tieText.includes('DRAW') && tieText.includes('no outright winner'), tieText.slice(0, 120).replace(/\s+/g, ' '));

// --- TDM victory and defeat ----------------------------------------------
await get(() => window.__TACTICAL__.game.startMatch({ mapId: 'old_quarter', mode: 'tdm', botCount: 4, difficulty: 'Normal', team: 'CT', timeLimit: 180, scoreLimit: 25 }));
await page.waitForTimeout(400);
await get(() => { const g = window.__TACTICAL__.game; g.scores.CT = 12; g.scores.T = 4; g.endMatch('qa'); });
await page.waitForTimeout(200);
let text = await get(() => document.querySelector('#results-content').textContent);
