await get(() => window.__TACTICAL__.game.startMatch({ mapId: 'old_quarter', mode: 'tdm', botCount: 4, difficulty: 'Easy', team: 'CT', timeLimit: 180, scoreLimit: 25 }));
await page.waitForTimeout(400);
