const materialDefs = {
  plaster: { texture: 'plaster', roughness: 0.96, uv: 0.3 },
  brick: { texture: 'brick', roughness: 0.95, uv: 0.45 },
  concrete: { texture: 'concrete', roughness: 0.98, uv: 0.3 },
