  brass: { color: 0xa58a4d, roughness: 0.35, metalness: 0.6 },
  fabric: { color: 0x6e6a55, roughness: 1 },
  redCloth: { color: 0x7d3d31, roughness: 1 },
  paintWhite: { color: 0xbebbaa, roughness: 0.9 },
