import { chromium } from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright/index.mjs';
const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox', '--disable-dev-shm-usage', '--use-gl=swiftshader', '--enable-unsafe-swiftshader'] });
const page = await browser.newPage({ viewport: { width: 900, height: 560 } });
const errors = [];
page.on('console', (m) => { if (m.type() === 'error' && !m.text().includes('ReadPixels')) errors.push(m.text()); });
page.on('pageerror', (e) => errors.push(e.stack));
const results = [];
const check = (name, pass, detail = '') => { results.push({ name, pass: !!pass, detail }); console.log(`${pass ? 'PASS' : 'FAIL'} ${name}${detail ? ' — ' + detail : ''}`); };
const get = (fn, arg) => page.evaluate(fn, arg);
const state = () => get(() => window.__TACTICAL__.state());
const tick = (seconds, dt = 0.033) => get(({ seconds, dt }) => { const g = window.__TACTICAL__.game; for (let i = 0; i < Math.ceil(seconds / dt); i++) g.update(dt); return window.__TACTICAL__.state(); }, { seconds, dt });

await page.goto('http://127.0.0.1:3002/', { waitUntil: 'networkidle' });
await page.waitForTimeout(1100);
await get(() => { const g = window.__TACTICAL__.game; g.settings.update({ quality: 'low', resolutionScale: 0.6, shadows: false }); g.applySettings(); });
await get(() => window.__TACTICAL__.game.startMatch({ mapId: 'old_quarter', mode: 'tdm', botCount: 4, difficulty: 'Normal', team: 'CT', timeLimit: 180, scoreLimit: 5 }));
await page.waitForTimeout(500);

// --- wall/map geometry blocks player bullets ------------------------------
await get(() => {
  const g = window.__TACTICAL__.game;
  for (const b of g.bots) { b.alive = false; b.respawnTimer = 999; b.position.set(30, 0, 30); b.fireTimer = 999; }
  const target = g.bots.find((b) => b.team === 'T');
  target.alive = true;
  target.position.set(0, 0, -10);
  target.health = 100;
  target.character.setPosition(0, 0, -10);
  const p = g.player;
  p.position.set(0, 0, 10);
  p.velocity.set(0, 0, 0);
  p.yaw = 0;
  p.pitch = 0;
  p.weaponId = 'rifle';
  p.fireCooldown = 0;
  p.ammo.rifle = { mag: 30, reserve: 120 };
  p.updateCamera(0, 0);
  window.__wallTarget = target.name;
});
await get(() => window.__TACTICAL__.game.player.fire(window.__TACTICAL__.game));
await page.waitForTimeout(200);
let s = await state();
let t = s.bots.find((b) => b.name === (await get(() => window.__wallTarget)));
check('central fountain blocks player shots', t.health === 100, `target health ${t.health}`);

// --- friendly fire is disabled -------------------------------------------
await get(() => {
  const g = window.__TACTICAL__.game;
  for (const b of g.bots) { b.alive = false; b.respawnTimer = 999; }
  const friend = g.bots.find((b) => b.team === 'CT');
  friend.alive = true;
  friend.position.set(2, 0, 30);
  friend.health = 100;
  friend.character.setPosition(2, 0, 30);
  const p = g.player;
  p.position.set(2, 0, 38);
  p.velocity.set(0, 0, 0);
  p.yaw = 0;
  p.pitch = 0;
  p.fireCooldown = 0;
  p.ammo.rifle = { mag: 30, reserve: 120 };
  p.updateCamera(0, 0);
  window.__friendName = friend.name;
});
await get(() => window.__TACTICAL__.game.player.fire(window.__TACTICAL__.game));
await page.waitForTimeout(200);
s = await state();
t = s.bots.find((b) => b.name === (await get(() => window.__friendName)));
check('friendly fire does not damage teammates', t.health === 100 && s.player.kills === 0, `teammate health ${t.health}, kills ${s.player.kills}`);

// --- bullets/aim cannot pass through a building ---------------------------
await get(() => {
  const g = window.__TACTICAL__.game;
  for (const b of g.bots) { b.alive = false; b.respawnTimer = 999; b.position.set(30, 0, 30); b.fireTimer = 999; }
  const bot = g.bots.find((b) => b.team === 'T');
  bot.alive = true;
  bot.position.set(-24, 0, -10); // south of the north-west building (z >= -35..-17)
  bot.health = 100;
  bot.target = g.player;
  bot.targetVisible = true;
  bot.state = 'engage';
  bot.reactionTimer = 0;
  bot.fireTimer = 0;
  bot.burstRemaining = 5;
  bot.character.setPosition(-24, 0, -10);
  const p = g.player;
  p.position.set(-24, 0, -40); // north of the same building
  p.velocity.set(0, 0, 0);
  p.health = 100;
  p.armor = 100;
  p.alive = true;
  p.yaw = 0;
  p.updateCamera(0, 0);
});
const beforeHealth = (await state()).player.health;
const afterWall = await tick(3.5);
check('bot cannot shoot through a solid building', afterWall.player.health === beforeHealth, `health ${beforeHealth} -> ${afterWall.player.health}`);

// --- score limit ends TDM ------------------------------------------------
await get(() => {
  const g = window.__TACTICAL__.game;
  g.results = false;
  g.scores.CT = 4;
  g.scores.T = 0;
  g.matchConfig.scoreLimit = 5;
  g.checkEndConditions();
});
await page.waitForTimeout(250);
s = await state();
check('TDM score limit ends the match', s.results === true && await get(() => document.querySelector('#results-content').textContent.includes('VICTORY')));

// --- pause restart button -------------------------------------------------
await get(() => window.__TACTICAL__.game.restartMatch());
await page.waitForTimeout(500);
await get(() => window.__TACTICAL__.game.pause());
await page.waitForTimeout(120);
await get(() => document.querySelector('#pause-panel button[data-action="restart"]').click());
await page.waitForTimeout(700);
s = await state();
check('pause restart starts a clean match', s.active && !s.paused && s.player.kills === 0 && s.timeLeft > 170, JSON.stringify({ active: s.active, paused: s.paused, kills: s.player.kills }));

// --- settings reset -------------------------------------------------------
await get(() => window.__TACTICAL__.game.leaveMatch());
await page.waitForTimeout(250);
await get(() => document.querySelector('button[data-action="settings"]').click());
await page.waitForTimeout(150);
await get(() => document.querySelector('#panel-screen button[data-action="reset-settings"]').click());
await page.waitForTimeout(250);
const reset = await get(() => JSON.parse(localStorage.getItem('tacticalfps.settings.v2')));
check('reset settings restores defaults', reset.sensitivity === 1 && reset.fov === 74 && reset.quality === 'medium', JSON.stringify({ sensitivity: reset.sensitivity, fov: reset.fov, quality: reset.quality }));

// --- credits panel --------------------------------------------------------
await get(() => document.querySelector('#panel-screen [data-close]').click());
await page.waitForTimeout(150);
await get(() => document.querySelector('button[data-action="credits"]').click());
await page.waitForTimeout(150);
const credits = await get(() => document.querySelector('#panel-screen').textContent);
check('credits panel opens with build information', credits.includes('CREDITS') && credits.includes('Three.js'));

check('no runtime errors during edge checks', errors.length === 0, errors.slice(0, 3).join(' | '));
const passed = results.filter((r) => r.pass).length;
console.log(`\nSUMMARY ${passed}/${results.length} checks passed`);
await browser.close();
if (passed !== results.length) process.exitCode = 1;

